INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('10683f77-3ec0-45a3-8c9d-759c12c47622', '86a61787-c618-42e8-bf50-f3f7f787cfad', NULL, NULL, NULL, NULL, NULL, 'https://dsml.ece.ntua.gr/', '2026-08-23', 'Confirmed only that this interdepartmental MSc programme (School of Electrical & Computer Engineering) exists under this title. Degree-level detail, admission GPA/English-test thresholds, and a document checklist could not be confirmed — the programme page did not render this content via direct fetch within a deliberately capped research budget for this batch.'),
    ('0f0c8f4c-5176-4260-b004-40b5a77a3f64', '30b96861-2ba4-462c-9059-9f9eedda084c', NULL, NULL, NULL, NULL, NULL, 'https://csd.auth.gr/en/', '2026-08-23', 'AUTh''s School of Informatics confirmed to offer 5 MSc programmes including "Artificial Intelligence" and "Data and Web Science" — this row covers the Artificial Intelligence title. Admission GPA/English-test thresholds and a dedicated per-programme URL could not be confirmed within a deliberately capped research budget for this batch.');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('8a52fd17-6e44-42aa-84b4-9e0327b1eed1', 'IKY Postgraduate Scholarships', 'IKY (Greek State Scholarships Foundation)', 'GR', NULL, NULL, 'PARTIAL_TUITION', NULL, 'IKY confirmed to run several postgraduate-relevant programmes, including "IKY-Fulbright," "IKY-Max Weber" (2026-2027 postgraduate call), and the "Theodorideio Bequest Scholarships for Postgraduate Studies Abroad" (2025-2026 call) — award amounts were not stated on the page fetched and are left NULL rather than guessed.', NULL, NULL, 'https://www.iky.gr/en/', '2026-08-23');

-- France / Belgium / Australia batch (added 2026-08-23), continuing toward
-- the 32-country target. Every fact below was researched live against an
-- official source on 2026-08-23. France and Belgium use EUR natively, no
-- conversion needed. Australia uses AUD, converted here using the ECB
-- reference rate 1 EUR = 1.6321 AUD (dated 2026-08-21, via
-- https://api.frankfurter.dev/v1/latest, the most recent ECB reference
-- available) — the original AUD figure and this rate are recorded in each
-- converted row's notes.
--
-- Notable real-world event disclosed rather than silently absorbed: the
-- University of South Australia (UniSA) merged into the University of
-- Adelaide on 1 January 2026, forming "Adelaide University." UniSA no
-- longer exists as an independently-applying institution (unisa.edu.au now
-- redirects to adelaide.edu.au) — seeded here as "Adelaide University" with
-- the merger context disclosed in its admission-requirements notes, rather
-- than seeding a defunct "University of South Australia" as if it still
-- accepted applications.
--
-- Deliberate omissions (same never-guess discipline as every prior batch):
--  - INSA Lyon: its main insa-lyon.fr domain blocked every direct fetch
--    attempt (repeated "socket hang up"); only its rejoindreinsalyon.com and
--    fedora.insa-lyon.fr subdomains were directly fetchable, confirming only
--    that the classical engineering track requires French fluency and that
--    detailed admission documents/deadlines are not published on that page.
--    The IBMMAE bachelor's tuition (EUR 7,300/year) and English-test score
--    could only be sourced via a WebSearch snippet of the insa-lyon.fr page,
--    not a direct fetch — per the same discipline used for University of
--    Nicosia's tuition in an earlier batch, this is omitted rather than
--    stated as a confirmed figure (left as NULL/no program_fees row).
--  - No non-EU tuition figure for Sorbonne Université: its own 2026/2027
--    fees page states EU/exempt rates but not the non-EU differentiated
--    rate; a non-EU figure exists only via a WebSearch-cited PDF that could
--    not be parsed as text, so it is omitted rather than guessed.
--  - No cost-of-living figures for Lyon or Paris: no official/government
--    page with a specific euro figure was found for either city.
--  - No accommodation row for INSA Lyon or Sorbonne: CROUS Lyon's and CROUS
--    Paris's own pages confirm the DSE allocation process but neither
--    surfaced an actual rent figure on direct fetch (only via unofficial
--    aggregator sites, excluded per this project's sourcing rule).
--  - Belgium: no nationwide financial-proof figure for the Type D student
--    visa — dofi.ibz.be and a Belgian embassy page were both directly
--    fetched but neither states a EUR subsistence figure for this specific
--    permit (a EUR 12,744 figure found only via a WebSearch snippet is
--    excluded). No accommodation row for KU Leuven (its EUR 510/537 rent
--    figures came only from a WebSearch snippet, not a direct page fetch)
--    or ULB (no rent figures confirmed at all).
--  - Australia: no visa_requirements row at all. Every homeaffairs.gov.au
--    and immi.homeaffairs.gov.au URL attempted returned HTTP 403 on direct
--    fetch; the financial-capacity and passport-validity figures exist only
--    via WebSearch snippets of those blocked pages — same discipline as the
--    earlier Slovakia/US visa omissions (all-official-sources-blocked means
--    omit the row, not seed it from an indirect source). No living-cost row
--    for Adelaide, Melbourne, or Sydney: each city's official calculator
--    page (studyaustralia.gov.au, studymelbourne.vic.gov.au) either returned
--    no static figure or a 403. No accommodation row for Victoria
--    University: only its EUR-equivalent AUD 500 deposit is officially
--    confirmed (via unilodge.com.au, VU's own named on-campus partner); no
--    official weekly rent figure was found, only third-party aggregator
--    estimates, which are excluded.

