INSERT INTO academic_programs (program_id, university_id, title, degree_level, field_of_study, duration_months, programme_url) VALUES
    ('64771b3f-5078-4815-851b-4a0ac4bbd61d', '98df8828-d483-47cc-a8ae-bac332a701d1', 'International Bachelor in Mechanical, Materials and Aerospace Engineering (IBMMAE)', 'BACHELOR', 'Mechanical, Materials and Aerospace Engineering', 36, 'https://www.insa-lyon.fr/en/international-bachelor'),
    ('cd77501a-bd5d-4945-b418-3df6d4545476', 'a29e2576-15c0-49ee-bcbc-741ee0cb026b', 'Master Nanosciences, Nanotechnologies', 'MASTER', 'Nanoscience and Nanotechnology', NULL, 'https://master-nanosciences.univ-grenoble-alpes.fr/'),
    ('6b46eb26-8af9-4276-9749-acb01f32c453', 'e457d017-81c0-401e-8d89-8494c349434c', 'International Master: From Fundamental Molecular Biosciences to Biotherapies', 'MASTER', 'Molecular and Cellular Biology', 24, 'https://sciences.sorbonne-universite.fr/en/study/degree-seeking/masters/masters-degree-molecular-and-cellular-biology-bmc/international-master'),
    ('21ba601a-0afc-4271-b65d-39042c543a4f', '76a12e43-1639-4cfd-838a-b3b2cbf95731', 'Master of Bioethics', 'MASTER', 'Bioethics', NULL, 'https://www.kuleuven.be/programmes/master-bioethics/admission-application-tuition-fee'),
    ('cb8f13fb-e2d7-4ca8-9360-2ea5dc7710d4', '5c556365-1608-4f7d-8f1b-7164750a5135', 'Master of Science in Bioinformatics', 'MASTER', 'Bioinformatics', NULL, 'https://www.masterbioinformatics.ugent.be/practical'),
    ('447fef94-1ba6-443b-ae4e-43f90bdca8d2', '15be7a4d-116b-422d-b856-df3a51b9b3e6', 'Specialized Master in Data Science, Big Data', 'MASTER', 'Data Science', 12, 'https://www.ulb.be/en/programme/ms-bgda'),
    ('641dc16d-df00-4a47-940c-be2823b353ea', 'd8d850c2-e7d1-41c3-8dbc-4460b34c0e76', 'Bachelor of Computer Science', 'BACHELOR', 'Computer Science', 36, 'https://adelaide.edu.au/study/degrees/bachelor-of-computer-science/'),
    ('3924864c-858b-4100-b87a-6b57f5be23ec', '6e483f2a-97ca-4acd-aa00-7e4f7fe55f48', 'Bachelor of Business', 'BACHELOR', 'Business', 36, 'https://www.vu.edu.au/courses/bachelor-of-business-bbns/international'),
    ('13eac1c1-ef39-4426-b69e-c248e946790a', '816628cf-77b1-4cac-a1db-49b60bca7554', 'Bachelor of Information and Communications Technology', 'BACHELOR', 'Information and Communications Technology', 36, 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-information-and-communications-technology-ict');

INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('cd50da07-8020-43e9-8fb1-dea4aa733690', '64771b3f-5078-4815-851b-4a0ac4bbd61d', NULL, NULL, NULL, NULL, NULL, 'https://www.insa-lyon.fr/en/international-bachelor', '2026-08-23', 'insa-lyon.fr blocked every direct-fetch attempt during research (repeated "socket hang up"), so no GPA, English-test score, or document checklist could be confirmed directly for IBMMAE and is left NULL rather than stated from a WebSearch snippet. What WAS directly confirmed (via the rejoindreinsalyon.com subdomain) is that INSA Lyon''s classical 5-year engineering diploma (a separate track from IBMMAE, not seeded as its own row here) requires French-language fluency from international applicants, and that its own admissions page explicitly does not publish a document checklist or deadlines, pointing instead to a downloadable "Welcome Guide."'),
    ('996c1225-7704-4a50-a238-a80f4e5a59eb', 'cd77501a-bd5d-4945-b418-3df6d4545476', NULL, NULL, NULL, 'B2 (CEFR)', NULL, 'https://master-nanosciences.univ-grenoble-alpes.fr/admission/language-requirements/language-requirements-1208127.kjsp', '2026-08-23', 'English requirement confirmed as CEFR B2: TOEFL iBT 87-109, IELTS 5.5-6.5, TOEIC 785-945, or a CAE/CPE certificate, or proof of prior study conducted in English within Europe. M1 entry requires a completed (or final-semester) bachelor''s in a science field (physics, chemistry, nanosciences, nanotechnologies, engineering, or mathematics); M2 entry requires a completed/enrolled M1 with 60 ECTS, or 4+ year bachelor''s under conditions. No numeric minimum-GPA figure or generic document checklist is published beyond this. Non-PEF-country applicants apply via the national MonMaster platform, main phase Feb 17 – Mar 16, 2026; PEF-listed countries apply via "Études en France" on an embassy-set schedule.'),
    ('303b4b0b-7fc0-4e32-ba1a-f58a2ba5420f', '6b46eb26-8af9-4276-9749-acb01f32c453', NULL, NULL, NULL, NULL, ARRAY['cover_letter', 'CV', 'english_language_certificate_or_proof_of_english_medium_study', 'transcripts', 'diplomas', 'recommendation_letter'], 'https://sciences.sorbonne-universite.fr/en/study/degree-seeking/masters/masters-degree-molecular-and-cellular-biology-bmc/international-master', '2026-08-23', 'Required documents confirmed directly: a cover letter stating specialization choice, a 1-page CV, an English certificate (TOEIC/TOEFL/Cambridge) or proof of prior English-medium study, transcripts/diplomas, and one recommendation letter. Application via eCandidat, window March 26 – June 11 (recommend applying before May), or via "Études en France" depending on country of residence. No numeric minimum-GPA figure is published on this page.'),
    ('b7a96a01-174e-48c9-a9c8-b93ac7d77afc', '21ba601a-0afc-4271-b65d-39042c543a4f', NULL, NULL, 'IELTS', '6.5', ARRAY['motivation_letter', 'academic_transcripts', 'language_test_results', 'eligibility_screening_form'], 'https://www.kuleuven.be/programmes/master-bioethics/admission-application-tuition-fee', '2026-08-23', 'IELTS 6.5 overall (Academic); TOEFL also accepted at 580 (paper) / 237 (computer) / 92 (internet-based). Prior degree required: a master''s degree in one of medicine, biology, nursing, political science, theology, philosophy, psychology, sociology, economics, or law. Deadlines: non-EEA citizens March 1; EEA citizens (or non-EEA residents already holding a valid Belgian residence permit) June 1. No numeric minimum-GPA figure is published on this page.'),
    ('4c006319-2c90-4224-831a-576acb06cea9', 'cb8f13fb-e2d7-4ca8-9360-2ea5dc7710d4', NULL, NULL, 'IELTS', '6.0', NULL, 'https://www.masterbioinformatics.ugent.be/practical', '2026-08-23', 'IELTS 6.0 overall minimum; TOEFL also accepted at 72 (internet-based) / 510 (paper). Non-EEA applicants must additionally submit a GRE score, minimum 160 quantitative reasoning. The Systems Biology track requires a minimum 10 ECTS of prior math coursework. Deadlines: April 1 for foreign students needing visa sponsorship, June 1 for foreign students who do not, end of August for Belgian students. No generic document checklist or numeric minimum-GPA figure is published on this specific page (a 3.5/4.0 GPA appears only as an eligibility bar for the separate Master Mind scholarship, not as a general admission requirement — see the scholarships table).'),
    ('a6a52909-0b99-4f53-b4fd-2e8097d227d9', '447fef94-1ba6-443b-ae4e-43f90bdca8d2', NULL, NULL, NULL, NULL, NULL, 'https://www.ulb.be/en/programme/ms-bgda', '2026-08-23', 'The programme page itself states only a qualitative bar: an existing master''s degree plus "good knowledge in computer sciences or statistics" — no numeric GPA, language-test score, or document checklist is published there. ULB''s general international-eligibility page (https://www.ulb.be/en/prepare-your-application/eligibility-requirements) additionally confirms non-EU applicants pay a EUR 200 administrative fee before their application is examined (seeded in program_fees), and that a foreign master''s-entry credential must be recognized as equivalent by the French Community of Belgium. A B2 English requirement is mentioned only via a WebSearch snippet, not a directly-fetched official page, so it is not stated here as confirmed.'),
    ('fd193ee7-76cb-4f7c-b1bf-a4368d403d7d', '641dc16d-df00-4a47-940c-be2823b353ea', NULL, NULL, 'IELTS', '6.5', ARRAY['academic_transcripts_certified_and_translated', 'english_test_results', 'passport_copy', 'subject_syllabi_for_credit_transfer'], 'https://adelaide.edu.au/study/degrees/bachelor-of-computer-science/', '2026-08-23', 'IELTS 6.5 overall, minimum 6.0 in each of Reading/Listening/Speaking/Writing. Academic entry is via completion of a secondary qualification equivalent to the South Australian Certificate of Education (SACE), or alternative pathways (Certificate IV+, or 6+ months prior higher-education study) — no numeric GPA/ATAR figure is stated for this specific course. Application must go through an official Adelaide University education agent for applicants from the Middle East, North Africa, Sub-Saharan Africa, South Asia (Bangladesh, India, Maldives, Nepal, Pakistan, Sri Lanka), the Philippines, and Latin America; other applicants may apply directly. Context: this university is the successor to the University of South Australia (UniSA), which merged into the University of Adelaide on 1 January 2026 to form "Adelaide University" — unisa.edu.au now redirects here, and current international admissions are handled entirely under the Adelaide University name.'),
    ('fa97df4f-3c82-4711-9cda-b1942655c24f', '3924864c-858b-4100-b87a-6b57f5be23ec', NULL, NULL, 'IELTS', '6.0', NULL, 'https://www.vu.edu.au/study-at-vu/how-to-apply/international-applicants/entry-requirements-for-international-students', '2026-08-23', 'IELTS 6.0 overall, no band below 6.0 (bachelor level). Alternatives: TOEFL iBT 67 overall (Listening 12 / Speaking 18 / Reading 15 / Writing 21), PTE Academic 52 overall (no section below 52), or CAE 169 overall (no band below 169); test must be within 2 years of course start. Academic entry requires a secondary qualification equivalent to an Australian Year 12 certificate — no numeric GPA/ATAR figure is stated for this specific course. No generic document checklist is published; the entry-requirements page states only conditional/course-specific items (portfolios, police checks, work-experience proof) as needed.'),
    ('29c79be4-e2d7-4cb3-93cf-68777ad56d13', '13eac1c1-ef39-4426-b69e-c248e946790a', NULL, NULL, 'IELTS', '6.5', NULL, 'https://www.westernsydney.edu.au/international/studying/entry-requirements', '2026-08-23', 'IELTS Academic 6.5 overall, minimum 6.0 in each subtest. Alternatives: TOEFL iBT 82 total (Writing 21 / Speaking 18 / Reading 13 / Listening 13), or PTE Academic 58 overall (no communicative skill below 50); test must be no more than 2 years old, and online-proctored variants (PTE Online, IELTS Online, TOEFL Home Edition, OET@Home) are explicitly NOT accepted. Admission is described as "highly competitive, on the basis of academic merit" with no numeric ATAR/GPA-equivalent figure stated for this specific course, and no generic document checklist was found on the pages fetched — applicants are directed to the online Handbook or to internationalstudy@westernsydney.edu.au instead.');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('9391e2fc-3491-4e5f-9274-eec30289ca8d', 'cd77501a-bd5d-4945-b418-3df6d4545476', 'TUITION_PER_YEAR', 'EU', 254.00, 'https://www.univ-grenoble-alpes.fr/registration-fees/registration-fees-626553.kjsp', '2026-08-23', 'Official Master-level national registration fee for 2025-2026, EU/exempt-category rate (EUR 178/year applies instead at Bachelor/Licence level, EUR 397/year at PhD level). An additional EUR 166/year applies only to students concurrently enrolled in a second qualification, not a fresh Master''s entrant. A separate CVEC national student-life contribution of EUR 105/year also applies, paid to CROUS before registration, and is not included in this figure.'),
    ('4db22ae2-9b50-4b4a-bd61-c6f2d9541fac', 'cd77501a-bd5d-4945-b418-3df6d4545476', 'TUITION_PER_YEAR', 'INTERNATIONAL', 3770.00, 'https://master-nanosciences.univ-grenoble-alpes.fr/admission/tuition-and-scholarships/tuition-and-scholarships-481102.kjsp', '2026-08-23', 'Non-EU differentiated rate as published on this specific Master Nanosciences programme page, explicitly labeled "2023-2024" — the university''s current 2025-2026 general registration-fees page states differentiated non-EU fees apply but does not itself restate the exact figure, so this older-labeled figure is included with this caveat rather than omitted outright. The source page states the fee is waivable on request. Verify the current non-EU figure directly before relying on it.'),
    ('99831eb1-9891-4188-8f8e-5fc590b67a65', '6b46eb26-8af9-4276-9749-acb01f32c453', 'TUITION_PER_YEAR', 'EU', 255.00, 'https://www.sorbonne-universite.fr/en/education/study-sorbonne-university/enrolment-procedures-and-tuition-fees', '2026-08-23', 'Official Master-level national registration fee, EU/exempt-category rate, for the 2026/2027 academic year (EUR 178/year applies instead at Bachelor/Licence level, EUR 398/year at PhD level, EUR 630/year for engineering programmes). This same page does not state the non-EU differentiated rate; a EUR 3,941/year figure exists only via a WebSearch-cited PDF regulation that could not be parsed as readable text during research, so it is omitted here rather than stated as confirmed. A separate CVEC national student-life contribution (EUR 105/year nationally) also applies and is not included in this figure.'),
    ('1d3a3e42-b944-41e9-86c5-092e9c3ba876', '21ba601a-0afc-4271-b65d-39042c543a4f', 'TUITION_PER_YEAR', 'INTERNATIONAL', 2533.10, 'https://www.kuleuven.be/programmes/master-bioethics/admission-application-tuition-fee', '2026-08-23', '2025-2026 rate. The source page states this figure applies equally to EEA and non-EEA students (no separate lower EEA rate exists for this specific programme).'),
    ('1cad89f0-98ee-415d-888c-25a808b6130f', 'cb8f13fb-e2d7-4ca8-9360-2ea5dc7710d4', 'TUITION_PER_YEAR', 'EU', 1181.40, 'https://www.ugent.be/student/en/administration/tuition/tuition-fee-master-programme-not-advanced-and-masters-programme-in-teaching.htm/tuitionmasterteacher20262027.htm', '2026-08-23', '2026-2027 official rate for EEA students (and non-EEA students paying the EEA rate under an exemption), covering a standard 60-credit course load (EUR 305.40 fixed component + EUR 14.60/credit). Reduced rates as low as EUR 139.40 apply to Flemish Community study-allowance holders and other exempt categories.'),
    ('9ed9db42-c50b-441a-a015-bb02f7291284', 'cb8f13fb-e2d7-4ca8-9360-2ea5dc7710d4', 'TUITION_PER_YEAR', 'INTERNATIONAL', 7079.40, 'https://www.ugent.be/student/en/administration/tuition/tuition-fee-master-programme-not-advanced-and-masters-programme-in-teaching.htm/tuitionmasterteacher20262027.htm', '2026-08-23', '2026-2027 official non-EEA "Tier B" rate (Sciences faculty, which Bioinformatics falls under), covering a standard 60-credit course load (EUR 305.40 fixed + EUR 31/credit + a higher Tier-B supplementary EUR 81.90/credit). This figure covers one 60-ECTS block, i.e. one standard full-time year at UGent''s usual 60-ECTS/year pace — a full multi-year programme total is not published as a single lump figure. Non-EEA students in other faculties (Arts/Law/Psychology "Tier A", or most other faculties at the standard non-EEA rate) pay a different figure.'),
    ('b343c83a-3760-4843-b9bf-560bcd783326', '447fef94-1ba6-443b-ae4e-43f90bdca8d2', 'TUITION_PER_YEAR', 'EU', 1194.00, 'https://www.ulb.be/en/enrolment/tuitions-fees', '2026-08-23', '2026-2027 official base rate applying to Bachelor''s/Master''s/Advanced Master''s students who are EU nationals or from a non-EU "exempt" country list. A EUR 50/year rate applies to continuing students beyond their first year in some categories.'),
    ('4d2e6b55-8808-441b-9468-48bfe7c106fd', '447fef94-1ba6-443b-ae4e-43f90bdca8d2', 'TUITION_PER_YEAR', 'INTERNATIONAL', 5369.00, 'https://www.ulb.be/en/enrolment/tuitions-fees', '2026-08-23', '2026-2027 official rate for non-EU students from a "non-exempt" country (EUR 1,194 base + EUR 4,175 supplement = EUR 5,369). A transitional exception keeps bachelor''s students already enrolled in 2024-2025 on the prior fee system through 2026-2027. Minimum EUR 50 due by Oct 31 to validate enrolment; remaining balance due by Feb 1.'),
    ('6fdee25c-b9ae-404b-8387-eae5eae50c1d', '447fef94-1ba6-443b-ae4e-43f90bdca8d2', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 200.00, 'https://www.ulb.be/en/prepare-your-application/eligibility-requirements', '2026-08-23', 'One-time non-refundable administrative fee charged to non-EU applicants before their application file is examined; applies university-wide, not specific to this programme.'),
    ('b9f3ecf1-d25f-4712-9295-096714472598', '641dc16d-df00-4a47-940c-be2823b353ea', 'TUITION_PER_YEAR', 'INTERNATIONAL', 33944.00, 'https://adelaide.edu.au/study/degrees/bachelor-of-computer-science/', '2026-08-23', 'Original figure: AUD 55,400/year (indicative, international student rate), converted to EUR using the ECB reference rate (1 EUR = 1.6321 AUD, 2026-08-21). Indicative 3-year total is approximately AUD 166,200 (tuition only). Verify the current AUD figure directly.'),
    ('9d7f4aca-bb26-4036-83b7-88d1cd7553ca', '641dc16d-df00-4a47-940c-be2823b353ea', 'APPLICATION_FEE', 'INTERNATIONAL', 91.91, 'https://ask.adelaideuni.edu.au/app/answers/detail/a_id/4176', '2026-08-23', 'Original figure: AUD 150 (non-refundable), converted to EUR using the ECB reference rate (1 EUR = 1.6321 AUD, 2026-08-21). Verify the current AUD figure directly.'),
    ('3fe5fded-4b0f-42d3-a3ef-ab42b96edab5', '3924864c-858b-4100-b87a-6b57f5be23ec', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 11273.82, 'https://www.vu.edu.au/courses/bachelor-of-business-bbns/international', '2026-08-23', 'Original figure: AUD 18,400/semester (2026 rate), converted to EUR using the ECB reference rate (1 EUR = 1.6321 AUD, 2026-08-21). The same page publishes a 2027 rate of AUD 19,500/semester (EUR 11,947.80 at this rate) — the 2026 figure is used here as the current one. International students must pay full tuition up front each semester. Verify the current AUD figure directly.'),
    ('02aa3289-7077-4750-aefa-229776c55205', '13eac1c1-ef39-4426-b69e-c248e946790a', 'TUITION_PER_YEAR', 'INTERNATIONAL', 22312.36, 'https://www.westernsydney.edu.au/content/dam/digital/pdf/international/wsu-international-undergraduate-fees-2025.pdf', '2026-08-23', 'Original figure: AUD 36,416/year (2025 rate, program 3639 / CRICOS 064013K, based on 80 credit points), converted to EUR using the ECB reference rate (1 EUR = 1.6321 AUD, 2026-08-21). A 2026 fee schedule exists at a separate PDF URL but its exact figure could not be extracted (the PDF did not parse cleanly during research) — this 2025 figure is the most recent one confirmed as readable text. Verify the current AUD figure directly.');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('2b070f42-7f30-4b45-8659-bd15976d4705', 'France Excellence Eiffel Scholarship Programme', 'French Ministry for Europe and Foreign Affairs (via Campus France)', 'FR', NULL, NULL, 'PARTIAL_TUITION', NULL, 'National scholarship, not tied to one university. Master''s track: for students studying in France for the first time; PhD track: requires a cotutelle/joint-supervision arrangement, in the first year of the thesis. Requires an academic average of at least 15/20 over the last 3 years. Restricted to 7 priority fields: biology/health, ecological transition, mathematics/digital science, engineering, French history/language/civilization, law/political science, and economics/management. Deadlines: Master''s Nov 28, 2025; PhD Nov 24, 2025 (for the receiving institution''s internal nomination). Stipend amount is not stated on this specific institutional page (a commonly cited national rate of ~EUR 1,181/month for Master''s and ~EUR 1,800/month for PhD appears in secondary sources only, not confirmed here as an official figure) — amount left NULL rather than guessed.', '2025-11-28', 'https://www.sorbonne-universite.fr/en/news/france-excellence-eiffel-scholarship-programme-2026/2027', 'https://www.sorbonne-universite.fr/en/news/france-excellence-eiffel-scholarship-programme-2026/2027', '2026-08-23'),
    ('14cf6c8e-506a-49f1-bc2c-fbbdc2b99152', 'Master Mind Scholarship', 'Flemish Ministry of Education and Training (via Flemish universities, including Ghent University)', 'BE', NULL, NULL, 'PARTIAL_TUITION', 10000.00, 'A national Flemish scheme (not Ghent-specific, though sourced here from Ghent University''s own page), open to students from the Global South. Requires a GPA of at least 3.5/4.0, English proficiency, and preselection by the admitting programme''s coordinator. Only about 30 scholarships are available across all participating Flemish institutions each year (roughly 6 typically go to Ghent University applicants). Deadline aligned with academic admission, around April 1.', '2026-04-01', NULL, 'https://www.ugent.be/en/research/funding/globalsouth/master-mind', '2026-08-23'),
    ('16c9978c-8cc3-4512-9185-98b113424d22', 'Adelaide Academic Excellence Scholarship', 'Adelaide University', 'AU', 'd8d850c2-e7d1-41c3-8dbc-4460b34c0e76', '641dc16d-df00-4a47-940c-be2823b353ea', 'PARTIAL_TUITION', 16972.00, 'Automatically assessed on application (no separate form required beyond the standard application); requires a high-distinction academic average. Grants a 50% tuition-fee reduction. Amount shown here is 50% of this specific programme''s published indicative annual tuition (AUD 55,400 -> AUD 27,700, converted to EUR at 1 EUR = 1.6321 AUD, 2026-08-21) — a derived figure, not a flat amount separately published by Adelaide University. Lower automatic tiers also exist: Emerging Leaders Award (25% reduction, distinction average), Merit Scholarship (15%, credit average), Global Alumni Scholarship (10%, for previous UniSA/Adelaide University/University of Adelaide students), and Partner Award (10%, for approved partner-institution students).', NULL, 'https://adelaide.edu.au/study/scholarships/international-students-scholarships/', 'https://adelaide.edu.au/study/scholarships/international-students-scholarships/', '2026-08-23'),
    ('6a329e62-8194-4898-816e-bb69ed91ecbe', 'VU Block Model International Scholarship', 'Victoria University', 'AU', '6e483f2a-97ca-4acd-aa00-7e4f7fe55f48', '3924864c-858b-4100-b87a-6b57f5be23ec', 'PARTIAL_TUITION', 6764.29, 'For students starting a foundation, undergraduate, or postgraduate coursework degree at VU''s Melbourne campus in 2026-2027; grants a tuition reduction of 10%, 20%, or 30% for the entire first year depending on prior academic results (this record reflects only the top 30% tier). Amount shown is 30% of an approximate annual tuition for this programme, derived from its published per-semester rate (2 x AUD 18,400 = AUD 36,800/year -> 30% = AUD 11,040, converted to EUR at 1 EUR = 1.6321 AUD, 2026-08-21) since VU publishes tuition per-semester, not per-year. Separate VU Sydney & Brisbane campus scholarships exist at different rates (up to 22.5% plus a further 10% diversity award for IT/Business students from designated countries) and are not reflected in this figure.', NULL, NULL, 'https://www.vu.edu.au/courses/bachelor-of-business-bbns/international', '2026-08-23'),
    ('53236661-3b25-4d0d-84b0-120902c361d9', 'WSU International Undergraduate Scholarship', 'Western Sydney University', 'AU', '816628cf-77b1-4cac-a1db-49b60bca7554', '13eac1c1-ef39-4426-b69e-c248e946790a', 'PARTIAL_TUITION', 3676.25, 'Automatically assessed on application (no separate application needed), awarded on academic merit, renewable for up to 3 years. Two named tiers exist: AUD 6,000 (this record) and AUD 3,000; a top tier offering 50% off tuition is also mentioned on the same page without a separate fixed amount. Amount shown: AUD 6,000, converted to EUR using the ECB reference rate (1 EUR = 1.6321 AUD, 2026-08-21).', NULL, NULL, 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-information-and-communications-technology-ict', '2026-08-23');

INSERT INTO living_cost_estimates (estimate_id, country_code, city, university_id, category, monthly_estimate_eur, source_url, source_checked_on, notes) VALUES
    ('6e1c327e-680d-43e6-a7f9-bebf0e6975df', 'FR', 'Grenoble', 'a29e2576-15c0-49ee-bcbc-741ee0cb026b', 'ACCOMMODATION', 350.00, 'https://etudiant.univ-grenoble-alpes.fr/medias/fichier/les-residences-etudiantes-publiques-du-crous-a-grenoble-1344744.kjsp', '2026-08-23', 'Official CROUS Grenoble published range is EUR 200-500/month depending on room size (9m² room up to a studio); figure shown is the midpoint of that range, not a single fixed rate. A separate UGA international-office cost-of-living page gives an overlapping but slightly different range of EUR 250-500/month for subsidized/CROUS housing, plus EUR 450-800/month for private residence halls and EUR 400-600/month for a private studio/flat (https://international.univ-grenoble-alpes.fr/getting-organized/budget/cost-of-living/cost-of-living-783898.kjsp) — not used here to avoid double-counting, since it describes the same CROUS housing option among others.'),
    ('dbc9ff87-a19b-4761-be0f-092b5ffee5d7', 'FR', 'Grenoble', 'a29e2576-15c0-49ee-bcbc-741ee0cb026b', 'FOOD', 250.00, 'https://international.univ-grenoble-alpes.fr/getting-organized/budget/cost-of-living/cost-of-living-783898.kjsp', '2026-08-23', 'Official UGA international office estimate: EUR 200-300/month for food; figure shown is the midpoint of that range.'),
    ('642d5c58-212e-4cd8-9cf0-aefc9ae08836', 'FR', 'Grenoble', 'a29e2576-15c0-49ee-bcbc-741ee0cb026b', 'TRANSPORT', 18.00, 'https://international.univ-grenoble-alpes.fr/getting-organized/budget/cost-of-living/cost-of-living-783898.kjsp', '2026-08-23', 'Official UGA international office figure: EUR 18/month for a discounted "M réso" transport pass for students aged 18-25 — a single stated figure, not a range.'),
    ('3c3d54ba-3fd4-4eda-83dd-543d0f73d2b5', 'BE', NULL, NULL, 'GENERAL', 1225.00, 'https://www.kuleuven.be/english/life-at-ku-leuven/money-matters/cost-of-living-in-belgium', '2026-08-23', 'Official KU Leuven estimate: EUR 1,050-1,400/month for living expenses in Belgium generally (covering study materials, housing, food, clothing, laundry, medical/insurance, leisure, and transport); figure shown is the midpoint of that range. Not university- or city-specific — treated as a country-wide figure since the source explicitly frames it as a Belgium-wide estimate rather than a Leuven-only one.');

INSERT INTO visa_requirements (visa_requirement_id, destination_country_code, applicant_country_code, visa_type, financial_proof_eur, estimated_processing_days, required_documents, application_url, source_url, source_checked_on, notes) VALUES
    ('24de10fe-cabd-4f71-98a3-2d4e613035cb', 'FR', NULL, 'RESIDENCE_PERMIT', 10530.00, NULL, ARRAY['passport', 'university_enrollment_confirmation', 'prior_academic_transcripts', 'proof_of_financial_resources', 'signed_republic_principles_commitment'], 'https://campusfrance.org/en/student-long-stay-visa', 'https://www.service-public.fr/particuliers/vosdroits/F2231', '2026-08-23', 'Covers the VLS-TS ("visa de long séjour valant titre de séjour") student permit for Bachelor''s/Master''s study (PhD candidates instead use a separate "Talent Passport" category, not covered here). Minimum required financial resources increased on 2026-08-01 to EUR 877.50/month (EUR 10,530/year) from a prior EUR 615/month (EUR 7,380/year) threshold, set at 47% of the monthly gross SMIC and subject to future revision alongside SMIC increases; applications submitted through 2026-07-31 were assessed under the old threshold. Holders of French-government (Ministry for Europe/Foreign Affairs) scholarships are exempt from this check. Required documents shown are for the mandatory validation step (done online via the ANEF platform, within 3 months of arrival) rather than a separately-enumerated initial embassy-application checklist, which was not found as a clean list on the pages fetched. Fees: VLS-TS validation tax EUR 100; residence-card renewal EUR 100; multi-year residence card EUR 150. Minimum passport validity is NOT stated on any official page checked (campusfrance.org, service-public.fr, or france-visas.gouv.fr, the last of which returned HTTP 403 on direct fetch) and is left NULL rather than assumed. A separate CVEC national student contribution of EUR 105/year also applies at registration and is not part of this visa''s own fees.'),
    ('845d9e89-ca6a-455d-8887-abd2da8385e0', 'BE', NULL, 'RESIDENCE_PERMIT', NULL, 90, ARRAY['passport', 'enrollment_certificate', 'proof_of_financial_resources', 'health_insurance_proof', 'medical_certificate', 'criminal_record_extract'], 'https://dofi.ibz.be/en/themes/third-country-nationals/study/initial-authorisation-stay-application-visa-d-authorisation', 'https://dofi.ibz.be/en/themes/third-country-nationals/study/initial-authorisation-stay-application-visa-d-authorisation', '2026-08-23', 'Covers Belgium''s national long-stay "Type D" visa/residence authorisation for study. A decision is due within 90 days of a complete application. Financial-proof amount is NOT stated in EUR on this official page (a EUR 12,744 figure found only via a WebSearch snippet is excluded rather than treated as confirmed) — proof of sufficient means of subsistence is still a qualitative requirement, just without a stated number. Minimum passport validity is likewise NOT stated for this specific student permit: a "15 months" figure appears on a Belgian embassy page (https://canada.diplomatie.belgium.be/en/visa/visa-belgium/long-stay-visa-d-visa) but is explicitly stated there for work-permit categories, not the student permit, so it is not applied here. Criminal-record extract required only for applicants aged 18+, must be dated within 6 months. Sworn translations into German/English/French/Dutch are required for foreign-language documents. Parental consent required if the applicant is under 18.');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('e8e59576-c5f9-4c08-b72c-63be728a6618', 'a29e2576-15c0-49ee-bcbc-741ee0cb026b', 'UNIVERSITY_DORM', 'CROUS Grenoble-Alpes', 'Grenoble', 350.00, NULL, NULL, ARRAY['furnished'], 'https://www.messervices.etudiant.gouv.fr/', NULL, 'https://etudiant.univ-grenoble-alpes.fr/medias/fichier/les-residences-etudiantes-publiques-du-crous-a-grenoble-1344744.kjsp', '2026-08-23', 'Official CROUS Grenoble published range is EUR 200-500/month across room types from a 9m² room up to a studio, some with shared/co-living options; figure shown is the midpoint, not a single fixed rate. Allocation is via the national Dossier Social Étudiant (DSE), with the main campaign in July for September entry; scholarship holders are prioritized. Deposit amount is not published on the official page and is left NULL rather than guessed.'),
    ('a17042a0-0f94-4ffe-992c-07ba46e3f98f', '5c556365-1608-4f7d-8f1b-7164750a5135', 'UNIVERSITY_DORM', 'Ghent University Housing Service', 'Ghent', 391.00, NULL, NULL, ARRAY['unrenovated_room'], 'https://www.ugent.be/en/facilities/housing/rentalfee', 'accommodatie@ugent.be', 'https://www.ugent.be/en/facilities/housing/rentalfee', '2026-08-23', 'Official 2026-2027 rate for an unrenovated Room booked for a full academic year (a higher EUR 443/month rate applies for contracts under 12 months). Higher room tiers are also available: Rooms Plus EUR 622/month, Comfort Rooms & Studios EUR 707/month, and a Type 5 Couples Apartment EUR 791/month (all full-year rates). A city-imposed student-housing tax takes effect from January 2027 and is not included in these figures. Deposit amount is not published on the official page and is left NULL rather than guessed.'),
    ('8d99118d-034d-449e-b55d-37e330a98718', 'd8d850c2-e7d1-41c3-8dbc-4460b34c0e76', 'UNIVERSITY_DORM', 'Adelaide University Village', 'Adelaide', 1008.93, 306.35, NULL, ARRAY['furnished', 'all_utilities_included', 'wifi'], 'https://adelaide.edu.au/life-at-adelaide/accommodation/student-accommodation/university-managed-student-accommodation/adelaide-university-village/', NULL, 'https://adelaide.edu.au/life-at-adelaide/accommodation/student-accommodation/university-managed-student-accommodation/adelaide-university-village/', '2026-08-23', 'Original figures: AUD 19,760/year for an apartment bedroom with shared bathroom (used here, converted to a monthly EUR figure) and a AUD 500 refundable security deposit; converted using the ECB reference rate (1 EUR = 1.6321 AUD, 2026-08-21). A higher-tier townhouse bedroom with a private bathroom is also available at AUD 21,840/year. Fees include all utilities (unlimited wifi, water, gas, electricity), paid in two instalments per year. The source page labels these as "2027" rates as fetched — reverify at time of use. Distance to campus is not published on the official page and is left NULL rather than guessed.'),
    ('f5e8c96b-f1a8-4886-925b-724e442c8ae7', '816628cf-77b1-4cac-a1db-49b60bca7554', 'UNIVERSITY_DORM', 'Western Sydney University Village (Accommodation Scholarship rate)', 'Sydney', 451.36, 416.64, NULL, ARRAY['utilities_included', 'residential_activity_fee_included'], 'https://www.westernsydney.edu.au/international/arriving/accommodation/accommodation-scholarships', 'studentaccommodation@westernsydney.edu.au', 'https://www.westernsydney.edu.au/international/arriving/accommodation/accommodation-scholarships', '2026-08-23', 'Original figure: AUD 170/week (discounted Accommodation Scholarship rate, inclusive of utilities and a residential activity fee), converted to a monthly EUR figure using 52/12 weeks-per-month, then to EUR at the ECB reference rate (1 EUR = 1.6321 AUD, 2026-08-21). Available only at the Campbelltown, Hawkesbury, and Penrith locations, for new international students commencing a Bachelor''s or Master''s degree in 2026 (promo code "International2026" required). Deposit shown is derived from the source page''s stated rule of "4 weeks'' rent" (4 x AUD 170 = AUD 680, converted the same way) rather than a separately-published flat figure. A one-time AUD 110 (EUR 67.40) application fee also applies and is not included in either figure above. Distance to campus is not applicable to a single figure since the offer spans three separate campus locations.');

-- Batch: Sweden, Singapore, New Zealand (research/verification pass 2026-08-23).
-- FX rates used throughout this batch (ECB reference rate via frankfurter.dev,
-- dated 2026-08-21): 1 EUR = 11.0625 SEK, 1 EUR = 1.4838 SGD, 1 EUR = 1.9541 NZD.
-- Deliberate omissions / notable findings from this batch, documented here so
-- a future reader doesn't mistake a gap for an oversight:
--  - KTH (Sweden) and NTU (Singapore) both state an English-test figure of
--    "TOEFL score of 4.5" verbatim on their own official pages. This reads as
--    anomalously low for the TOEFL iBT 0-120 scale and may reference a
--    different sub-scale or be a page artifact — reported exactly as stated
--    per this project's policy against silently "correcting" a sourced
--    figure; verify directly with each university before relying on it.
--  - Sweden: no programme states a numeric minimum-GPA figure or a
--    programme-specific minimum-funds figure distinct from the Migrationsverket
--    visa requirement. The Swedish Institute Scholarship (SISGP) was NOT
--    blocked in this pass (si.se fetched directly) — seeded with only the
--    monthly living stipend (SEK 12,000) as its amount_eur, since the larger
--    tuition-coverage component varies by university and isn't reducible to
--    one euro figure; full coverage terms are in eligibility_notes. Sweden's
--    visa_requirements row has no required_documents/estimated_processing_days
--    (not confirmed in this pass) and no minimum_passport_validity_months —
--    Migrationsverket states only a relative rule ("never longer than your
--    passport is valid"), not a fixed number of months, so left NULL rather
--    than assumed. No deposit figure for KTH Teknikringen or Lund
--    Klostergarden housing (not stated on the pages fetched).
--  - Singapore: no scholarship and no general living-cost-estimate row is
--    seeded — none was found on any official page during this pass. NUS's
--    Bachelor of Computing in Computer Science duration is left NULL: only
--    third-party aggregators state "4 years," not an official NUS page. No
--    SMU accommodation row: no concrete SGD rent figure could be confirmed on
--    any official SMU page (only descriptive text, no rate table); NUS's
--    UTown Residence was likewise dropped (Incapsula-blocked live, and its
--    Wayback snapshot rendered as an empty JS shell). ICA's Student's Pass
--    page does not state a financial-proof figure or a minimum passport
--    validity — both left NULL rather than assumed (the visa row itself is
--    still seeded, since the page loaded fine and simply doesn't cover those
--    two facts). Several official Singapore domains (nus.edu.sg, smu.edu.sg)
--    are Incapsula-protected; Wayback Machine snapshots were used in their
--    place with snapshot dates recorded as source_checked_on.
--  - New Zealand: no scholarship row is seeded (none found). No numeric
--    minimum-GPA/CGPA figure for any of the three universities' admission
--    requirements — NCEA rank scores, IB points, and GCE grades aren't
--    reducible to one comparable percentage without guessing. Otago's own
--    domain (otago.ac.nz) returns HTTP 403 to automated fetches (reconfirmed
--    directly 2026-08-23); Wayback Machine snapshots were used for its
--    tuition, admission-requirements, and accommodation pages, with the
--    snapshot date recorded as source_checked_on. Otago's accommodation
--    deposit figure is NOT confirmed (an unverified third-party NZD 949
--    figure was deliberately excluded) and left NULL. New Zealand's
--    visa_requirements row carries this project's first-ever confirmed,
--    clean numeric minimum_passport_validity_months figure (3 months, stated
--    directly by immigration.govt.nz) — every other seeded destination
--    country still has this column NULL.
-- All accommodation rows quoted as a weekly or annual figure in the original
-- research (NUS, and all three NZ universities) are converted to a
-- monthly-equivalent for this table's monthly_rent_eur column; the raw
-- weekly/annual figure and the conversion basis are always disclosed in that
-- row's notes. NZ accommodation figures that are catered/all-inclusive
-- college fees (Wellington's Capital Hall, all of Otago's colleges) are
-- flagged as such in notes since they include a meal plan and so are not
-- directly comparable to a rent-only hall (e.g. Auckland's Carlaw Park
-- Student Village, seeded here specifically because it is self-catered).

