    ('e83be5af-a43c-4c45-9030-484c80cdd8d9', '169974be-2d30-405b-bbad-e3855cc9fcc0', 'Master''s Programme in Business and Management – International Business', 'MASTER', 'Business Studies', 24, 'https://www.uu.se/en/study/programme/masters-programme-business-and-management-international-business'),
    ('da1efe86-5e23-4856-afad-00a8513bc6af', '05c4a80b-8e23-4fe8-8788-ec0a117ab241', 'MSc Machine Learning', 'MASTER', 'Machine Learning', 24, 'https://www.kth.se/en/studies/master/machine-learning/msc-machine-learning-1.48533'),
    ('8582d1e6-45ed-4212-b8d1-8f641147ff6b', 'e3d372be-82f9-4574-a720-e07e30fb12b7', 'Economics - Master''s Programme (Two Years)', 'MASTER', 'Economics', 24, 'https://www.lunduniversity.lu.se/study/economics-masters-programme-two-years-EAECO'),
