    ('7c401299-b56b-42de-becf-54c0504b3961', '65ea2c34-b879-4eaf-b02c-629309c61127', 'MSc in Cybersecurity (Applied Cryptography)', 'MASTER', 'Cybersecurity', 12, 'https://www.ntu.edu.sg/spms/about-us/mathematics/grad/msc-in-cybersecurity-applied-cryptography'),
