    ('9d15b4c4-4226-456f-ac1b-34b256510e7b', '2461e115-2c23-4c67-b5dd-8acb27db558e', 'Bachelor of Commerce (BCom)', 'BACHELOR', 'Commerce', 36, 'https://www.wgtn.ac.nz/__data/assets/pdf_file/0008/2208428/bachelor-commerce.pdf'),
    ('01c52db0-7df1-46ae-8daf-fd0b7b7c67bd', 'e930abc2-ae26-4c67-a8da-5dca27c28ca2', 'Bachelor of Commerce (BCom)', 'BACHELOR', 'Commerce', 36, 'https://www.otago.ac.nz/study/qualifications/bachelor-of-commerce');

INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('f95a43db-d737-4377-9783-bb140f0bd7d9', 'e83be5af-a43c-4c45-9030-484c80cdd8d9', NULL, NULL, 'IELTS', '6.5', NULL, 'https://www.uu.se/en/study/masters-studies/application/entry-requirements', '2026-08-23', 'IELTS Academic overall 6.5, no section below 5.5; TOEFL iBT alternative: 20 (scale 0-30) in the written test, 90 total. This English-score pair comes from Uppsala''s general master''s entry-requirements page, which the programme page itself defers to via its "English 6" equivalence statement, rather than a programme-specific score. Selection for this specific programme prioritizes a GMAT score plus higher-education credits (max 285); no numeric minimum-GPA figure is published. Academic prerequisite: a Bachelor''s degree equivalent to a Swedish Kandidatexamen with 90 credits in business studies. No programme-specific minimum-funds figure or generic document checklist is published beyond "general supporting documents per the application guide." Application deadline 15 January 2026 (application code UU-M2111).'),
    ('8ec81150-9596-43ad-aa78-1aefd6bc67a8', 'da1efe86-5e23-4856-afad-00a8513bc6af', NULL, NULL, 'IELTS', '6.5', ARRAY['degree_certificate', 'official_transcript', 'proof_of_english_proficiency', 'passport_copy', 'letter_of_motivation', 'two_letters_of_recommendation', 'programme_summary_sheet'], 'https://www.kth.se/en/studies/master/machine-learning/entry-requirements-machine-learning-1.48539', '2026-08-23', 'IELTS overall 6.5. TOEFL alternative: quoted verbatim from KTH''s own page as a "TOEFL score of 4.5" — this figure looks anomalously low for TOEFL iBT''s 0-120 scale and may reference a different sub-scale or be a page anomaly; reported as-is rather than corrected, same caution applied to NTU (Singapore) in this same batch. Bachelor''s prerequisite: 180 ECTS credits including named coursework in Algebra/Geometry, Calculus, Probability/Statistics, Programming, and Algorithms/Data Structures. Selection uses a KTH internal 1-75 scoring scale on prior grades, not a published minimum-GPA cutoff. Application opens 16 October, deadline 15 January, documents due 1 February, results 1 April.'),
    ('3c8515cb-f0d1-4d6e-b7d2-27e6574c8e98', '8582d1e6-45ed-4212-b8d1-8f641147ff6b', NULL, NULL, 'IELTS', '6.5', ARRAY['statement_of_purpose', 'cv', 'university_transcripts'], 'https://www.lusem.lu.se/study/application-and-admission', '2026-08-23', 'IELTS Academic overall 6.5, no section below 5.5. TOEFL alternatives also accepted: paper-based score of 4.5 (scale 1-6) with a 575 total, or internet-based score of 20 (written) with a 90 total — the paper-based "4.5" is quoted verbatim, same caution as KTH''s TOEFL figure in this batch. GMAT/GRE explicitly not required; the page notes a majority of accepted students hold roughly IELTS 7.0, stated as informational, not a minimum. Academic prerequisite: a Bachelor''s degree (or equivalent) with at least 60 credits in economics, including intermediate microeconomics and econometrics. No numeric minimum-GPA figure is published.'),
    ('99da22ed-7a41-4140-a44d-d8da5a10edff', 'c8fb7004-1289-4b67-bcbd-61ddc9f4bb3e', NULL, NULL, NULL, NULL, NULL, 'https://www.nus.edu.sg/oam/admissions/international-qualifications/admission-requirements', '2025-09-19', 'nus.edu.sg is Incapsula-protected against automated fetches; content taken from a Wayback Machine snapshot of this official URL (dated 2025-09-19), which confirms the AY2026/2027 application window (3 Dec 2025 - 23 Feb 2026) and a minimum of 12 years of general education, but states no English-test name/score. Subject prerequisite (from NUS''s "Programme Prerequisites for International Students" PDF, accessed directly 2026-08-23): a Year 12 or higher pass in Mathematics for Computer Science/AI majors under the School of Computing. No numeric GPA figure, English-test score, or itemized document checklist is stated on any official NUS page found in this pass — IELTS/TOEFL figures exist only on third-party sites (collegedunia, gabble.ai, ambitio.club) and are excluded per this project''s sourcing rule.'),
    ('3052a30d-ffe5-4603-88a6-ef591c0f9ca8', '7c401299-b56b-42de-becf-54c0504b3961', NULL, NULL, 'IELTS', '6.0', ARRAY['passport_or_nric', 'passport_photo', 'degree_certificate', 'official_transcript', 'english_test_score'], 'https://www.ntu.edu.sg/spms/about-us/mathematics/grad/msc-in-cybersecurity-applied-cryptography', '2026-08-23', 'IELTS overall 6.0 or a "TOEFL score of 4.5 or more" — the TOEFL figure is quoted verbatim from NTU''s own page; it looks anomalously low for the TOEFL iBT 0-120 scale and may reference a different sub-scale, reported as-is rather than corrected (same caution as KTH/Sweden in this batch). Entry requires a good Bachelor''s degree in a quantitative field (mathematics, physics, engineering, computer science, finance, or related). A minimum CGPA of 2.50 stated by NTU is a graduation requirement, not an entry requirement, and is not populated here. Required-documents list drawn from NTU''s Coursework Programmes Admission Guide (https://www.ntu.edu.sg/admissions/graduate/cwadmissionguide); GMAT/GRE and work experience are preferred, not required.'),
    ('f9301a05-4805-4de4-968f-43b7b5a0dcf9', '2813e9df-0bb1-40e1-83e7-26cbca245942', NULL, NULL, 'IELTS', '7.0', ARRAY['online_application', 'secondary_school_results', 'standardised_test_score'], 'https://admissions.smu.edu.sg/admissions-requirements/international-and-other-qualifications', '2026-06-06', 'smu.edu.sg is Incapsula-protected against automated fetches; content taken from a Wayback Machine snapshot of this official URL (dated 2026-06-06). General entry requires a minimum of 12 years of formal education with good passes in a recognised exam; grade thresholds vary per home-country qualification system, so no single numeric GPA is populated. English requirement for non-Law programmes: IELTS Academic overall >= 7.0 (reading >= 7.0, writing >= 6.5); other accepted tests: SAT >= 1,350, ACT >= 29, TOEFL iBT >= 93 (before 21 Jan 2026) or >= 5 (from 21 Jan 2026, an Essentials-style rescale, quoted verbatim as stated), PTE Academic >= 66, C1 Advanced >= 185, AST English >= 225. No minimum-funds/financial-requirement figure is stated on this page (only an application fee of S$15 is mentioned).'),
    ('8951b3b1-9f84-4036-96a9-f28562241ab8', '0fe90188-2ebf-4558-b864-e1ce8b5358ff', NULL, NULL, 'IELTS', '6.0', ARRAY['birth_certificate_or_passport', 'citizenship_certificate', 'secondary_transcript', 'tertiary_transcript_if_applicable', 'english_test_certificate'], 'https://www.auckland.ac.nz/en/study/study-options/find-a-study-option/bachelor-of-science-bsc.html', '2026-08-23', 'IELTS Academic overall 6.0, no band below 5.5. Academic entry benchmarks vary by qualification system (NCEA rank score 165 for 2027 NZ secondary; CIE 170; IB 26; GCE A-Level/CIE minimum BCC across 3 subjects; prior tertiary study GPA/GPE minimum 3.0, 3.5 for select majors) — not reduced to one percentage figure since these scales aren''t directly comparable. Required-documents list drawn from https://www.auckland.ac.nz/en/study/applications-and-admissions/how-to-apply/supporting-documents.html. No institution-specific minimum-funds figure is stated; the page mentions only "proof of financial capability" without a number.'),
    ('c6b59fcd-a438-4dd5-b92c-bda9660a041e', '9d15b4c4-4226-456f-ac1b-34b256510e7b', NULL, NULL, 'IELTS', '6.0', ARRAY['passport_identity_page', 'academic_transcripts', 'completion_certificates', 'police_report_if_applicable', 'nzqa_assessment_if_applicable'], 'https://www.wgtn.ac.nz/international/applying/entry-requirements/english-language/standard-undergraduate', '2026-08-23', 'IELTS Academic overall 6.0, no band below 5.5. Alternative tests: TOEFL iBT 80, PTE Academic 50/42, Duolingo English Test 105/95, Cambridge C1/C2 169/162, NZCEL Level 4 Academic, Trinity ISE II Distinction. No single numeric GPA is stated for general international entry; the accepted academic pathways are a recognised secondary qualification, an approved foundation programme, or one year of tertiary study equivalent to an NZ Bachelor''s, with country-specific thresholds behind a qualification-by-country lookup not enumerated here. Documents list from https://www.wgtn.ac.nz/international/applying/how-to-apply/prepare-documents. No institution-specific minimum-funds figure is stated.'),
    ('9dee66ad-d5a2-4895-8cf6-8cc68bf3df39', '01c52db0-7df1-46ae-8daf-fd0b7b7c67bd', NULL, NULL, 'IELTS', '6.0', NULL, 'https://www.otago.ac.nz/international/future-students/entrance-requirements/language-requirements', '2025-06-18', 'otago.ac.nz returns HTTP 403 to automated fetches (reconfirmed directly 2026-08-23); content taken from a Wayback Machine snapshot of this official URL (dated 2025-06-18), which directly confirms: IELTS Academic (undergraduate) overall 6.0, no individual band below 5.5 (the postgraduate threshold is higher, 6.5/6.0, and not applicable to this Bachelor''s programme); TOEFL iBT alternative: overall 80 and a writing score of 20. General academic entry is assessed per home-country qualification (NCEA-equivalent, IB, A-Level, etc.) against country-specific thresholds rather than one global numeric GPA — see https://www.otago.ac.nz/study/entry-requirements/international-entrance-requirements (Wayback snapshot 2025-10-18) for that country-by-country framework. A documents-checklist page exists on Otago''s site but was not independently re-verified in this pass, so required_documents is left NULL here rather than guessed.');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('1e80dcbf-f853-4513-a4eb-b68d25e8ff7f', 'e83be5af-a43c-4c45-9030-484c80cdd8d9', 'TUITION_TOTAL', 'INTERNATIONAL', 20610.17, 'https://www.uu.se/en/study/programme/masters-programme-business-and-management-international-business', '2026-08-23', 'Original figure: SEK 228,000 total for the 2-year programme (first instalment SEK 57,000), converted at 1 EUR = 11.0625 SEK (frankfurter.dev ECB reference rate, 2026-08-21).'),
    ('143c40ef-e125-4f71-a5aa-be17e2f1a080', 'da1efe86-5e23-4856-afad-00a8513bc6af', 'TUITION_TOTAL', 'INTERNATIONAL', 32542.37, 'https://www.kth.se/en/studies/master/machine-learning/fees-machine-learning-1.909974', '2026-08-23', 'Original figure: SEK 360,000, explicitly stated as the full non-EU/EEA/Swiss programme tuition (not per-year), converted at 1 EUR = 11.0625 SEK (2026-08-21).'),
    ('77d5c38d-5a11-41c4-a985-59e7917b7f6f', 'da1efe86-5e23-4856-afad-00a8513bc6af', 'APPLICATION_FEE', 'INTERNATIONAL', 81.36, 'https://www.kth.se/en/studies/master/machine-learning/fees-machine-learning-1.909974', '2026-08-23', 'Original figure: SEK 900, due before the end of January, converted at 1 EUR = 11.0625 SEK (2026-08-21).'),
    ('7468ee57-57eb-4c0b-b762-0c5085e498b9', '8582d1e6-45ed-4212-b8d1-8f641147ff6b', 'TUITION_TOTAL', 'INTERNATIONAL', 27118.64, 'https://www.lunduniversity.lu.se/study/economics-masters-programme-two-years-EAECO', '2026-08-23', 'Original figure: SEK 300,000 total for the 2-year programme (first payment SEK 75,000), converted at 1 EUR = 11.0625 SEK (2026-08-21).'),
    ('10172b00-3ef0-4ef6-83ed-4ce8428e4110', 'c8fb7004-1289-4b67-bcbd-61ddc9f4bb3e', 'TUITION_PER_YEAR', 'INTERNATIONAL', 26755.63, 'https://www.nus.edu.sg/registrar/docs/default-source/administrative-policies-procedures/ugtuitioncurrent.pdf', '2026-08-23', 'Original figure: S$39,700 per annum, inclusive of GST — the non-subsidised (no MOE Tuition Grant) rate for International Students, AY2026/2027, per NUS Registrar''s official tuition-fee PDF (document dated March 2026, fetched and text-extracted directly). Converted at 1 EUR = 1.4838 SGD (2026-08-21). For reference, subsidised rates on the same PDF are S$18,050/yr (ASEAN) and S$21,400/yr (other international) — not the figure used here.'),
    ('a3865a9d-8f08-47e8-8722-c9ca4217a48c', '7c401299-b56b-42de-becf-54c0504b3961', 'TUITION_TOTAL', 'INTERNATIONAL', 42606.82, 'https://www.ntu.edu.sg/spms/about-us/mathematics/grad/msc-in-cybersecurity-applied-cryptography', '2026-08-23', 'Original figure: S$63,220.00 for AY2026/27, inclusive of 9% GST, explicitly described as based on the shortest (1-year, full-time) candidature — i.e. a full-programme total, not a per-year figure. This programme has no MOE-subsidised track for any nationality, confirmed via NTU''s official non-subsidised-programmes fee-list PDF. Converted at 1 EUR = 1.4838 SGD (2026-08-21).'),
    ('6a778298-f57d-4c2e-820b-9b0ff4ff1e8b', '2813e9df-0bb1-40e1-83e7-26cbca245942', 'TUITION_PER_YEAR', 'INTERNATIONAL', 32147.19, 'https://admissions.smu.edu.sg/financial-matters/tuition-fees-grant', '2026-01-30', 'smu.edu.sg is Incapsula-protected against automated fetches; content taken from a Wayback Machine snapshot of this official URL (dated 2026-01-30). Original figure: S$47,700/year, described as the non-subsidised (no MOE Tuition Grant) annual fee inclusive of GST for AY2025/26 entering freshmen — the page groups Information Systems with several other SMU degrees under one fee row. Converted at 1 EUR = 1.4838 SGD (2026-08-21).'),
    ('266afa6c-fef8-443e-a4ba-0aa5da30c18c', '2813e9df-0bb1-40e1-83e7-26cbca245942', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 196.04, 'https://admissions.smu.edu.sg/financial-matters/tuition-fees-grant', '2026-01-30', 'Original figure: S$291.00/year, the Annual Miscellaneous Student Fee for international students, same Wayback-sourced page as this programme''s tuition row (snapshot dated 2026-01-30). Converted at 1 EUR = 1.4838 SGD (2026-08-21).'),
    ('2a4d50f8-9bcf-41f7-aad8-0b79d87f7c31', '0fe90188-2ebf-4558-b864-e1ce8b5358ff', 'TUITION_PER_YEAR', 'INTERNATIONAL', 24165.09, 'https://www.auckland.ac.nz/en/study/fees-and-money-matters/tuition-fees/international-student-fees/undergraduate-international-fees.html', '2026-08-23', 'Original figure: NZ$47,221/year (2026), the base/lower end of a published range up to NZ$58,009/year that applies to select higher-cost majors (Cell/Molecular Bioscience, Exercise Science, Medicinal Chemistry, Nutrition, Pharmacology, Physiology); the base figure is used here as most BSc majors fall under it. Converted at 1 EUR = 1.9541 NZD (2026-08-21). The same page states a forward-looking 2027 estimate (NZ$49,581.60-60,909.60), explicitly marked as an estimate and not used here.'),
    ('eb1f30b3-16ea-417b-86bc-3ac55e72c0e2', '0fe90188-2ebf-4558-b864-e1ce8b5358ff', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 579.71, 'https://www.auckland.ac.nz/en/study/fees-and-money-matters/tuition-fees/international-student-fees/undergraduate-international-fees.html', '2026-08-23', 'Original figure: NZ$1,132.80/year, the Student Services Fee charged alongside tuition, converted at 1 EUR = 1.9541 NZD (2026-08-21).'),
    ('eb7a7100-4a0d-4fce-af2a-ee65fbaad975', '9d15b4c4-4226-456f-ac1b-34b256510e7b', 'TUITION_PER_YEAR', 'INTERNATIONAL', 19213.76, 'https://www.wgtn.ac.nz/students/money/fees/international', '2026-08-23', 'Original figure: NZ$37,545.60/year (2026), explicitly described as "the average tuition fee for a year''s full-time study (120 points)" for the Commerce subject area, calculated at NZ$312.88/point including GST — the actual fee depends on the specific courses chosen, so this is an average/indicative figure rather than a fixed one. Converted at 1 EUR = 1.9541 NZD (2026-08-21).'),
    ('36121b5c-339e-42e5-a5c6-bf353408819e', '01c52db0-7df1-46ae-8daf-fd0b7b7c67bd', 'TUITION_PER_YEAR', 'INTERNATIONAL', 21654.47, 'https://www.otago.ac.nz/study/fees/international-tuition-fees/business-school', '2025-07-31', 'otago.ac.nz returns HTTP 403 to automated fetches (reconfirmed directly 2026-08-23); content taken from a Wayback Machine snapshot of this official URL (dated 2025-07-31). Original figure: NZD$42,315/year (2026), explicitly labelled "a guide only" and calculated per-paper, applying to most Commerce majors (Accounting, Economics, Finance, HR Management, Information Science, International Business, Management, Marketing, PPE, Tourism); one major variant, Sports Business, is NZD$45,045/year and is not separately seeded. Converted at 1 EUR = 1.9541 NZD (2026-08-21).');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('53cd8f7e-94a1-4e89-a189-54088e6bdbc3', 'Swedish Institute Scholarships for Global Professionals (SISGP)', 'Swedish Institute (SI)', 'SE', NULL, NULL, 'FULL_FUNDING', 1084.75, 'Competitive, country-wide scholarship for admitted Master''s applicants from SI''s list of priority countries; not tied to one Swedish university. Covers full tuition (paid directly by SI to the student''s university each semester) plus a monthly living stipend of SEK 12,000 throughout the study period, plus a one-time travel grant of SEK 15,000 (SEK 10,000 for scholars from Armenia, Azerbaijan, Belarus, Georgia, Moldova, and Ukraine). amount_eur here reflects only the monthly living stipend (converted at 1 EUR = 11.0625 SEK, 2026-08-21) — the tuition-coverage component varies by university and isn''t reduced to a single euro figure. First apply to a Swedish Master''s programme via University Admissions (15 Oct 2025 - 15 Jan 2026), then apply for this scholarship once admitted; results announced 23 April 2026.', '2026-02-25', 'https://si.se/en/apply/scholarships/swedish-institute-scholarships-for-global-professionals/', 'https://si.se/en/apply/scholarships/swedish-institute-scholarships-for-global-professionals/', '2026-08-23');

INSERT INTO living_cost_estimates (estimate_id, country_code, city, university_id, category, monthly_estimate_eur, source_url, source_checked_on, notes) VALUES
    ('09bf0039-a802-43ca-a2a6-19a598600668', 'SE', NULL, NULL, 'GENERAL', 963.25, 'https://www.migrationsverket.se/en/you-want-to-apply/study/higher-education.html', '2026-08-23', 'Swedish Migration Agency''s official minimum maintenance/financial-requirement figure for a student residence permit, effective for applications made in 2026: SEK 10,656/month (up from SEK 10,584/month for 2025 applications, per the same page). Converted at 1 EUR = 11.0625 SEK (2026-08-21). This is an immigration financial-sufficiency threshold, not a general cost-of-living survey figure — see the visa_requirements row for the same figure annualized.'),
    ('12f08bc6-521d-4144-bb7d-c73c7d95e3dc', 'NZ', NULL, NULL, 'GENERAL', 853.08, 'https://www.immigration.govt.nz/visas/fee-paying-student-visa/', '2026-08-23', 'Immigration New Zealand''s official minimum living-cost figure required as evidence for a Fee Paying Student Visa application, for tertiary/English-language study: NZD $1,667/month (or NZD $20,000/year), if studying under one year. (Compulsory-education, Years 1-13, applicants instead use a lower NZD $1,417/month figure, not used here.) Converted at 1 EUR = 1.9541 NZD (2026-08-21). This is an immigration financial-sufficiency threshold, not a general cost-of-living survey figure — see the visa_requirements row for the same figure annualized.');

INSERT INTO visa_requirements (visa_requirement_id, destination_country_code, applicant_country_code, visa_type, financial_proof_eur, estimated_processing_days, minimum_passport_validity_months, required_documents, application_url, source_url, source_checked_on, notes) VALUES
    ('f732edf6-875c-4572-9e34-ed24436a8084', 'SE', NULL, 'RESIDENCE_PERMIT', 11559.05, NULL, NULL, NULL, NULL, 'https://www.migrationsverket.se/en/you-want-to-apply/study/higher-education.html', '2026-08-23', 'Financial-proof figure shown here is Migrationsverket''s monthly maintenance requirement (SEK 10,656) annualized (x12) for consistency with this table''s other rows — the source states it only as a monthly figure (see living_cost_estimates for that raw monthly SEK/EUR figure). Converted at 1 EUR = 11.0625 SEK (2026-08-21). Passport validity: the source states only "You can never be granted a permit for longer than your passport is valid" — a relative rule, not a fixed number of months, so minimum_passport_validity_months is left NULL rather than assumed. Estimated processing time and a required-documents checklist for this specific permit were not confirmed in this research pass and are left NULL rather than guessed.'),
    ('9152c387-2d00-4804-90b0-5c188b774741', 'SG', NULL, 'STUDY_VISA', NULL, 14, NULL, ARRAY['registration_acknowledgement_letter', 'travel_document_biodata_page', 'birth_certificate_if_applicable', 'proof_of_financial_support', 'passport_photo'], 'https://eservices.ica.gov.sg', 'https://www.ica.gov.sg/reside/STP/apply/ihl', '2026-08-23', 'Covers Singapore''s Student''s Pass for applicants to an Institute of Higher Learning (the relevant category for NUS/NTU/SMU). ICA''s official pages state neither a financial-proof/minimum-funds figure nor a minimum passport-validity requirement — both left NULL rather than assumed (a commonly cited "6 months" passport rule circulates on third-party sites but is not confirmed on an official ICA page). Estimated processing time shown (14 days) is the upper end of ICA''s stated "within one week (two weeks if a visa is also required)" range. A non-refundable S$45 application fee applies (not a factual field in this table). Apply 2-3 months before course start via the SOLAR e-Service (eservices.ica.gov.sg).'),
    ('085dfc52-ed60-444b-8a07-665c99fd1b15', 'NZ', NULL, 'STUDY_VISA', 10234.89, 60, 3, ARRAY['passport_or_identity_certificate', 'signed_course_offer', 'tuition_fee_payment_evidence', 'proof_of_living_expenses_or_sponsor_details', 'outward_travel_evidence_or_funds', 'medical_evidence_if_required', 'police_certificate_if_required'], 'https://apply.immigration.govt.nz/', 'https://www.immigration.govt.nz/visas/fee-paying-student-visa/', '2026-08-23', 'Covers the Fee Paying Student Visa. Financial-proof figure shown is Immigration NZ''s annual "living costs" evidence requirement (NZD $20,000/year, or NZD $1,667/month if studying under one year) annualized for consistency with this table''s other rows; converted at 1 EUR = 1.9541 NZD (2026-08-21). Estimated processing time reflects the published "80% of applications decided within 8.5 weeks" figure (~60 days), not a guarantee for every applicant. Passport validity is a clean, directly confirmed official figure: the passport or certificate of identity must be valid for at least 3 months after the date the applicant plans to leave New Zealand — the first such confirmed figure across every destination country seeded in this project so far (every other seeded country''s minimum_passport_validity_months is still NULL, since none of their official sources state a clean fixed number).');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('625b0a96-6d8d-4bb5-bc6d-cf9fb24524c2', '169974be-2d30-405b-bbad-e3855cc9fcc0', 'UNIVERSITY_DORM', 'Uppsala University Housing Office', 'Uppsala', 483.62, 316.38, NULL, NULL, 'https://housingoffice.se/accommodation/exchange-students-master-students/uppsala/flogsta-sernanders-vag/', NULL, 'https://housingoffice.se/accommodation/exchange-students-master-students/uppsala/flogsta-sernanders-vag/', '2026-08-23', 'Original figures: a corridor room at Flogsta/Sernanders vag ranges SEK 5,350-5,400/month (lower end used here); deposit SEK 3,500, due before arrival. Studio apartments (SEK 5,600-5,700/month) and one-bedroom apartments (SEK 8,400-9,200/month) are also available at this location but not seeded separately. Converted at 1 EUR = 11.0625 SEK (2026-08-21). Distance to campus is not published on the official page.'),
    ('60181f18-fa94-4497-9a00-36412a7d1106', '05c4a80b-8e23-4fe8-8788-ec0a117ab241', 'STUDIO_APARTMENT', 'KTH Accommodation (Teknikringen)', 'Stockholm', 741.24, NULL, NULL, NULL, 'https://www.kth.se/en/student/studier/housing/locations/accommodation-at-teknikringen-1.946203', NULL, 'https://www.kth.se/en/student/studier/housing/locations/accommodation-at-teknikringen-1.946203', '2026-08-23', 'Original figure: a single studio at SEK 8,200/month; larger studios range up to SEK 9,700/month and shared 2-/3-bed apartments are SEK 7,500/month per tenant (neither seeded separately). Converted at 1 EUR = 11.0625 SEK (2026-08-21). No deposit figure is stated on this page; distance to campus is not published.'),
    ('36d3908a-1466-431f-8920-75afad054f23', 'e3d372be-82f9-4574-a720-e07e30fb12b7', 'STUDIO_APARTMENT', 'LU Accommodation', 'Lund', 596.61, NULL, NULL, NULL, 'https://www.luaccommodation.lu.se/student-accommodation/our-student-accommodation/lund/klostergarden-student-house', NULL, 'https://www.luaccommodation.lu.se/student-accommodation/our-student-accommodation/lund/klostergarden-student-house', '2026-08-23', 'Original figure: a 24 sqm private-apartment studio flat at Klostergarden Student House, SEK 6,600/month. Converted at 1 EUR = 11.0625 SEK (2026-08-21). No deposit figure is stated on this specific page (LU Accommodation''s general rent page mentions a deposit process exists but not a figure); distance to campus is not published.'),
    ('dbd24ebe-f4c3-45d2-b73f-6a629ee24c6f', '392e1e03-3296-4999-9095-e4efca44553f', 'UNIVERSITY_DORM', 'NUS Office of Student Affairs (Halls of Residence)', 'Singapore', 481.87, NULL, NULL, NULL, 'https://osa.nus.edu.sg/wp-content/uploads/2026/03/Halls-of-Residence-Hostel-Rates-for-Undergraduates-as-at-25-Mar-2026-3-1.pdf', NULL, 'https://osa.nus.edu.sg/wp-content/uploads/2026/03/Halls-of-Residence-Hostel-Rates-for-Undergraduates-as-at-25-Mar-2026-3-1.pdf', '2026-08-23', 'Original figure: a single, non-air-conditioned room (e.g. Eusoff/Kent Ridge/Raffles Hall) at S$165/week, inclusive of GST, per NUS OSA''s official hostel-rates PDF (dated 25 Mar 2026, fetched directly). Converted here to a monthly-equivalent (S$165 x 52/12 weeks = S$715/month) then to EUR at 1 EUR = 1.4838 SGD (2026-08-21). A double non-AC room is S$114/week and AC options range S$129-226/week (not seeded separately). No deposit figure appears in this document; NUS''s separate UTown Residence accommodation could not be confirmed (Incapsula-blocked live, and its Wayback snapshot rendered as an empty JS shell).'),
    ('8656e979-b67b-43d5-973a-2bef8cc37ad8', '65ea2c34-b879-4eaf-b02c-629309c61127', 'UNIVERSITY_DORM', 'NTU Hall 1', 'Singapore', 405.71, NULL, NULL, NULL, 'https://www.ntu.edu.sg/life-at-ntu/accommodation/undergraduate-housing/detail/hall-1', NULL, 'https://www.ntu.edu.sg/life-at-ntu/accommodation/undergraduate-housing/detail/hall-1', '2026-08-23', 'Original figure: a single, non-air-conditioned room at S$602/month (AY2026/27), stated as nett and inclusive of utilities except air-conditioning (pay-per-use). Converted at 1 EUR = 1.4838 SGD (2026-08-21). A double non-AC room is S$412/month (not seeded separately). No deposit figure is stated on this page. Hall 1 residents will be temporarily housed off-site (30 Nanyang Link) from June 2026 during renovations, per the same page. No confirmed SMU accommodation row exists in this batch: no official SMU page stated a concrete SGD rent figure.'),
    ('f00b927a-59bc-47b6-89b0-05984f49d2d8', '64ad86d0-0533-4cf8-8a0c-397cb1feafbd', 'UNIVERSITY_DORM', 'University of Auckland Accommodation (Carlaw Park Student Village)', 'Auckland', 660.79, 562.92, NULL, NULL, 'https://www.auckland.ac.nz/assets/on-campus/accommodation/resident-support/residential-rules-and-fees/accommodation-fees/payment-schedules/2026-payment-schedules/2026%20Payment%20Schedule%20-%20SC%20-%20Academic.pdf', NULL, 'https://www.auckland.ac.nz/assets/on-campus/accommodation/resident-support/residential-rules-and-fees/accommodation-fees/payment-schedules/2026-payment-schedules/2026%20Payment%20Schedule%20-%20SC%20-%20Academic.pdf', '2026-08-23', 'Carlaw Park Student Village is self-catered (rent-only, no meal plan), chosen deliberately over Auckland''s catered halls for comparability with rent-only accommodation elsewhere in this table. Original figure: a single room, 2026 payment schedule, 42-week academic year total NZ$15,495.00 — converted here to a monthly-equivalent (/12) then to EUR at 1 EUR = 1.9541 NZD (2026-08-21). Auckland''s catered halls (Grafton/O''Rorke/University/Waiparuru), which include meals, run NZ$20,969-23,301/year and are not seeded here to avoid conflating rent with a meal plan. Deposit figure reflects the general $1,100 due at acceptance (a $450 non-refundable admin fee plus a $650 advance payment credited to the room account), per Auckland''s accommodation-fees page.'),
    ('4c58794a-1d56-43df-9d25-92df15c4a602', '2461e115-2c23-4c67-b5dd-8acb27db558e', 'UNIVERSITY_DORM', 'Victoria University of Wellington (Capital Hall)', 'Wellington', 941.22, 547.57, NULL, NULL, 'https://www.wgtn.ac.nz/__data/assets/pdf_file/0005/2030765/capital-hall-payment-schedule.pdf', NULL, 'https://www.wgtn.ac.nz/__data/assets/pdf_file/0005/2030765/capital-hall-payment-schedule.pdf', '2026-08-23', 'Capital Hall is catered ("Hall Board" — includes meals), so this figure is not directly comparable to a rent-only hall. Original figure: a single room, 2026 payment schedule, annual NZ$22,070.86 (39-week hall-board year) — converted here to a monthly-equivalent (/12) then to EUR at 1 EUR = 1.9541 NZD (2026-08-21). Deposit reflects the combined Administration Fee + Residential Activity Fee + Security Deposit (NZ$1,070) on the same schedule.'),
    ('7d06d08e-4f89-4004-b3aa-4714eba3f0fc', 'e930abc2-ae26-4c67-a8da-5dca27c28ca2', 'UNIVERSITY_DORM', 'University of Otago (Residential Colleges, standard rate)', 'Dunedin', 915.60, NULL, NULL, NULL, NULL, NULL, 'https://www.otago.ac.nz/accommodation/colleges', '2026-06-02', 'otago.ac.nz returns HTTP 403 to automated fetches (reconfirmed directly 2026-08-23); content taken from a Wayback Machine snapshot of this official URL (dated 2026-06-02). Otago''s residential colleges are fully catered (meals, laundry, and linen included), so this figure is not directly comparable to a rent-only hall. Original figure: NZ$21,470/year (2026), the most common rate across colleges; the full range spans NZ$19,988/year (Aquinas College) to NZ$24,206/year (192 Castle College), with St Margaret''s College quoted "from NZ$22,490.30" — converted here to a monthly-equivalent (/12) then to EUR at 1 EUR = 1.9541 NZD (2026-08-21). No current deposit figure could be confirmed (an unverified, older third-party NZ$949 activities-fee figure was deliberately excluded rather than used).');
-- Batch: Denmark, Finland, Estonia (research/verification pass 2026-08-28).
-- FX rate used in this batch (ECB reference rate via frankfurter.dev, dated
-- 2026-08-27, retrieved 2026-08-28): 1 EUR = 7.4747 DKK. Finland and Estonia
-- both use the Euro directly, so no conversion was needed for their figures.
-- Deliberate omissions / notable findings from this batch, documented here so
-- a future reader doesn't mistake a gap for an oversight:
--  - Denmark: DTU and Aarhus University state no numeric minimum-GPA figure
--    for their MSc admissions — both instead require a minimum number of
--    ECTS credits in named prerequisite subject areas, reported verbatim in
--    each row's notes instead of a fabricated percentage. Denmark's national
--    student-visa self-support rule ("valid until 3 months before your
--    passport's expiry") is a relative cap on permit length, not an
--    applicant-facing "your passport needs N months of validity" minimum —
--    the same class of rule excluded for Sweden in the prior batch — so
--    minimum_passport_validity_months stays NULL. DTU's own accommodation
--    domains (vkr.dk, bdtu.dk/Boligfonden DTU) blocked automated fetching;
--    its rent/deposit figures come from a specialized third-party Copenhagen
--    student-housing portal (kbh-kollegier.dk) instead, dated July 2025 by
--    that page — flagged in its row's notes rather than presented as a
--    first-party DTU figure. No deposit figure is confirmed for CBS's
--    Tietgenkollegiet listing.
--  - Finland: University of Helsinki's own Rector's Decision confirms a
--    university-wide non-EU/EEA tuition band of EUR 13,000/15,000/18,000 per
--    year, but no single official page confirms which tier applies to the
--    Computer Science programme specifically (only third-party aggregators
--    claim EUR 15,000) — rather than guess between the three, no program_fees
--    tuition row is seeded for this University of Helsinki programme (its
--    EUR 100 application-fee search also came back empty, so it has no
--    program_fees row at all this batch). Aalto's HOAS deposit figure (EUR
--    500, confirmed on the University of Helsinki's own housing page for the
--    same HOAS foundation) is deliberately NOT reused on Aalto's row since
--    Aalto's own housing page doesn't restate it — left NULL rather than
--    assumed to carry over. Migri does not state a clean fixed
--    minimum-passport-validity figure, so Finland's visa row leaves that
--    column NULL like every other country except New Zealand.
--  - Estonia: TalTech's Cybersecurity MSc is the first programme seeded in
--    this project with a confirmed GRE General Test requirement (Verbal >=
--    145, Quantitative >= 150, Analytical Writing >= 3.0, waived only for
--    EU/EFTA/OECD bachelor's holders) — flagged as unusual for a European
--    Master's programme, reported as-is per this project's no-editorializing
--    sourcing rule. TalTech and Tallinn University are also this project's
--    first rows with a genuinely confirmed minimum_cgpa_percentage (60.00,
--    "at least 60% of the highest possible CGPA / maximum possible results",
--    stated verbatim as a percentage by each university, unlike every prior
--    country's qualitative or non-percentage grading scale). Estonia's
--    residence-permit financial-proof figure is deliberately left NULL: the
--    official multiplier ("four times the subsistence level") is confirmed
--    on politsei.ee, but the EUR 220/month subsistence-level figure needed to
--    compute it was only found via secondary reporting of a government
--    budget, not a directly-fetched primary sm.ee/riigiteataja.ee page, so
--    the derived EUR 880/month total is not used per this project's rule
--    against resolving a fact from an unverified secondary source. Estonia's
--    state fee (riigilõiv) amount and minimum passport validity were both
--    genuinely not stated on any official page found and are left NULL.
--    Tartu's dormitory deposit, TLU's dormitory application URL, and a
--    specific English-test score for TalTech's programme page were likewise
--    not found and are omitted rather than guessed.

