    ('6a99be62-365b-4522-aa5b-8732a6a7de30', 'efe743da-6975-418d-8d2e-3bcf8696d385', 'MSc in Computer Science', 'MASTER', 'Computer Science', 24, 'https://masters.au.dk/computerscience'),
    ('451e27db-a5a1-4616-bbce-3b5ef5273ac2', 'f7bbb041-0769-4435-a0be-513fb8c0ed07', 'MSc in International Business and Politics', 'MASTER', 'International Business and Politics', 24, 'https://www.cbs.dk/en/study-programmes/master-programmes/msc-international-business-and-politics'),
    ('6b03dfba-46b4-438b-9def-37edb2fc6ecf', '4b2944e5-c76b-4cab-b820-df95b52be5ef', 'Master''s Programme in Computer Science', 'MASTER', 'Computer Science', 24, 'https://www.helsinki.fi/en/degree-programmes/computer-science-masters-programme'),
    ('0b4af654-dd4e-4926-b1a2-7bf542bd9f91', '157a714d-1742-4c87-bc22-39300c23d6de', 'Master''s Programme in Computer, Communication and Information Sciences', 'MASTER', 'Computer Science', 24, 'https://www.aalto.fi/en/programmes/masters-programme-in-computer-communication-and-information-sciences'),
    ('b84ba65a-f2fe-4b59-a4e2-467581154476', 'def3641e-3a3a-4c8a-a5f0-8dec6c47ba33', 'Master''s Programme in Computing Sciences and Electrical Engineering (AI-native Software)', 'MASTER', 'Computer Science', 24, 'https://www.tuni.fi/en/tau/masters-programmes/software-web-cloud-computing-sciences-and-electrical-engineering'),
