    ('e8031f6f-6a33-402a-94e8-1355608b5a53', '7a0aa525-7e61-449b-a31d-10cc043f5f57', 'Master of Science in Engineering (Cybersecurity)', 'MASTER', 'Cybersecurity', 24, 'https://taltech.ee/en/masters-programmes/cybersecurity'),
    ('45f9d566-b5cb-4bcc-a528-2c49a66d1879', '7d0fe7ce-3d6e-4fca-be9d-0fb70f1fdd6c', 'Communication Management', 'MASTER', 'Communication Management', 24, 'https://www.tlu.ee/en/bfm/communication-management');

INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('b82486c8-3f24-4d14-b5b6-0f47ff50e190', 'e1266190-f478-423f-b4f4-892628a4abd6', NULL, NULL, 'IELTS', '6.5', ARRAY['certified_diploma', 'certified_transcript', 'english_test_score', 'prequalification_mapping_form'], 'https://www.dtu.dk/english/education/graduate/admission-and-deadlines/application_procedure/apply/language-test-requirements', '2026-08-28', 'IELTS Academic overall 6.5, no section below 6.0. TOEFL iBT alternative (new scale): overall 4.5, no section below 4.0. Cambridge CAE/CPE alternative: overall 180 (Cambridge B2 First/FCE explicitly does not qualify). Only test results verifiable online are accepted. No numeric minimum-GPA figure is published; the academic prerequisite is instead a minimum of 75 ECTS across four named subject areas (20 ECTS mathematics/theoretical computer science, 20 ECTS programming/computational thinking, 10 ECTS algorithmic foundations/system performance, 25 ECTS software technology/computer engineering), and the bachelor''s degree must be less than ten years old. Source for prerequisites: https://www.dtu.dk/english/education/graduate/msc-programmes/computer-science-and-engineering/prerequisites. Fully digital application; no hard-copy documents accepted.'),
    ('d61911a4-048f-434d-bda5-776978c334fa', '6a99be62-365b-4522-aa5b-8732a6a7de30', NULL, NULL, 'IELTS', '6.5', NULL, 'https://bachelor.au.dk/en/international-applicants/moreinfo/language-requirements', '2026-08-28', 'IELTS overall 6.5 (Aarhus University''s general standard, which the MSc admission page defers to rather than hosting a separate number). TOEFL alternative: 83 on the pre-21-Jan-2026 scale, or overall 4.5 with no section below 4.0 on the new post-21-Jan-2026 scale. Cambridge English Advanced (CAE): grades A/B/C or 180+ on the Cambridge English Scale; Cambridge English First: grade A or 180+. Tests older than 2 years are generally not accepted. No numeric minimum-GPA figure is published; the academic prerequisite is a bachelor''s degree comparable to a Danish bachelor''s (180 ECTS) in level and duration, plus a minimum of 80 ECTS across four named subject areas (20 ECTS each: Programming, Computer Systems, Theoretical Computer Science/HCI, Mathematics). A full itemized document checklist beyond a required credit-mapping appendix form was not confirmed in this pass and is left NULL rather than guessed.'),
    ('bc4a9d85-55b6-4cc9-a728-34b58f839723', '451e27db-a5a1-4616-bbce-3b5ef5273ac2', NULL, NULL, 'IELTS', '7.0', ARRAY['bachelor_diploma', 'official_grade_transcript', 'course_descriptions', 'english_test_score', 'personal_statement', 'passport_copy'], 'https://www.cbs.dk/en/study-programmes/master-programmes/msc-international-business-and-politics', '2026-08-28', 'IELTS Academic overall 7.0, no section below 6.0 (IELTS One Skill Retake not accepted). TOEFL iBT alternative: overall 94 on the pre-2026 scale, or overall 4.5 with no section below 4.5 on the new scale (2026 admission round). Cambridge C2 Proficiency: minimum grade C; Cambridge C1 Advanced: minimum grade C or score 185+. Tests must be no older than 2 years by the application deadline. CBS''s own admission page states explicitly there is no minimum grade point average; the academic prerequisite is instead a minimum of 60 ECTS distributed across Economics (15 ECTS, including at least 5 each of Micro/Macro), Business Administration (15 ECTS), Social Science Methodology (15 ECTS), and Politics (15 ECTS). Personal statement (max 2 A4 pages) is required if applying for a scholarship or per programme rules.'),
    ('3c7ba012-1fda-44ac-bdc6-a7d7a9cc8ba9', '6b03dfba-46b4-438b-9def-37edb2fc6ecf', NULL, NULL, 'IELTS', '6.5', ARRAY['bachelor_degree_certificate', 'transcript_of_records', 'passport_or_id_copy', 'proof_of_english_proficiency'], 'https://www.helsinki.fi/en/admissions-and-education/apply-bachelors-and-masters-programmes/apply-international-masters-programmes/proving-your-english-language-skills', '2026-08-28', 'IELTS Academic overall 6.5, minimum 6.0 in writing. TOEFL iBT alternative: overall 92, minimum 22 in writing. PTE Academic alternative: overall 62, minimum 54 in each communicative-skills section. Cambridge C1 Advanced/C2 Proficiency: pass level A/B/C. Finnish YKI: level 5 on all subtests. No numeric minimum-GPA figure is published; the official eligibility page states only that a bachelor''s degree (or recognised equivalent) is required, with no further published threshold. Programme-specific attachments beyond the core documents listed vary and were not itemized in this pass.'),
    ('7d568d70-c2df-4edc-bcfe-81922e714c89', '0b4af654-dd4e-4926-b1a2-7bf542bd9f91', NULL, NULL, 'IELTS', '6.5', ARRAY['motivation_letter', 'cv', 'official_transcripts', 'bachelor_degree_certificate', 'proof_of_english_proficiency'], 'https://www.aalto.fi/en/admission-services/language-requirements-in-masters-admissions', '2026-08-28', 'IELTS Academic overall 6.5, minimum 6.0 in writing. TOEFL iBT: for tests taken before 21 Jan 2026, overall 92 with minimum 22 in writing; for tests taken on/after 21 Jan 2026 (new TOEFL scale), overall 4.5 with no subtest below 4.0 — this dual scale reflects an official TOEFL scoring-system change and is reported as confirmed on Aalto''s own page rather than treated as an anomaly. No single numeric minimum-GPA figure is published; the programme instead states it seeks "consistently excellent grades" and gives country-specific example minimums (e.g. India 8.0/10 or 75%; China 3.50/4 or 85/100; Bangladesh 3.70/4), reported here as context rather than a normalized figure. Bachelor''s degree must be completed (proof of graduation) by 31 July. GRE/GMAT scores and a recommendation letter are noted as optional, not mandatory.'),
    ('edeb32fc-a167-44d9-af67-03f07280d449', 'b84ba65a-f2fe-4b59-a4e2-467581154476', NULL, NULL, 'IELTS', '6.5', NULL, 'https://www.tuni.fi/en/tau/masters-programmes/language-requirements', '2026-08-28', 'IELTS Academic overall 6.5, no section below 6. TOEFL iBT alternative: overall 92, no section below 20. PTE Academic alternative: overall 68, no Communicative Skills section below 61. Finnish YKI: level 5 on all subtests. No numeric minimum-GPA figure is published; the official eligibility page states selection is based on "the applicant''s bachelor''s degree... academic qualifications and merits shown in the application documents," with no numeric threshold. A full itemized document checklist page could not be rendered in this pass and is left NULL rather than guessed; scanned colour copies of original educational documents are required at application, with officially certified copies required by 29 May 2026 if admitted.'),
    ('e4826084-175c-46d1-9f48-f2944704afb3', '59d5ac73-c543-4b44-ae43-54d18da57c2b', NULL, NULL, 'IELTS', '6.0', ARRAY['motivation_letter', 'certified_bachelor_diploma', 'certified_transcript', 'proof_of_english_proficiency', 'passport_copy'], 'https://ut.ee/en/english-language-requirements', '2026-08-28', 'IELTS Academic overall 6.0, no component below 5.5 (IELTS General Training not accepted). TOEFL iBT alternative: 75 total for exams before 21 Jan 2026, or overall 4 (1-6 scale) on the new scale from 21 Jan 2026. Cambridge English (B2 First/C1 Advanced/C2 Proficiency): 169. PTE Academic (incl. online): 59. No fixed minimum-GPA figure is published; admission is instead committee-based, weighted 50% motivation letter and 50% average grade from the previous study level, with no numeric cutoff stated. Motivation letter capped at 6,000 characters. A EUR 100 application fee applies (see program_fees).'),
    ('0270a44c-7eff-4a4d-b759-ec2d911e7e0f', 'e8031f6f-6a33-402a-94e8-1355608b5a53', 60.00, NULL, NULL, NULL, ARRAY['bachelor_degree_certificate', 'gre_general_test_score_unless_waived', 'motivation_letter', 'cv', 'online_lab_assessment', 'passport_copy'], 'https://taltech.ee/en/masters-programmes/cybersecurity', '2026-08-28', 'Minimum CGPA: at least 60% of the highest possible CGPA from bachelor''s studies (waivable down to above 50% if a prior master''s degree average is at least 60%) — stated verbatim as a percentage of maximum possible CGPA, this project''s first genuinely confirmed percentage-based GPA figure. FLAGGED AS UNUSUAL: a GRE General Test score is required for most applicants (Verbal Reasoning >= 145, Quantitative Reasoning >= 150, Analytical Writing >= 3.0), waived only for bachelor''s degree holders from an EU/EFTA/OECD country — an unusual requirement for a European master''s programme, reported as-is per this project''s no-editorializing sourcing rule. English-proficiency proof is required but no specific test name/minimum score is stated on the programme page itself (TalTech''s university-wide English-test list exists at a separate URL not independently re-verified in this pass), so language_test_name/minimum_language_score are left NULL rather than guessed. Bachelor''s degree in IT/ICT required, or another field plus 1 year of IT work experience.'),
    ('c4afb9f9-872a-4c54-9f02-2bbd16981da6', '45f9d566-b5cb-4bcc-a528-2c49a66d1879', 60.00, NULL, 'IELTS', '6.0', ARRAY['bachelor_degree_certificate', 'transcript', 'proof_of_english_proficiency', 'motivation_letter', 'interview_participation'], 'https://www.tlu.ee/en/requirements-and-procedure-admission-degree-studies', '2026-08-28', 'Minimum CGPA: at least 60% of maximum possible results from bachelor''s studies — Tallinn University''s general master''s admission standard, stated verbatim as a percentage. English requirement: minimum general level B2 CEFR; IELTS Academic/Online overall 6.0, no component below 5.5. TOEFL iBT alternative: 72 total for exams before 21 Jan 2026 (min. Reading 18, Listening 17, Writing 17, Speaking 20), or overall 4 on the new scale from 21 Jan 2026 (each section min. 4). Cambridge (B2 First/C1 Advanced/C2 Proficiency): 169. PTE Academic/Online: 59 overall, min. 59 each component. Admission also includes an interview as part of the entrance-exam components. Source for English requirement: https://www.tlu.ee/en/proof-english-proficiency.');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('dba28221-b4ed-4bf4-9074-627e48216dbe', 'e1266190-f478-423f-b4f4-892628a4abd6', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://www.dtu.dk/english/education/graduate/admission-and-deadlines/application_procedure/apply/application-fee', '2026-08-28', 'DTU states this fee directly in EUR (non-EU/EEA applicants only); covers up to 2 MSc applications per intake. No conversion needed.'),
    ('d7144123-4c04-4cf0-82e3-32d6afe0ca46', 'e1266190-f478-423f-b4f4-892628a4abd6', 'TUITION_PER_YEAR', 'INTERNATIONAL', 15000.00, 'https://www.dtu.dk/english/education/graduate/fees-and-funding', '2026-08-28', 'DTU states this fee directly in EUR (non-EU/EEA/Swiss students): EUR 7,500 per semester, i.e. EUR 15,000/year; full 2-year programme total is EUR 30,000. No conversion needed. The source page states fees are "expected to be revised for the Autumn 2026 intake" — flagged as subject to change. EU/EEA/Swiss citizens are tuition-free; limited tuition-fee waivers exist for excellent non-EU/EEA applicants.'),
    ('9aaeb51c-a719-46f6-a19f-bb42e876639a', '6a99be62-365b-4522-aa5b-8732a6a7de30', 'APPLICATION_FEE', 'INTERNATIONAL', 150.00, 'https://masters.au.dk/tuitionfees', '2026-08-28', 'Aarhus University states this fee directly in EUR (non-EU/EEA/Swiss applicants only; the page also gives a DKK 1,125 equivalent); covers up to 3 applications. No conversion needed.'),
    ('153b1cfb-b0f7-4a9a-8d7a-05f4c2351219', '6a99be62-365b-4522-aa5b-8732a6a7de30', 'TUITION_PER_YEAR', 'INTERNATIONAL', 17300.00, 'https://masters.au.dk/tuitionfees/current-tuition-fee-rates', '2026-08-28', 'Aarhus University states this fee directly in EUR (non-EU/EEA/Swiss students): the Natural Sciences/Computer Science fee tier is EUR 17,300/year (2-year total EUR 34,600); AU''s humanities/social-science programmes are billed at a lower EUR 13,000/year tier not used here. No conversion needed. EU/EEA/Swiss citizens are tuition-free; limited Danish state scholarships exist for non-EU/EEA/Swiss 2-year master''s students (full tuition waiver plus up to 23 months of stipend).'),
    ('817de76e-9ee4-40d7-8fd3-b54cc3c41873', '451e27db-a5a1-4616-bbce-3b5ef5273ac2', 'APPLICATION_FEE', 'INTERNATIONAL', 150.00, 'https://www.cbs.dk/en/study/graduate/admission/non-eueea-citizens', '2026-08-28', 'CBS states this fee directly in EUR (non-EU/EEA citizens only), due 15 January for the Autumn intake. No conversion needed.'),
    ('97044bae-2bad-42a6-8f37-88fe9f6186d3', '451e27db-a5a1-4616-bbce-3b5ef5273ac2', 'TUITION_PER_YEAR', 'INTERNATIONAL', 16000.00, 'https://www.cbs.dk/en/study/graduate/admission/non-eueea-citizens', '2026-08-28', 'CBS states this fee directly in EUR (non-EU/EEA/Swiss students): EUR 8,000/semester = EUR 16,000/year (2-year total EUR 32,000); the same page also states an equivalent DKK 60,000/semester (DKK 120,000/year, DKK 240,000 total) figure directly, not derived by conversion. EU/EEA/Swiss citizens pay no application fee and no tuition.'),
    ('c51cb5fd-813b-4581-b7f3-6b4bbb04b308', '0b4af654-dd4e-4926-b1a2-7bf542bd9f91', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://www.aalto.fi/en/admission-services/masters-admissions-frequently-asked-questions', '2026-08-28', 'Non-EU/EEA applicants only, payable via Studyinfo.fi within 7 days of application. Finland uses the Euro; no conversion needed.'),
    ('b6467c0b-64d0-4ce6-b3fc-a632f62c03b4', '0b4af654-dd4e-4926-b1a2-7bf542bd9f91', 'TUITION_PER_YEAR', 'INTERNATIONAL', 17000.00, 'https://www.aalto.fi/en/programmes/masters-programme-in-computer-communication-and-information-sciences', '2026-08-28', 'Applies to study rights starting on/after 1 August 2025 (was EUR 15,000/year for study rights starting on/before 1 August 2024, not used here since it is no longer current). EU/EEA/Swiss students are tuition-free. No conversion needed.'),
    ('fa6223e1-2cda-4cab-959a-7b9c88630041', 'b84ba65a-f2fe-4b59-a4e2-467581154476', 'TUITION_PER_YEAR', 'INTERNATIONAL', 12000.00, 'https://www.tuni.fi/en/study-with-us/apply-to-tampere-university/financial-matters/tuition-fees-scholarships', '2026-08-28', 'No application fee found for Tampere University. Related tuition reductions confirmed on the same page: a highly-selective 50% Tuition Fee Scholarship, an early-bird EUR 2,000 first-year reduction for accepting/paying within 2 weeks, and a EUR 2,000 Graduation Scholarship for Tampere bachelor''s graduates completing within 3 years — none of these are guaranteed, so the full EUR 12,000/year figure is used here. No conversion needed.'),
    ('306f6ae2-7aa5-4139-9df0-f3de3e042014', '59d5ac73-c543-4b44-ae43-54d18da57c2b', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://ut.ee/en/content/application-fee', '2026-08-28', 'Non-refundable, international applicants only. Exempt: Estonian citizens, those who completed prior studies in Estonia, and certain re-applicants. No conversion needed.'),
    ('70f64178-7550-4f32-a7bc-690db76896f0', '59d5ac73-c543-4b44-ae43-54d18da57c2b', 'TUITION_PER_YEAR', 'INTERNATIONAL', 7200.00, 'https://ut.ee/en/curriculum/software-engineering', '2026-08-28', 'Free for EU/EEA/Swiss citizens and permanent residents. No conversion needed.'),
    ('32ffb40c-eb19-482a-81b1-7b3891d70301', 'e8031f6f-6a33-402a-94e8-1355608b5a53', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://taltech.ee/en/apply', '2026-08-28', 'Covers application to up to 2 programmes. No conversion needed.'),
    ('b0859807-64f8-464b-b43f-29d978b77f62', 'e8031f6f-6a33-402a-94e8-1355608b5a53', 'TUITION_PER_YEAR', 'INTERNATIONAL', 7000.00, 'https://taltech.ee/en/masters-programmes/cybersecurity', '2026-08-28', 'Free for EU/EEA citizens. No conversion needed.'),
    ('5246dae7-d8c7-453e-9246-cf0e01ff11ae', '45f9d566-b5cb-4bcc-a528-2c49a66d1879', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 2300.00, 'https://www.tlu.ee/en/bfm/communication-management', '2026-08-28', 'Stated explicitly as a per-semester figure by the official programme page, not annualized here since the source itself does not state a per-year total. No application fee was found for this programme. No conversion needed.');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('df9efe8e-0a48-484d-a323-b496c62b44d6', 'CBS Scholarship', 'Copenhagen Business School', 'DK', 'f7bbb041-0769-4435-a0be-513fb8c0ed07', NULL, 'FULL_FUNDING', 1070.28, 'Full tuition-fee waiver plus a monthly stipend of DKK 8,000 (converted at 1 EUR = 7.4747 DKK, 2026-08-27 rate) for up to 22 months, starting 1 September. Open to non-EU/non-EEA/non-Swiss citizens requiring a student residence permit to study at CBS; applicants must pay the application fee by deadline (unless holding a Danish bachelor''s degree) and submit a personal statement via the Application Portal. Not eligible if also eligible for SU (Danish State Educational Grant) or other Danish public support. Selection is based on motivation/academic merit, not financial need; approximately 25 scholarships are awarded per year. amount_eur here reflects only the monthly stipend — the separately-confirmed full tuition waiver (EUR 16,000/year, see program_fees) is not folded into one combined euro figure.', '2026-01-15', 'https://dans.stads.dk/SelfUserRegistration/faces/WelcomePage.jspx', 'https://www.cbs.dk/en/study/graduate/admission/non-eueea-citizens', '2026-08-28'),
    ('f148556b-79e6-4fac-bb73-1fb1d91afd0e', 'University of Helsinki Tuition Fee Waiver Scholarship Programme', 'University of Helsinki', 'FI', '4b2944e5-c76b-4cab-b820-df95b52be5ef', NULL, 'PARTIAL_TUITION', NULL, 'Waives either 100% (full) or 50% (partial) of tuition for the 2-year master''s programme, depending on award tier; amount_eur is left NULL because the applicable tuition figure depends on which of the university''s three tuition tiers (EUR 13,000/15,000/18,000 per year) a given programme falls under, and no single official page confirms that assignment for Computer Science specifically. Open to non-EU/EEA tuition-fee-liable students admitted to a University of Helsinki international master''s programme; awarded based on prior academic performance, motivation letter, and other supporting information; the number of awards per programme scales with the size of the admitted tuition-fee-liable cohort per a stated formula. Continuation into year 2 requires at least 55 completed ECTS credits in year 1. No separate application: automatically considered as part of the master''s programme admission application (same form/deadline).', NULL, NULL, 'https://riihiweb.it.helsinki.fi/riihidata/public/b8668965-0f65-46ca-b0d5-7e5bc9d17a2c/Tuition_fees_and_related_scholarships_0606_2025.pdf', '2026-08-28'),
    ('f22d7afe-43f2-47a3-83d3-be5570d1af8f', 'Estonian Government Scholarship (Scholarship for Degree and Exchange Study in Estonia)', 'Estonian Ministry of Education and Research / Education and Youth Board (HARNO)', 'EE', NULL, NULL, 'LIVING_STIPEND', 350.00, 'Monthly stipend of EUR 350 at bachelor''s/master''s level (EUR 660/month at doctoral level, not used here); does not separately cover tuition. Open only to foreign students from specified partner countries under bilateral agreements; bachelor''s-level awards are restricted to Estonian language/culture-related fields, while master''s/doctoral awards are open to all fields. Historically only around 10% of applicants receive the scholarship each year. Applications are submitted by email (rvo.dokumendid@harno.ee, subject line "Scholarship for degree and exchange study in Estonia") with a completed application form, passport/ID copy, and an Estonian higher-education-institution confirmation letter — no online application portal URL is published, so application_url is left NULL rather than substituting the informational page. The separate Kristjan Jaak Scholarship was deliberately excluded: it funds Estonian citizens/permanent residents studying abroad, not international students studying in Estonia.', '2026-10-01', NULL, 'https://harno.ee/en/scholarships-and-grants/scholarships-studying-and-working-estonia/scholarships-international', '2026-08-28');

INSERT INTO living_cost_estimates (estimate_id, country_code, city, university_id, category, monthly_estimate_eur, source_url, source_checked_on, notes) VALUES
    ('a14dde76-b18f-4e7b-8f14-107db4c4a91a', 'DK', NULL, NULL, 'GENERAL', 993.48, 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher-Education', '2026-08-28', 'Denmark''s official immigration authority (SIRI) documented self-support/financial-proof figure for a student residence permit, 2026 level: DKK 7,426/month, converted at 1 EUR = 7.4747 DKK (2026-08-27 rate). This is an immigration financial-sufficiency threshold, not an independent general cost-of-living survey figure — see the visa_requirements row for the same figure''s official annual cap.'),
    ('cbed6c8a-e5b6-403a-bba1-ba25ea5fd194', 'FI', NULL, NULL, 'GENERAL', 800.00, 'https://migri.fi/en/income-requirement-for-students', '2026-08-28', 'Finnish Immigration Service (Migri) official minimum documented figure for students studying less than 1 year: EUR 800/month (consistent with the >= 1 year requirement of a EUR 9,600 lump sum, i.e. EUR 800/month equivalent — see visa_requirements). Lower Migri tiers apply if the institution provides free accommodation (EUR 400/month) or free accommodation plus meals (EUR 270/month) — not used here. For informational comparison only (not used as the seeded figure, since it is a broader recommendation rather than an official minimum): Study in Finland''s own portal recommends EUR 900-1,200/month generally, and the University of Helsinki''s own page states Helsinki-specific living costs of EUR 1,000-1,300+/month.'),
    ('7aca12ae-f2eb-4f48-b6a1-ecb93ff0d9bc', 'EE', NULL, NULL, 'GENERAL', 300.00, 'https://www.studyinestonia.ee/living/living-costs', '2026-08-28', 'Study in Estonia (the official national education-promotion portal) states an overall student living-cost range of EUR 300-500/month (dormitory EUR 150-350/month, private flats EUR 350-750/month, food ~EUR 300/month), citing an iGraduate 2019 international-student survey in which roughly 50% of students spend around EUR 300/month, 25% spend more than EUR 400/month, and 10% spend more than EUR 500/month. The lower/typical EUR 300/month figure is used here, with the full range disclosed. Estonia''s residence-permit financial-proof requirement (a multiplier of the national subsistence level) is deliberately NOT used as this row''s figure since the subsistence-level component could not be confirmed on a directly-fetched primary government page in this pass — see visa_requirements notes.');

INSERT INTO visa_requirements (visa_requirement_id, destination_country_code, applicant_country_code, visa_type, financial_proof_eur, estimated_processing_days, minimum_passport_validity_months, required_documents, application_url, source_url, source_checked_on, notes) VALUES
    ('a1c7d33f-e50c-4707-809c-a8e6c8581d88', 'DK', NULL, 'RESIDENCE_PERMIT', 11921.82, 60, NULL, ARRAY['passport_copies_all_pages', 'proof_of_self_support_or_scholarship_or_student_loan', 'proof_of_paid_processing_fee', 'proof_of_enrollment'], 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher-Education', 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher-Education', '2026-08-28', 'Covers the residence permit as a student, issued by SIRI (Danish Agency for International Recruitment and Integration). Financial-proof figure shown is SIRI''s official annual cap on the documented self-support requirement (DKK 89,112, i.e. DKK 7,426/month capped at 12 months for studies exceeding a year), converted at 1 EUR = 7.4747 DKK (2026-08-27 rate) — see living_cost_estimates for the raw monthly DKK/EUR figure. Only liquid, immediately accessible assets are accepted; cryptocurrency is explicitly not accepted and must be converted to DKK or another fiat currency first. Processing time is normally around 2 months (60 days, used here), officially up to 3 months (90 days) if additional information is required. A processing fee of DKK 3,060 (EUR 409.38, same conversion) also applies and is disclosed here rather than treated as a factual field of this table. Passport validity: the official rule states only that "a residence permit can only be valid until 3 months before the expiry date of your passport" — a cap on how long the permit itself can run relative to the passport, not an applicant-facing "your passport needs at least N months of validity" minimum, so minimum_passport_validity_months is left NULL (the same class of relative rule excluded for Sweden in the prior batch).'),
    ('7590d0d7-2d9d-428c-b215-d0106a2fe4dd', 'FI', NULL, 'RESIDENCE_PERMIT', 9600.00, 30, NULL, ARRAY['valid_passport', 'passport_photo', 'certificate_of_acceptance', 'bank_statement_six_months', 'health_or_travel_insurance_proof', 'tuition_fee_payment_or_scholarship_documentation'], 'https://enterfinland.fi/eservices/ole/opi', 'https://migri.fi/en/residence-permit-application-for-studies', '2026-08-28', 'Covers the Finnish Immigration Service (Migri) residence permit for studies (OLE_OPI) — a continuous (A) permit for higher-education degree students. Financial-proof figure shown (EUR 9,600) is Migri''s official minimum bank-account requirement for studies of one year or longer, documented via a 6-month bank statement in the student''s own name; see living_cost_estimates for Migri''s lower monthly-equivalent tiers for shorter studies or subsidised accommodation/meals. Processing time is normally about 1 month (30 days, used here); Migri states up to 3 months (90 days) in a minority of cases, which is the legal maximum. Migri''s official pages do not state a clean fixed minimum-passport-validity figure, so that column is left NULL, consistent with every seeded country except New Zealand. For applicants under 18: a birth certificate and parental/guardian consent are additionally required (not itemized in the array above).'),
    ('dfef131d-3909-48e7-a6ec-df3ac80928b6', 'EE', NULL, 'RESIDENCE_PERMIT', NULL, 90, NULL, ARRAY['residence_permit_application_form', 'biographical_data_form', 'supplementary_questionnaire', 'passport_or_travel_document', 'document_photo', 'admission_or_invitation_confirmation_letter', 'proof_of_sufficient_income', 'health_insurance_contract'], NULL, 'https://www.politsei.ee/en/instructions/residence-permit-for-study', '2026-08-28', 'Covers the temporary residence permit for studies, issued by the Police and Border Guard Board (Politsei- ja Piirivalveamet). financial_proof_eur is deliberately left NULL: the official page confirms only a multiplier rule ("sufficient income of four times the subsistence level"), and the EUR 220/month subsistence-level figure needed to compute an absolute number was found only via secondary reporting of a government budget rather than a directly-fetched primary sm.ee/riigiteataja.ee page — this project''s rule against resolving a fact from an unverified secondary source applies. Processing time is stated as 90 days for a decision, with the physical residence-permit card issued within a further 30 days after that (90 days used here as the decision timeline). No minimum passport validity is stated as a clean fixed number. The state fee (riigilõiv) amount for this permit was also not found on any official page despite repeated searches and is left out of this table entirely (it is not one of this table''s modeled columns). No separate online application-portal URL is stated on the source page (the process is via the Police and Border Guard Board''s e-service, not named explicitly there), so application_url is left NULL.');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('24da1fe6-eb3f-4031-a0ba-56406410f3c8', 'dc9e6b2b-bb43-4dd4-b8b1-119e11588143', 'UNIVERSITY_DORM', 'Villum Kann Rasmussen Kollegiet (VKR Kollegiet), via PKS', 'Kongens Lyngby', 449.25, 1374.50, NULL, ARRAY['furnished', 'internet_included', 'heating_included', 'shared_kitchen', 'shared_bathroom'], NULL, 'acco@adm.dtu.dk', 'https://kbh-kollegier.dk/en/spot-en/villum-kann-rasmussen-kollegiet/', '2026-08-28', 'DTU''s own accommodation domains (vkr.dk, and Boligfonden DTU''s bdtu.dk) blocked automated fetching; these figures come from a specialized third-party Copenhagen student-housing information portal instead, which itself dates the figures to July 2025 — flagged here rather than presented as directly confirmed by DTU or VKR''s own site. Original figures: DKK 3,358/month (inclusive of water, heating, electricity, resident contribution, antenna and internet) and a DKK 10,274 deposit, both converted at 1 EUR = 7.4747 DKK (2026-08-27 rate). DTU''s official accommodation contact (Boligfonden DTU) is acco@adm.dtu.dk, confirmed directly on DTU''s own site. 12 sqm rooms with shared corridor kitchen/bathroom access.'),
    ('8bc879eb-0bc3-4f87-b259-41ee6321c5e0', 'efe743da-6975-418d-8d2e-3bcf8696d385', 'UNIVERSITY_DORM', 'Kollegierne i Universitetsparken (Parkkollegierne P/S)', 'Aarhus', 520.56, 1561.67, NULL, ARRAY['electricity_included', 'heating_included', 'water_included', 'cable_tv_included'], 'https://koll.au.dk', 'kontoret@pkas.dk', 'https://koll.au.dk/information/huslejen', '2026-08-28', 'Original figure: DKK 3,891.00/month (2026 rate, renovated Kollegium 1/2/3/6/8/9, used here as the standard rate) — non-renovated rooms (Kollegium 4/5) are DKK 2,818.00/month and accessible rooms (Kollegium 1) are DKK 5,586.00/month, neither seeded separately. Converted at 1 EUR = 7.4747 DKK (2026-08-27 rate). Deposit is stated as a rule ("equivalent to three months'' rent") rather than a flat figure, so the deposit shown here (DKK 11,673 = 3 x 3,891) is derived from that stated rule and converted the same way. Internet is DKK 20.00/month extra, not included in rent. Rent adjusts annually via the net price index. Located within Universitetsparken, directly adjacent to Aarhus University; no distance figure is stated in km.'),
    ('a96ccd87-d9c1-401e-9a67-4c65c0111e0c', 'f7bbb041-0769-4435-a0be-513fb8c0ed07', 'PRIVATE_HALL', 'Tietgenkollegiet', 'Copenhagen', 538.21, NULL, NULL, ARRAY['shared_kitchen', 'common_room', 'laundry', 'gym', 'bicycle_parking'], 'https://tietgenkollegiet.dk/en/tour/', 'info@tietgenkollegiet.dk', 'https://tietgenkollegiet.dk/en/the-dorm/', '2026-08-28', 'Tietgenkollegiet is an independently-run kollegium in Ørestad North, Copenhagen, listed by CBS as a CBS-affiliated housing option (not a CBS-operated building). Original figure: the lowest published room tier, Type A (26 sqm), DKK 4,022.97-4,334.60/month; larger tiers run up to Type D (45 sqm, two-room), DKK 6,657.71-6,969.37/month — the Type A lower bound is used here, converted at 1 EUR = 7.4747 DKK (2026-08-27 rate). No deposit figure is stated on the official kollegium page. Distance to CBS campus in km is not stated (the building is in Ørestad North with metro access to central Copenhagen). Shared kitchens serve 1 per 12 residents; other amenities include an event hall, reading room, music rooms, workshops, and outdoor courts.'),
    ('a29e7583-20d2-40bb-b0f9-f86a83ba59a4', '4b2944e5-c76b-4cab-b820-df95b52be5ef', 'UNIVERSITY_DORM', 'HOAS (Foundation for Student Housing in the Helsinki Region)', 'Helsinki', 633.00, 500.00, NULL, ARRAY['electricity_included', 'water_included', 'internet_included', 'shared_kitchen'], 'https://hoas.fi/en', NULL, 'https://studies.helsinki.fi/instructions/article/housing-option-international-bachelors-and-masters-degree-students', '2026-08-28', 'HOAS offers several unit types for degree students; the lower end of its Studio tier (EUR 633-890/month) is used here as the most directly comparable standalone unit. Other tiers: shared studio EUR 398-485/month; room in a shared apartment EUR 454-584/month — neither seeded separately. Deposit is EUR 500 (confirmed on this same University of Helsinki page). No fixed distance to campus is stated; HOAS states only that it "aims to offer an apartment close to or with good public transport links to your study campus." No conversion needed (Finland uses the Euro).'),
    ('1d8f5510-4963-40b3-a741-e82cef768f7a', '157a714d-1742-4c87-bc22-39300c23d6de', 'SHARED_APARTMENT', 'HOAS (Foundation for Student Housing in the Helsinki Region), Otaniemi/Espoo', 'Espoo', 250.00, NULL, NULL, ARRAY['internet_included', 'sauna_reservable', 'laundry_reservable'], 'https://www.aalto.fi/en/services/housing-for-students', 'housing@ayy.fi', 'https://www.aalto.fi/en/services/housing-for-students', '2026-08-28', 'Aalto''s own official housing page states a shared-apartment room range of EUR 250-500/month (the lower bound is used here); other tiers on the same page are a two/three-room apartment (EUR 600-1,000/month) and a studio (EUR 580-750/month), neither seeded separately. No deposit figure is restated on this Aalto-specific page — the University of Helsinki''s page for the same HOAS foundation confirms a EUR 500 deposit for degree students generally, but that figure is deliberately not reused here since Aalto''s own page does not restate it. HOAS locations closest to Aalto''s campus are Otaniemi-Teekkarikylä and Otaniemi-Tapiola; no distance figure in km is stated. No conversion needed (Finland uses the Euro).'),
    ('1de8f09e-fb92-4eff-9588-a5f0f0920408', 'def3641e-3a3a-4c8a-a5f0-8dec6c47ba33', 'SHARED_APARTMENT', 'TOAS (Tampere Student Housing Foundation)', 'Tampere', 212.00, 300.00, NULL, ARRAY['furnished_bedroom', 'shared_kitchen'], 'https://toas.fi/en/application-for-a-furnished-room/', NULL, 'https://toas.fi/en/find-your-apartment/', '2026-08-28', 'TOAS does not publish one official "typical rent" figure; live official listings show a wide range depending on apartment type and location (roughly EUR 152 to over EUR 1,200/month across all stock), with shared-apartment rooms specifically observed in the EUR 212-740/month range — the lower end of that shared-room range is used here as an indicative figure rather than a single confirmed rate. Deposit (EUR 300) is confirmed specifically for the Furnished Room / International Application track. Furnished bedroom includes a bed, mattress, desk, chair, and bookshelf; the shared kitchen has a stove/oven/fridge; bedding and towels are explicitly not included. The Autumn 2026 Furnished Room application round was already closed as of the check date. No distance-to-campus figure is stated. No conversion needed (Finland uses the Euro).'),
    ('0b3940ca-1800-4463-871a-9810a67c0738', '0dae2de7-6576-47a6-90e2-33e76dee20f6', 'UNIVERSITY_DORM', 'Tartu Student Village (Tartu Üliõpilasküla / campus.ee)', 'Tartu', 175.50, NULL, NULL, ARRAY['furnished'], 'https://www.campus.ee/en/applicant/', NULL, 'https://www.campus.ee/en/residence-halls/', '2026-08-28', 'Original figure: from EUR 175.50/month, the lowest published rate shared by the Narva mnt 25, Raatuse 22, and Narva mnt 27 residence halls (Narva mnt 25 is about a 5-minute walk from University of Tartu''s main building, per https://ut.ee/en/content/arrival-and-housing). Other halls: Pepleri 14 from EUR 175/month, Nooruse 7 from EUR 182/month — neither seeded separately. No deposit figure is stated. Priority is given to University of Tartu degree students. Ancillary fees (e.g. parking EUR 15-30/month, a one-time EUR 65 bedding set) are excluded from the rent figure. No conversion needed (Estonia uses the Euro).'),
    ('a56f400b-e30f-406a-8f90-90c40cd211c5', '7a0aa525-7e61-449b-a31d-10cc043f5f57', 'STUDIO_APARTMENT', 'TalTech Student Housing (Akadeemia 11/2)', 'Tallinn', 440.00, 440.00, NULL, ARRAY['furnished', 'private_bathroom', 'kitchenette', 'wifi_included', 'laundry', '24_7_security'], 'https://app.campusttu.ee/en', NULL, 'https://taltech.ee/en/student-housing/akadeemia-11-2', '2026-08-28', 'Fixed monthly rent (EUR 440), inclusive of all utilities (heating, water/sewer, electricity); deposit is also EUR 440. Fully furnished single rooms with a kitchenette and private toilet/shower. Stated as "a 5-7 minute walk from the university''s academic buildings" — no distance figure in km is given. No conversion needed (Estonia uses the Euro).'),
    ('fe4e4eda-f6fa-4735-bbac-03cde0934756', '7d0fe7ce-3d6e-4fca-be9d-0fb70f1fdd6c', 'UNIVERSITY_DORM', 'Tallinn University Dormitory (Karu 17)', 'Tallinn', 215.00, 470.00, NULL, ARRAY['furnished', 'shared_kitchen', 'wifi_included', 'laundry', 'bed_linen_included', 'bicycle_storage'], NULL, NULL, 'https://www.tlu.ee/en/dormitory', '2026-08-28', 'Original figures: a smaller double room (14 sqm) at EUR 215/month (EUR 230/month if newly renovated) with a EUR 470 deposit (EUR 490 if renovated); a bigger double room (17 sqm) is EUR 245/month (EUR 260/month if renovated) with a EUR 520 (or EUR 550) deposit — the smaller/standard-rate room is used here. Located on Tallinn University''s main campus (Karu Street 17), behind the Terra building, city center — no distance figure in km is given since it is on-campus. No public application URL is stated; the page notes a link is provided only after official acceptance. No conversion needed (Estonia uses the Euro).');

-- Batch: Lithuania, Latvia, Romania (research/verification pass 2026-08-28).
-- FX rate used in this batch (ECB reference rate via frankfurter.dev, dated
-- 2026-08-28): 1 EUR = 5.2584 RON. Lithuania and Latvia both use the Euro
-- directly (LT since 2015, LV since 2014), so no conversion was needed for
-- their figures.
-- Deliberate omissions / notable findings from this batch, documented here so
-- a future reader doesn't mistake a gap for an oversight:
--  - Lithuania: migracija.lt (the national Migration Department site) is a
--    JS-rendered single-page app that returned no text content via direct
--    fetch, curl, or Wayback Machine; the visa row instead relies on an
--    official Vytautas Magnus University (VDU) PDF that itself compiles and
--    cites current migracija.lt/MIGRIS rules (document internally dated
--    2025-02, still live and fetched 2026-08-28 — source_checked_on reflects
--    the fetch date, with the document's own older vintage flagged in notes).
--    Its stated passport-validity rule ("valid for at least 3 months after
--    the expiry date of the requested TRP") is relative to the permit's own
--    length, not a fixed number, so minimum_passport_validity_months is left
--    NULL — same discipline applied to Denmark's relative rule in the prior
--    batch. KTU's standard-bachelor application-fee amount could not be
--    confirmed (the only "100 EUR" figure found on its page is explicitly
--    attached to transfer-studies applicants, not general admission), so no
--    APPLICATION_FEE row is seeded for KTU. KTU's own vague "Scholarship for
--    International Students" (unstated waiver percentage) is not seeded as a
--    separate row since VILNIUS TECH's tiered, fully-detailed scholarship
--    already covers the same ground for this batch. VILNIUS TECH's tuition
--    figure has two different official numbers across two of its own pages
--    (EUR 4,201/year on the specific programme page vs. EUR 4,950/year on
--    the university-wide non-EU Engineering/IT/Technologies fee table) — the
--    higher, explicitly non-EU-tier figure is used here and the discrepancy
--    is disclosed in that row's notes rather than silently picking one.
--  - Latvia: Riga Technical University's own domain (rtu.lv / apply.rtu.lv)
--    returned HTTP 403 to both the fetch tool and direct curl on every
--    attempt; its data (programme, admission, fees, accommodation) comes
--    from Wayback Machine snapshots, with each snapshot's own date recorded
--    as source_checked_on. The Latvian State Scholarship's confirmed EUR 500/
--    month figure is stated by the source only for second-cycle (Master's)
--    programmes — no bachelor's-level EUR figure is published, and this is
--    disclosed rather than assumed to also apply at bachelor's level. RSU's
--    "International Business and Start-up Entrepreneurship" tuition figure
--    (quoted by the research pass as "3,300 EUR (3 years)") is ambiguous
--    between a per-year and a whole-programme total on the source page — no
--    tuition fee row is seeded for RSU as a result, though its unambiguous
--    EUR 100 application fee is. RSU's own "Students-Ambassadors Scholarship"
--    is excluded: it targets Medicine/Dentistry students specifically (not
--    the Business programme seeded here) and cites a stale 2024 deadline.
--    OCMA's residence-permit page states neither a processing-time figure nor
--    a minimum passport validity — both left NULL rather than assumed.
--  - Romania: all RON figures are converted at 1 EUR = 5.2584 RON, shown
--    alongside the original RON figure in each row's notes. The Government
--    of Romania Scholarship's monthly stipend amount is not published on any
--    official page found (only "monthly financial aid, in accordance with
--    the legislation in force," with no number) — seeded with amount_eur
--    NULL rather than a guessed figure. Babeș-Bolyai University's tuition is
--    officially published as a EUR 600/month rate paid over 9 or 10 months
--    depending on the study year (per its Senate fee regulation); this batch
--    derives a TUITION_PER_YEAR figure using the lower, 9-month bound
--    (EUR 5,400), with the full calculation and the possible 10-month/
--    EUR 6,000 alternative disclosed in that row's notes rather than
--    silently picking one. University of Bucharest's non-EU bachelor's
--    application deadline and its dormitories' rent/deposit figures are not
--    published on any official page found and are both left unseeded. IGI's
--    (Romanian immigration authority) visa and residence-permit pages state
--    neither a minimum passport validity nor an absolute minimum-funds EUR
--    figure (only "a minimum net wage at country level," itself not
--    quantified on that page) — both left NULL rather than assumed.

