    ('5f0a68df-ef4d-4a7f-ab54-aeb110a0482c', '3d7fe0be-6cd7-4b61-b1b2-19160b746649', 'Informatics', 'BACHELOR', 'Computer Science', 48, 'https://admissions.ktu.edu/programme/b-informatics/'),
    ('79224a9f-9dd8-4e15-b815-676146b7911a', '3942c50b-fdd3-4112-a110-996c540546ec', 'Computer Engineering', 'BACHELOR', 'Computer Engineering', 48, 'https://apply.vilniustech.lt/courses/course/26-bachelor-computer-engineering'),
    ('fc79fa21-1992-4fc4-a680-0358a686f928', 'db3b4b3e-5645-4a82-808b-ff43e571091a', 'Biotechnology and Bioengineering', 'BACHELOR', 'Biotechnology', 36, 'https://www.lu.lv/en/studies/study-programmes-1/bachelors-study-programmes/biotechnology-and-bioengineering/'),
    ('ce5a611c-c9e9-4a71-90c4-b14d08402a86', '6dced863-e5f6-4488-a29e-2d77fac1e0c4', 'MSc Computer Systems', 'MASTER', 'Computer Systems', 24, 'https://apply.rtu.lv/courses/course/16-msc-computer-systems'),
