    ('48c86563-60e7-4add-935b-44337724ba40', 'daa62780-e575-4dbb-aeec-b22d5774779d', 'MEng Cloud Computing and Internet of Things', 'MASTER', 'Cloud Computing', 24, 'https://apply.upt.ro/courses/course/43-meng-cloud-computing-and-internet-things'),
    ('14bd6043-90f4-4821-b69d-324c361025c2', '5934ea53-d095-40f3-9e65-c9b8336be88f', 'Business Administration', 'BACHELOR', 'Business Administration', 36, 'https://faa.ro/studii/licenta/business-administration.html');

INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('41f6bffe-e0dc-4992-8d39-e4f70e1e101f', 'eeb3b887-779c-439a-a28a-23b7adf0aa43', NULL, NULL, 'IELTS', '6.5', ARRAY['motivation_letter', 'reference_letter'], 'https://apply.vu.lt/courses/course/92-quantitative-economics', '2026-08-28', 'No overall CGPA/percentage figure is published; the page states only "the average grade of Mathematics subject no less than 7.5 points converted to a 10-point grading scale," a single-subject threshold, not a general CGPA, so left NULL rather than reduced to one percentage. Also accepted: TOEFL iBT 81+, Cambridge English 176+, Pearson PTE Academic 59+, LanguageCert IESOL B2, Duolingo 120+. "The gap since your completed secondary degree should not exceed five years." At least 1 reference and a motivation letter required. Applicants from Bangladesh, Nepal, or Pakistan must also submit an OMPT-A Online Mathematics Placement Test certificate (minimum passing grade 55%). No fixed calendar deadline is published on this page (shown per-citizenship in the live application portal); studies commence 1 September 2026.'),
    ('fcd6ffb2-c962-4d9c-8c34-a29e2b775ae3', '5f0a68df-ef4d-4a7f-ab54-aeb110a0482c', 60.00, NULL, 'IELTS', '5.5', NULL, 'https://admissions.ktu.edu/bachelor/', '2026-08-28', 'Quoted verbatim: "Minimum average grade (CGPA) >60% in each entry subject." Entry-score weighting: Mathematics 50%, Information Technologies or a related subject 30%, English language 20%. TOEFL alternative: 75; CEFR alternative: B2. Non-EU/Belarus/Ukraine applicants'' documents must be legalised (Apostille). No specific documents checklist is itemised on this page beyond the legalisation requirement, so left NULL rather than guessed. General admission deadline (university-wide, per https://en.ktu.edu/news/ktu-opens-admissions-for-international-students-2026/, checked 2026-08-28): "Apply by June 1, 2026." No APPLICATION_FEE row is seeded for this programme in program_fees: the only "100 EUR" figure found on KTU''s bachelor''s admissions page is explicitly attached to transfer-studies applicants, not general first-time admission, so it is not seeded as a general application fee.'),
    ('ac943101-cbdb-45c7-80b4-713650c4d520', '79224a9f-9dd8-4e15-b815-676146b7911a', 60.00, 7500.00, 'IELTS', '5.5', ARRAY['motivation_letter', 'reference_letter'], 'https://vilniustech.lt/for-international-students/admission-20262027-------scholarships/admission-requirements-for-international-students/51029', '2026-08-28', 'Quoted verbatim from the programme''s own course page: "Minimum 60% of maximum possible results in mathematics, physics/another science subject/social science subject and English language are required." That programme page names accepted English certificates (Cambridge English, IELTS, TOEFL, or equivalent) but states no numeric minimum score; the IELTS 5.5 / TOEFL score here is instead taken from VILNIUS TECH''s separate university-wide admission-requirements page for international students (same URL as source_url) — the two pages are not perfectly consistent, and both are disclosed rather than silently reconciled. At least 2 references and a motivation letter are required (per the programme page). official_funds_requirement_eur reflects a bank-account minimum stated on VILNIUS TECH''s tuition-and-fees page ("Students must open a bank account in Vilnius with at least 7500 EUR/year") — a subsistence/visa-support figure disclosed on an admissions-adjacent page, not a strictly admissions-specific criterion, flagged here rather than presented as a normal entrance requirement.'),
    ('ea0155c9-6ee9-4ede-9030-a76eca7be301', 'fc79fa21-1992-4fc4-a680-0358a686f928', 60.00, NULL, 'IELTS', '6.0', NULL, 'https://www.lu.lv/en/admission/for-international-students/degree/language-proficiency/', '2026-08-28', 'Original figure quoted verbatim from the programme page: "Average secondary certificate grade ≥6/10" (Latvia''s 10-point secondary-school grading scale); converted here to a percentage-equivalent (60.00) for consistency with this column''s percentage basis. Also required (same page): "minimum 8/10" in each of Mathematics, Physics, Chemistry, or Biology (a per-subject threshold, not folded into the overall figure above); "All grades ≥4/10 (passing)"; SAT score ≥1200; an online interview. TOEFL iBT alternative: 80 (for tests taken on/before 21 Jan 2026) or 4 (ETS''s post-rescale scale, quoted verbatim as stated). Application deadline: 1 December 2025 (general); 5 July 2026 (state-funded places only). No documents checklist beyond the above is itemised on this page, so left NULL rather than guessed.'),
    ('69f0ad3a-ec91-4728-9213-86d96d8ed6dc', 'ce5a611c-c9e9-4a71-90c4-b14d08402a86', NULL, NULL, 'IELTS', '5.5', ARRAY['motivation_letter', 'reference_letter'], 'https://apply.rtu.lv/courses/course/16-msc-computer-systems', '2025-12-31', 'rtu.lv and apply.rtu.lv returned HTTP 403 to both the fetch tool and direct curl on every attempt; content taken from a Wayback Machine snapshot of this official URL, dated 2025-12-31 (used as source_checked_on). No numeric overall CGPA/percentage figure is published; entry instead requires an undergraduate diploma in a named related field (computer control and computer science, computer systems, information technology, intelligent robotic systems, electrical science, mathematics, or physics). TOEFL iBT alternative: 72; also accepted: TOEFL paper-based 532, TOEIC 780, Cambridge B2 First, Pearson PTE 59, Duolingo 100. At least 1 reference and a motivation letter required, plus an online interview and an online "Computer Systems exam" (Mathematics, Algorithmizing, Data Structures, Programming, Databases sections).'),
    ('ce7daa16-69fb-4928-aec7-c68c1292ecac', '6fa6daad-ff0c-4d26-85c7-43daab2fa72f', NULL, NULL, 'IELTS', '6.0', NULL, 'https://www.rsu.lv/en/requirements-english-proficiency', '2026-08-28', 'No numeric overall CGPA/percentage figure is stated for this programme (unlike RSU''s Medicine "70%+" or Dentistry "80%+" pages, which do publish one) — the general requirement is only "at least passing grades" in secondary subjects, including compulsory English and Mathematics (Latvian is also compulsory for standard Latvian-diploma holders). TOEFL iBT alternative: 80. Application windows for the September 2026 intake (per https://www.rsu.lv/en/study-here/admissions/when-apply, checked 2026-08-28): EU/EEA and visa-free-country applicants 1 Sep 2025 - 1 Jul 2026; Additional Assessment Countries 1 Sep 2025 - 1 Apr 2026; other non-EU/EEA 1 Sep 2025 - 1 May 2026. No documents checklist beyond the above is itemised on the pages checked, so left NULL rather than guessed.'),
    ('bb9f8fef-a06f-4f19-ae7e-75cbd5e48615', '903d0411-6bed-4444-8a8c-a930259c4223', NULL, NULL, NULL, NULL, ARRAY['passport_copy', 'high_school_diploma_certified_translation', 'birth_certificate_certified_translation', 'medical_certificate', 'motivation_letter', 'language_proficiency_certificate'], 'https://cci.ubbcluj.ro/admission-international-students/candidates-from-other-countries/bachelor/', '2026-08-28', 'No numeric overall CGPA/percentage figure or a named minimum language-test score is published for general bachelor''s admission — the page lists accepted language-proficiency certificates without a numeric cutoff, so both are left NULL rather than guessed (the "average of at least 7/10" figure found elsewhere on UBB''s site is a Government of Romania Scholarship eligibility criterion, not a general admission requirement, and is not repeated here). Passport must be "valid for at least 8 months." Registration period: 1 April 2026 - 31 July 2026. Medical certificate must be issued within 3 months of application; motivation letter capped at 200-300 words.'),
    ('ca4cfa8b-093d-4c7e-9cdc-4f35e0a3854a', '48c86563-60e7-4add-935b-44337724ba40', NULL, NULL, NULL, NULL, ARRAY['bachelor_diploma_certified_translation', 'official_transcript_certified_translation'], 'https://international.upt.ro/en/international-students/students-from-countries-outside-the-eu-eea-or-the-swiss-confederation/2026-2027/non-eu-admissions/', '2026-08-28', 'No numeric overall CGPA/percentage figure is published (only "a bachelor''s degree or an equivalent diploma" is required for entry). English requirement: proof via one of TOEFL, Cambridge, IELTS, LCCI, Trinity ISE, or ECL, OR proof of at least 2 years of English-medium instruction — no specific numeric minimum score is stated on the official page, so left NULL rather than guessed. 2026-2027 application window: 1 March 2026 - 31 August 2026, 4pm Romanian time (GMT+3).'),
    ('ccfde486-e461-4a9c-b6c4-9babc979c153', '14bd6043-90f4-4821-b69d-324c361025c2', 70.00, NULL, 'CEFR', 'B1', ARRAY['diploma_or_equivalent_certified_translation', 'official_transcript_certified_translation', 'language_proficiency_certificate'], 'https://international.unibuc.ro/home-3/admission-2026-2/study-cycles/bachelors-degree-for-non-eu-candidates/', '2026-08-28', 'Original figure quoted verbatim: "7/10 minimum admission grade" (Romania''s 10-point grading scale); converted here to a percentage-equivalent (70.00) for consistency with this column''s percentage basis. Language requirement quoted verbatim: "B1 language level proficiency"; accepted certificates: Cambridge, IELTS Academic, PTE Academic, TOEFL, or Trinity — the page explicitly states "DUOLINGO tests are NOT accepted as language certificates." A non-refundable 100 EUR admission fee applies (seeded separately in program_fees). No specific application deadline for the non-EU bachelor''s cycle is published on the pages checked, so left unstated here rather than guessed. A lower-confidence, unverified claim (an English motivational essay specific to the Faculty of Business and Administration) was found only via search-engine summaries of faa.ro, not a directly fetched official page, and is deliberately excluded from this row.');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('d84c02e4-8866-4fed-a860-0a0bf5fb79ac', 'eeb3b887-779c-439a-a28a-23b7adf0aa43', 'TUITION_PER_YEAR', 'INTERNATIONAL', 3660.00, 'https://apply.vu.lt/courses/course/92-quantitative-economics', '2026-08-28', 'Stated directly in EUR by Vilnius University — no conversion needed. Page notes: "Tuition fee is subject to change in accordance with national legislation," and a 50% tuition-fee reduction applies for Ukrainian students (not reflected in this figure).'),
    ('f8cb59d2-ad17-4f3e-82fc-e948dc0624ad', 'eeb3b887-779c-439a-a28a-23b7adf0aa43', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://apply.vu.lt/courses/course/92-quantitative-economics', '2026-08-28', 'Stated directly in EUR. Quoted verbatim: "The application fee is non-refundable."'),
    ('7d460a17-ca6b-43d1-9705-704a83923ad2', '5f0a68df-ef4d-4a7f-ab54-aeb110a0482c', 'TUITION_PER_YEAR', 'INTERNATIONAL', 4201.00, 'https://admissions.ktu.edu/bachelor/', '2026-08-28', 'Stated directly in EUR by KTU ("4201 €", price per credit 70,02 € x 60 credits/year) — no conversion needed.'),
    ('894f838b-244c-4b5f-bdd6-7ab96c1f7fb3', '79224a9f-9dd8-4e15-b815-676146b7911a', 'TUITION_PER_YEAR', 'INTERNATIONAL', 4950.00, 'https://vilniustech.lt/for-international-students/admission-20262027-------scholarships/tuition-and-other-fees/9603', '2026-08-28', 'Stated directly in EUR by VILNIUS TECH''s university-wide non-EU tuition table, for the Engineering/IT/Technologies programme group (includes Computer Engineering) — no conversion needed. Note: the programme''s own course page separately states a lower figure, "€4,201 per year," which appears to be the EU/EEA-citizen rate rather than the non-EU rate used here; both figures are disclosed rather than one silently discarded.'),
    ('2de151ef-a662-493c-a108-b4f390201b26', '79224a9f-9dd8-4e15-b815-676146b7911a', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://vilniustech.lt/for-international-students/admission-20262027-------scholarships/tuition-and-other-fees/9603', '2026-08-28', 'Stated directly in EUR: "100 EUR non-refundable application fee."'),
    ('427ad182-3b9a-4dbd-84ae-2f0106f81d1a', '79224a9f-9dd8-4e15-b815-676146b7911a', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 200.00, 'https://vilniustech.lt/for-international-students/admission-20262027-------scholarships/tuition-and-other-fees/9603', '2026-08-28', 'Stated directly in EUR: "A 200 EUR registration fee is paid with the first tuition fee after receiving the official acceptance letter."'),
    ('39650a44-3409-4376-a1e0-b55667b50c77', 'fc79fa21-1992-4fc4-a680-0358a686f928', 'TUITION_PER_YEAR', 'INTERNATIONAL', 4200.00, 'https://www.lu.lv/en/studies/study-programmes-1/bachelors-study-programmes/biotechnology-and-bioengineering/', '2026-08-28', 'Stated directly in EUR by the University of Latvia for "other nationalities" (non-EU/EEA/Swiss) — no conversion needed. EU/EEA/Swiss citizens are charged a lower €3,600/year rate on the same page, not used here (student_category INTERNATIONAL).'),
    ('d02345e8-3e8e-4751-94fc-1d152af7d2d6', 'fc79fa21-1992-4fc4-a680-0358a686f928', 'APPLICATION_FEE', 'INTERNATIONAL', 170.00, 'https://www.lu.lv/en/admission/admissions/registration-fee/', '2026-08-28', 'Stated directly in EUR: "170.00 EUR," described as "nonrefundable and does not guarantee acceptance."'),
    ('08fd27bd-fbcd-46e9-ae3c-5caa00b37113', 'ce5a611c-c9e9-4a71-90c4-b14d08402a86', 'TUITION_PER_YEAR', 'INTERNATIONAL', 5590.00, 'https://apply.rtu.lv/courses/course/16-msc-computer-systems', '2025-12-31', 'rtu.lv/apply.rtu.lv returned HTTP 403 to both the fetch tool and direct curl; content taken from a Wayback Machine snapshot of this official URL, dated 2025-12-31 (used as source_checked_on). Stated directly in EUR ("€5,590 per year") — no conversion needed. The same snapshot also states a one-time €250 deposit, which is not one of this table''s fee_type categories and is not seeded here.'),
    ('023ff214-b7eb-482f-a3d5-e4afd286e793', 'ce5a611c-c9e9-4a71-90c4-b14d08402a86', 'APPLICATION_FEE', 'INTERNATIONAL', 150.00, 'https://apply.rtu.lv/courses/course/16-msc-computer-systems', '2025-12-31', 'Same Wayback snapshot as this programme''s tuition row (dated 2025-12-31). Stated directly in EUR: "€150 one-time."'),
    ('d1e1879e-c249-4224-98e3-49b16b0eab1e', '6fa6daad-ff0c-4d26-85c7-43daab2fa72f', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://www.rsu.lv/en/study-here/admissions/tuition-fees-studies-english', '2026-08-28', 'Stated directly in EUR: "100 EUR (non-refundable)" for international applicants (30 EUR applies only to Latvian citizens educated in Latvia, not seeded here). No TUITION_PER_YEAR row is seeded for this programme: the same page''s tuition figure ("3,300 EUR (3 years)") is ambiguous between a per-year rate and a whole-programme total, and this project omits rather than guesses which basis applies.'),
    ('b60b78c1-c396-4d22-817b-06e5b0bebf11', '903d0411-6bed-4444-8a8c-a930259c4223', 'TUITION_PER_YEAR', 'INTERNATIONAL', 5400.00, 'https://senat.ubbcluj.ro/wp-content/uploads/2025/04/Anexa-4_Regulament-taxe_administrative-2025-2026.pdf', '2026-08-28', 'Babeș-Bolyai University''s Senate fee regulation (Addendum 4, 2025-2026 academic year) states the Faculty of Mathematics and Computer Science, Computer Science specialisation, non-EU/EEA/Swiss self-funded tuition as "600" EUR/month. The same regulation (Art. 15.2) states fees are paid over "9 months" in years without a distinct training-course component, or "10 months" in years that have one. This row uses the lower, 9-month bound: 600 x 9 = EUR 5,400/year. A year with the 10-month component would total EUR 6,000/year instead — disclosed here rather than silently picked.'),
    ('2d4735c9-150d-4ce7-be9b-4800614582cf', '903d0411-6bed-4444-8a8c-a930259c4223', 'APPLICATION_FEE', 'INTERNATIONAL', 50.00, 'https://cci.ubbcluj.ro/admission-international-students/candidates-from-other-countries/bachelor/', '2026-08-28', 'Quoted verbatim from the admissions page: "Processing fee receipt (50 EUR)" — stated directly in EUR, no conversion needed.'),
    ('49b9ea2e-0f21-433d-b462-4c07ed060474', '48c86563-60e7-4add-935b-44337724ba40', 'TUITION_PER_YEAR', 'INTERNATIONAL', 2430.00, 'https://international.upt.ro/en/international-students/students-from-countries-outside-the-eu-eea-or-the-swiss-confederation/2026-2027/non-eu-admissions/', '2026-08-28', 'Stated directly in EUR by Politehnica University of Timișoara: "Tuition fee — €2,430 per year" — no conversion needed.'),
    ('98570e49-b397-440e-8b4c-5e20ed7e905e', '48c86563-60e7-4add-935b-44337724ba40', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://international.upt.ro/en/international-students/students-from-countries-outside-the-eu-eea-or-the-swiss-confederation/2026-2027/non-eu-admissions/', '2026-08-28', 'Stated directly in EUR: "Application fee — €100 one-time" — no conversion needed.'),
    ('62b49f85-7f26-4991-9100-3545ea454bd7', '14bd6043-90f4-4821-b69d-324c361025c2', 'TUITION_PER_YEAR', 'INTERNATIONAL', 2600.00, 'https://international.unibuc.ro/home-3/admission-2026-2/study-cycles/details-about-fees-and-admission-criteria/tuition-fees/tuition-fees-for-bachelors-degree/', '2026-08-28', 'Stated directly in EUR by the University of Bucharest for its Faculty of Business and Administration bachelor''s programmes (non-EU international students) — no conversion needed. Distinct from the higher €3,050/year rate on the same page for the Faculties of Biology/Chemistry/Physics/Geography/Geology/Mathematics and Computer Science, which does not apply to this programme.'),
    ('1172b017-0d09-46b2-8ea3-2d13b2d86ea8', '14bd6043-90f4-4821-b69d-324c361025c2', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://international.unibuc.ro/home-3/admission-2026-2/study-cycles/bachelors-degree-for-non-eu-candidates/', '2026-08-28', 'Stated directly in EUR: "100 EUR admission fee" (non-refundable) — no conversion needed.');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('db7ce1a6-69d5-4a5e-9e62-9b5609ab1c9e', 'VU FEBA Admission Scholarship for High Potential Foreign Students', 'Vilnius University, Faculty of Economics and Business Administration', 'LT', 'd0edcc4d-4074-4089-850e-5bd46253c5bc', NULL, 'LIVING_STIPEND', 1000.00, 'Ten one-off scholarships of EUR 1,000 each, open to international students from any foreign country admitted to a Bachelor''s or Master''s programme at VU FEBA. Ranked by grades, motivation to study at Vilnius University in the chosen programme, and a motivation interview. Paid directly to the successful applicant after their arrival — a one-off award, not a recurring monthly stipend.', NULL, 'https://www.evaf.vu.lt/en/about-the-faculty/news/vu-feba-admission-scholarship-for-high-potential-foreign-students', 'https://www.evaf.vu.lt/en/about-the-faculty/news/vu-feba-admission-scholarship-for-high-potential-foreign-students', '2026-08-28'),
    ('a8a6e636-bc78-4a94-b3bb-c8134d7334bd', 'VILNIUS TECH Tuition-Free & Partial Scholarships for International Students', 'Vilnius Gediminas Technical University (VILNIUS TECH)', 'LT', '3942c50b-fdd3-4112-a110-996c540546ec', NULL, 'FULL_TUITION', 4950.00, 'Top tier ("Tuition-Free Scholarships") is full first-year tuition coverage for the best international Bachelor''s applicants, requiring a minimum of 80% of the maximum grade, B2 English, a motivation letter, and 2 academic references. amount_eur here reflects only this full-coverage tier, set equal to this batch''s seeded non-EU Engineering/IT/Technologies annual tuition figure. A separate, lower "Partial Scholarships" tier (50% or 25% of the tuition fee, minimum 70% of the maximum grade) also exists and is not reduced to one euro figure here.', '2026-04-20', 'https://vilniustech.lt/en/international-students/full-time-students/scholarships/', 'https://vilniustech.lt/en/international-students/full-time-students/scholarships/', '2026-08-28'),
    ('8ab41cd2-68ce-40e1-9c1b-9e8befaab945', 'Latvian State Scholarship', 'Republic of Latvia (Cabinet of Ministers Regulation No. 68 of 24 Jan 2012, as amended)', 'LV', NULL, NULL, 'LIVING_STIPEND', 500.00, 'Country-wide scholarship for citizens of countries with a cooperation agreement with Latvia (39 eligible countries per the source), for a maximum of two terms within one study cycle. The source states this EUR 500/month figure explicitly only for second-cycle (Master''s) programmes; no bachelor''s-level EUR figure is published, and none is assumed here.', NULL, 'https://www.studyinlatvia.lv/scholarships', 'https://www.studyinlatvia.lv/scholarships', '2026-08-28'),
    ('eb4f8ccf-69d1-4467-b412-363474eb3d7c', 'Government of Romania Scholarship', 'Romanian Ministry of Foreign Affairs / Ministry of Education', 'RO', NULL, NULL, 'FULL_FUNDING', NULL, 'Country-wide scholarship for non-EU citizens with "an average of the study years, for the last graduated school, of at least 7 (seven)" (10-point scale). Open to all fields except Medicine, Dental Medicine, and Pharmacy. Covers tuition, a monthly financial-aid stipend, dormitory accommodation, and exemption from registration/other fees. Bachelor''s and Master''s study must be conducted in Romanian (a preparatory year is included); only PhD study may be in English. No monthly stipend EUR/RON amount is published on any official page found — the source states only "a monthly financial aid, in accordance with the legislation in force," with no number, so amount_eur is left NULL rather than guessed. 2026 cycle: applications 16 February - 31 March 2026, results around 15 July 2026.', '2026-03-31', 'https://scholarships.studyinromania.gov.ro/scholarship-about', 'https://scholarships.studyinromania.gov.ro/scholarship-about', '2026-08-28');

INSERT INTO living_cost_estimates (estimate_id, country_code, city, university_id, category, monthly_estimate_eur, source_url, source_checked_on, notes) VALUES
    ('6ac74c04-8259-4119-87f3-1e63ace6b93c', 'LT', 'Kaunas', '3d7fe0be-6cd7-4b61-b1b2-19160b746649', 'GENERAL', 450.00, 'https://admissions.ktu.edu/relocation-to-kaunas/', '2026-08-28', 'KTU''s own relocation page states "the average monthly student budget in Kaunas ranges from €450 to €1000" (accommodation included). This row uses the lower bound; the same page''s itemised breakdown: KTU dormitory €139-301/month, private rent €300-800/month, utilities (if renting privately) €80-170/month, groceries €200/month, public transportation €14/month.'),
    ('625aaf90-c86c-47cf-9a15-6cb2f94a4437', 'LV', NULL, NULL, 'GENERAL', 450.00, 'https://studyinlatvia.lv/faq/fees-and-costs', '2026-08-28', 'Study in Latvia (the national higher-education promotion platform) states living costs of "€450-€700 monthly," covering food, accommodation, utilities, transportation, and other expenses. This row uses the lower bound of that published range; no city- or university-specific official figure was found.'),
    ('6dc23270-8cc6-43bc-918b-963e59bf8d94', 'RO', NULL, NULL, 'GENERAL', 600.00, 'https://studyinromania.gov.ro/living-cost', '2026-08-28', 'Study in Romania (the official Ministry-affiliated portal) states directly: "The living costs can be approximately 600 Euro / per month." Same source''s breakdown: food €100-300/month, utilities €40-60/month, phone/internet €20-40/month, public transport €10-30/month, medical insurance €12+/month. This is a national estimate; no Bucharest-, Cluj-Napoca-, or Timișoara-specific official figure was found.');

INSERT INTO visa_requirements (visa_requirement_id, destination_country_code, applicant_country_code, visa_type, financial_proof_eur, estimated_processing_days, minimum_passport_validity_months, required_documents, application_url, source_url, source_checked_on, notes) VALUES
    ('6cde96dd-0471-4806-87d7-b4134aea9215', 'LT', NULL, 'RESIDENCE_PERMIT', 6228.00, NULL, NULL, ARRAY['passport_copy', 'bank_statement_or_financial_proof', 'health_insurance_proof', 'police_clearance_certificate', 'university_acceptance_letter'], NULL, 'https://www.vdu.lt/wp-content/uploads/2025/02/TRP_Application_Non_EU_citizens_2025-02.pdf', '2026-08-28', 'migracija.lt (the national Migration Department site) is a JS-rendered single-page app that returned no text content via direct fetch, curl, or Wayback Machine; this row instead relies on an official Vytautas Magnus University PDF that compiles and cites current migracija.lt/MIGRIS rules, instructing students to "always check the actual information on the migration website." That PDF is internally dated February 2025 but was confirmed still live on 2026-08-28 (used as source_checked_on) — flagged here since its content may be up to roughly 1.5 years old. Financial proof is the PDF''s own stated annual figure ("the minimum amount of 520 EUR/month, i.e.: 6228 EUR/year"), doubled to 12,456 EUR/year if using a parent''s/representative''s account (not used here). Health insurance must cover EUR 10,000 for medical care and repatriation. State fee: EUR 45 (general procedure, within 10 business days) or EUR 90 (urgent, within 5 business days) — not converted to calendar days here since that would require an assumption, so estimated_processing_days is left NULL. Passport-validity rule ("valid for at least 3 months after the expiry date of the requested TRP") is relative to the permit''s own length, not a fixed number, so minimum_passport_validity_months is left NULL — same discipline applied to Denmark''s relative rule in the prior batch. A TRP is issued for the duration of study, up to 2 years for Bachelor''s/Master''s or 3 years for PhD; renewal must be submitted at least 1 working day before expiry, no earlier than 6 months in advance.'),
    ('42f4d11e-ea60-4081-a58c-baf66e3d86a1', 'LV', NULL, 'RESIDENCE_PERMIT', NULL, NULL, NULL, ARRAY['residence_permit_application_form', 'passport_copy', 'police_clearance_certificate_if_applicable', 'study_agreement', 'proof_of_subsistence_means', 'passport_photo'], NULL, 'https://vissparmigraciju.pmlp.gov.lv/?lang=en&page_id=2458', '2026-08-28', 'Covers the Initial Residence Permit for studies at an accredited Latvian university, per the Office of Citizenship and Migration Affairs (OCMA)''s official migration-procedures portal. State fee: EUR 780 (EUR 234 for a minor) — not modelled as financial_proof_eur since it is an application fee, not a means-of-subsistence figure; no separate subsistence-funds EUR amount is stated on this page, so financial_proof_eur is left NULL. Neither a processing-time figure nor a minimum passport-validity requirement is stated on this page — both left NULL rather than assumed. A parallel document set (reason D 1.1, for citizens of a listed country group not needing the criminal-record certificate) carries the same EUR 780/234 fee.'),
    ('37fb69cb-e52c-40b2-86ad-213edfe4f41f', 'RO', NULL, 'STUDY_VISA', NULL, 30, NULL, ARRAY['proof_of_acceptance_for_studies', 'proof_of_tuition_payment', 'proof_of_means_of_support', 'criminal_record_certificate', 'medical_insurance_proof'], NULL, 'https://igi.mai.gov.ro/en/how-can-i-obtain-a-long-stay-visa-for-studies/', '2026-08-28', 'Covers Romania''s long-stay visa for studies (Type D), per the General Inspectorate for Immigration (IGI). "Means of support" is required "in amount of at least a minimum net wage at country level per month" — the page does not itself quantify that wage, so financial_proof_eur is left NULL rather than guessed. Processing time quoted verbatim: the National Visa Center approves "within 30 days of receiving the request, with the possibility to extend the deadline by 15 days" — the base 30-day figure is used here. Visa validity is 90 days with one or more entries; no minimum passport-validity figure is stated. A separate residence-permit application is required after arrival (same source domain, /en/studies/), itself requiring proof of means of support "amounting to at least the minimum gross salary per country guaranteed in payment for a period of at least 6 months," also not quantified on that page, and resolved within the same 30 (+15) day window.');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('38ae168b-8892-441c-83e0-1ce1381d298e', 'd0edcc4d-4074-4089-850e-5bd46253c5bc', 'UNIVERSITY_DORM', 'Vilnius University Housing (Saulėtekio dormitories)', 'Vilnius', 130.00, 150.00, NULL, NULL, 'https://www.bustas.vu.lt/en/accommodation/', NULL, 'https://www.bustas.vu.lt/en/accommodation/', '2026-08-28', 'Stated directly in EUR by VU''s housing office (stays over 2 months): double room "130 Eur"/month (used here); a triple room is "90 Eur"/month (not seeded separately). Deposit: "at least 150 Eur. Deposit must cover monthly price." Distance to campus is not stated numerically on this page — only described as "in a walking distance to the faculties."'),
    ('dcb28a4f-9270-4f2f-83ae-af5231b314d9', '6dced863-e5f6-4488-a29e-2d77fac1e0c4', 'UNIVERSITY_DORM', 'RTU Ķīpsala Campus Dormitory', 'Riga', 267.00, NULL, NULL, NULL, 'https://www.rtu.lv/en/studies/accomodation-1/kipsala-campus-dormitory', NULL, 'https://www.rtu.lv/en/studies/accomodation-1/kipsala-campus-dormitory', '2026-02-03', 'rtu.lv returned HTTP 403 to both the fetch tool and direct curl; content taken from a Wayback Machine snapshot of this official URL, dated 2026-02-03 (used as source_checked_on). Stated directly in EUR, effective 01.09.2023: a double-shared room is "267.00 EUR"/month (used here); a double-shared room in "Tower A" is 293.00 EUR/month, and a single room is up to 432.00 EUR/month (neither seeded separately). No deposit figure is stated on this page or on RTU''s separate dormitory-security-deposit refund-process page (Wayback snapshot 2024-07-17), which describes the refund process only, with no amount — left NULL rather than guessed. Distance to campus is not stated numerically; the page only says it is "located on Ķīpsala campus."'),
    ('4f2ad958-b9a5-4942-9a47-dc92cd4983ff', '6fc1cf97-58ab-46df-9fa5-05ac5aafca8c', 'UNIVERSITY_DORM', 'Babeș-Bolyai University (Cămin C 1)', 'Cluj-Napoca', 67.51, NULL, NULL, NULL, NULL, NULL, 'https://senat.ubbcluj.ro/wp-content/uploads/2025/04/Anexa-4_Regulament-taxe_administrative-2025-2026.pdf', '2026-08-28', 'Original figure: 355 RON/bed/month for the "9. Studenţi străini necomunitari pe cont propriu valutar" (non-EU foreign students, self-funded, foreign-currency basis) category at dormitory "C 1," per Babeș-Bolyai University''s Senate fee regulation (Addendum 4, 2025-2026 academic year). Converted at 1 EUR = 5.2584 RON (355 / 5.2584 = 67.51 EUR/month). A higher-comfort dormitory ("C A1") charges 515 RON/month for the same category (515 / 5.2584 = 97.94 EUR/month), not seeded separately. No deposit or distance-to-campus figure is stated in this document. The same document notes "Tarifele nu includ TVA" (rates exclude VAT).'),
    ('42ce5af0-2914-48b5-897d-dbe23a0c1e07', 'daa62780-e575-4dbb-aeec-b22d5774779d', 'UNIVERSITY_DORM', 'Politehnica University of Timișoara (Dormitory 8C, Student Complex)', 'Timișoara', 65.00, 114.10, NULL, ARRAY['shared_bathroom', 'shared_kitchen', 'shared_laundry_room'], NULL, NULL, 'https://international.upt.ro/en/international-students/students-from-countries-outside-the-eu-eea-or-the-swiss-confederation/2025-2026/accommodation/', '2026-08-28', 'Rent stated directly in EUR: "approximately 65 euros/month" for a room "shared by 2 students," with shared bathroom, kitchen, reading room, and laundry room. Deposit original figure: "a deposit of 600 RON (Romanian lei) in cash," refunded at the end of stay, converted at 1 EUR = 5.2584 RON (600 / 5.2584 = 114.10 EUR). Distance to campus is not stated on this page.');
-- Batch: Bulgaria, Croatia, Luxembourg (research/verification pass 2026-08-28).
-- Bulgaria, Croatia, and Luxembourg all use the Euro directly (Bulgaria's
-- euro adoption confirmed via the EU's official countries-using-the-euro
-- page as of this batch's research date; Croatia since 2023; Luxembourg a
-- founding eurozone member) — no FX conversion was needed anywhere in this
-- batch. Where an official Bulgarian page still quoted a figure in BGN
-- (the pre-euro Lev, not yet updated on that specific page), that figure is
-- reported as-is with no invented conversion, and is not used as this
-- batch's seeded EUR figure.
-- Deliberate omissions / notable findings from this batch, documented here
-- so a future reader doesn't mistake a gap for an oversight:
--  - Bulgaria: Sofia University's own international-students page states
--    outright that it "presently does not offer any financial assistance
--    for foreign citizens," and the only other scholarship found (Medical
--    University of Sofia's) is stated in BGN, not yet updated to EUR, and is
--    narrowly scoped to students admitted under intergovernmental exchange
--    agreements — neither is seeded as a scholarship row. No comprehensive
--    official monthly cost-of-living figure was found for Sofia or
--    Blagoevgrad specifically; Bulgaria's two living_cost_estimates rows
--    instead use two distinct, narrowly-scoped official figures from
--    AUBG's own Cost of Attendance document (meals, off-campus housing)
--    rather than a synthesized aggregate. Medical University of Sofia's own
--    dormitory complex (СОСБОС) publishes room/bed counts but no rent or
--    deposit figure, so no accommodation row is seeded for it. The
--    Ministry of Foreign Affairs' Visa D document is this batch's one
--    confirmed absolute minimum-passport-validity figure (18 months) —
--    Croatia and Luxembourg's equivalent rules are both relative to the
--    permit's own length or merely advisory, not a fixed number, and are
--    left NULL accordingly.
--  - Croatia: University of Zagreb's Master of European Studies programme
--    states both a per-semester (EUR 1,000) and a whole-programme total
--    (EUR 2,000) tuition figure on the same official page; since the
--    programme is exactly one year (two semesters), only the TUITION_TOTAL
--    row is seeded to avoid double-counting the same cost under two
--    fee_type rows (the per-semester figure is disclosed in that row's
--    notes instead). University of Zagreb explicitly states it offers no
--    financial aid to foreign citizens, so this batch's one Croatian
--    scholarship is the country-wide "Scholarships of the Republic of
--    Croatia" bilateral scheme instead. No named, single-dormitory rent
--    figure could be confirmed for the University of Rijeka specifically
--    (only an aggregate official range), so Rijeka's cost data is seeded as
--    living_cost_estimates rows (tied to the university) rather than a
--    student_accommodations row, and this project's usual per-university
--    accommodation listing is skipped for Rijeka rather than guessed.
--  - Luxembourg: the University of Luxembourg's own site returned an AWS
--    WAF bot-challenge to direct automated fetches; all uni.lu content
--    below was retrieved through the r.jina.ai read-only proxy (i.e. still
--    today's live page content, not an archived snapshot), noted in each
--    row. The university's own pages show an internal inconsistency (the
--    homepage says the 2026-2027 intake is closed and the next cycle opens
--    1 February 2027, while each programme's own admissions page still
--    displays "1 Feb 2026" deadlines) — reported as found rather than
--    resolved by guessing which is current. Two official uni.lu pages also
--    disagree on student-residence rent (EUR 400/month on the accommodation
--    "offer" page for Bachelor's/Master's students vs. "minimum 450
--    EUR/month" on the cost-of-living page) — both are disclosed in that
--    accommodation row's notes rather than one being silently discarded;
--    the deposit figure used (EUR 900) is the cost-of-living page's own
--    literal example tied to its EUR 450 rent figure, not recalculated
--    against the EUR 400 figure used for monthly_rent_eur. Guichet.lu (the
--    Luxembourg government portal) gives only advisory language ("if the
--    passport is due to expire in less than 6 months, they are advised to
--    renew it") for passport validity, not a hard requirement, so
--    minimum_passport_validity_months is left NULL for Luxembourg. This
--    batch's minimum-cgpa_percentage column is left NULL for every one of
--    its 9 programmes: Bulgaria/Croatia's programmes state no numeric GPA
--    threshold at all, and AUBG's "recommended minimum GPA of 3.0 on a 4.0
--    scale (4.5 out of 6 on the Bulgarian scale)" is a non-mandatory
--    recommendation on a US-style GPA scale, not a percentage, and is not
--    forced into a percentage-equivalent the way this project has
--    previously converted a clean out-of-10 grading scale.

