INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('c54e0204-56af-43ec-a3d0-34646640255e', 'a594369f-9af6-4097-a4b2-9a2d85d41b29', NULL, NULL, 'CEFR', 'B2', ARRAY['application_form_or_cv', 'diploma_with_certified_translation_and_legalization', 'language_certificate', 'passport_copy', 'passport_photos'], 'https://www.uni-sofia.bg/index.php/eng/admission/international_students/application_procedure/applicants_from_non_eu_member_countries/application_documents', '2026-08-28', 'Quoted verbatim: "A language certificate is obligatory with language proficiency minimum Upper-intermediate (B2)" — no numeric IELTS/TOEFL score is stated on any official page found, only this CEFR level. Admission is via "an exam in English"; the programme is "designed primarily for citizens of states which are not EU members." Explicitly: "MEDICAL CERTIFICATE IS NOT NEEDED!" Documents must include the original diploma with certified translation and legalisation, plus (for non-Bulgarian secondary graduates) a NACID recognition certificate. Application window (2026/2027 cycle): 27 July - 11 September 2026. No overall CGPA/percentage figure is published.'),
    ('58125dde-d735-4a26-94d7-9662205fbe72', '27ca5833-70b0-421a-a7f8-cbf861429edd', NULL, NULL, NULL, NULL, ARRAY['application_form_bilingual', 'legalized_diploma_certified_translation', 'proof_of_citizenship', 'passport_photos'], 'https://mu-sofia.bg/en/admission/admissions-of-foreign-citizen/', '2026-08-28', 'No numeric overall CGPA/percentage figure or English-test score is published; entry instead requires passing an "Entrance Exams in English, Biology and Chemistry" (non-EU/EEA sitting quoted for "09.09.2026," remote format, maximum score "42"), so language_test_name/minimum_language_score are left NULL rather than guessed. Application window (2026/2027 cycle): 27 July - 31 August 2026. All documents must be submitted in person, per the official page.'),
    ('3f626f82-614e-4213-81da-6a8aa099a285', '2fb29357-8872-43df-9233-83f4c3c2d592', NULL, NULL, 'IELTS', '6.5', ARRAY['essay', 'letter_of_recommendation', 'official_transcript'], 'https://www.aubg.edu/admissions/bachelors/how-to-apply/', '2026-03-04', 'aubg.edu returns HTTP 403 to automated fetches; content taken from a Wayback Machine snapshot of this official URL, dated 2026-03-04 (used as source_checked_on). No hard minimum-GPA/percentage figure is enforced — the page states only a "recommended minimum GPA for applicants is 3.0 on a 4.0 scale (4.5 out of six 6 on the Bulgarian scale)," a non-mandatory US-style GPA-scale figure, not reduced to a percentage here since that would require an unstated conversion assumption. Also accepted in place of IELTS 6.5: Duolingo English Test 110, TOEFL iBT 80 (waived for applicants from English-medium secondary systems in the US/UK/Ireland/Australia/New Zealand/Canada). SAT/ACT explicitly not required. Essay is "around 650 words." Deadlines: Priority 15 January, Early 15 March, Regular 15 May. No application fee is mentioned on this official page.'),
    ('ffecdc6d-4360-4f52-99e3-11f796fb40a2', 'ae2323fe-4dc5-4cd8-a82e-791327c48263', NULL, NULL, NULL, NULL, ARRAY['cover_letter', 'cv', 'two_academic_recommendation_letters', 'certified_diploma_copy', 'grade_transcript'], 'https://www.fpzg.unizg.hr/en/study/graduate_study/master_of_european_studies', '2026-08-28', 'No entrance exam; quoted verbatim: "applications are ranked based on undergraduate study grade point average" with no minimum threshold stated. English requirement is only "a good command of spoken and written English," no numeric IELTS/TOEFL score. Prerequisite: a completed 4-year (240 ECTS) undergraduate degree. The most recent enrolment call found (2023/2024 cycle) gave a deadline of "September 21 and 22" — used here only as illustrative of the annual application pattern, not this year''s confirmed date, since no 2026/2027-specific call could be found.'),
    ('cde4d457-4176-4097-80e9-a1302f5c534d', '83c40e62-57d1-4e3b-96df-dbb0b2a3f300', NULL, NULL, NULL, NULL, ARRAY['application_form', 'cv', 'motivation_letter', 'proof_of_nationality', 'birth_certificate', 'secondary_school_transcripts_and_certificate'], 'https://mefst.unist.hr/studies/medical-studies-in-english/call-for-applicants-and-application-procedure-for-admission-into-2026-2027-medical-studies-in-english/13242', '2026-08-28', 'No overall CGPA/percentage figure is published; eligibility requires only "total duration of previous education - 12 years minimum" plus passed secondary-school final exams. English proficiency proof is listed as required "if applicable" with no numeric IELTS/TOEFL score stated. 2026/2027 cycle deadline as published: "18 August 2026" — already elapsed at the time of this research pass (2026-08-28); reported as found rather than adjusted.'),
    ('c3ddd15f-a7db-463d-904f-ce0413c5f04d', '3e55539f-0e52-4090-b6a6-9b2b3ee1ca26', NULL, NULL, NULL, NULL, NULL, 'https://efri.uniri.hr/en/education/study-programmes/university-undergraduate-programmes/university-undergraduate-programme-in-english/', '2026-08-28', 'No numeric overall CGPA/percentage figure, English-test score, or itemised documents checklist is published — entry requires "completed a four-year secondary school" and "passed the State Matura examination" (pre-2010 secondary graduates exempt), processed through Croatia''s national "Postani Student" admissions portal (www.postani-student.hr), not through a university-specific documents list. No specific application deadline date is stated on this page.'),
    ('05568b18-f742-41e2-ba10-626cdd879362', '1ef6832e-b294-4001-8852-f559a67f6585', NULL, NULL, 'CEFR', 'B2', ARRAY['secondary_school_certificate', 'cv_and_covering_letter', 'passport_copy', 'health_insurance_or_social_security_copy', 'id_photo'], 'https://www.uni.lu/fstm-en/study-programs/bachelor-in-computer-science/admissions/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy (uni.lu blocks direct automated fetches with an AWS WAF challenge); still today''s live page content. No minimum-GPA figure is published — selection is based on overall application quality. English requirement: "B2-level certificate in English required"; French/German "B1 level is recommended" but not mandatory. Capacity: "90 places." Cover letter/CV combined figure is roughly 1,500 words. Deadlines as displayed on this page: EU applicants 1 Feb - 15 Jul 2026 (submission by 22 Jul 2026), non-EU 1 Feb - 24 Mar 2026 (submission by 31 Mar 2026) — flagged as potentially stale, since the university''s own homepage (fetched the same day) states the 2026-2027 intake is already closed and the next cycle opens 1 February 2027; both are reported as found rather than one silently corrected.'),
    ('81fbc4c5-f745-4346-acf0-4e654497d3b4', 'bfc6af16-ca1c-4a89-ac33-f5896c89d719', NULL, NULL, 'CEFR', 'C1', ARRAY['motivation_letter_max_500_words', 'two_confidential_reference_letters'], 'https://www.uni.lu/fhse-en/study-programs/master-in-european-governance/admissions/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy (uni.lu blocks direct automated fetches with an AWS WAF challenge); still today''s live page content. Prerequisite: "A good Bachelor''s degree or equivalent (180 ECTS) in political science or another relevant area." No minimum-GPA figure is published; selection instead uses "previous degree, grades, language skills, motivation letter and relevant extracurricular experience." English requirement: "English C1 (CEFR)" mandatory; French proficiency "considered an asset" but not required. Same deadline-consistency caveat as this batch''s other two Luxembourg programmes applies (EU 1 Feb - 1 Jul 2026, non-EU 1 Feb - 24 Mar 2026, displayed alongside the university''s own homepage stating the cycle is closed).'),
    ('0afa4062-0e4a-40e4-a20c-e66f9df411ce', '7492687e-fb06-4ba9-9215-89c75ccf8687', NULL, NULL, 'CEFR', 'B2', ARRAY['academic_application_file', 'academic_recommendation_letter', 'language_proficiency_certificate'], 'https://www.uni.lu/fstm-en/study-programs/master-in-information-and-computer-sciences/admissions/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy (uni.lu blocks direct automated fetches with an AWS WAF challenge); still today''s live page content. Prerequisite: "Bachelor or equivalent diploma degree in computer science or relevant field, with good mathematical knowledge" (linear algebra, analysis, programming, abstraction). No minimum-GPA figure is published. English requirement: "Level B2 in English" mandatory; no French/German requirement stated. Same deadline-consistency caveat as this batch''s other two Luxembourg programmes applies.');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('d37ce960-7448-4d2a-8407-5ed12d46a92a', 'a594369f-9af6-4097-a4b2-9a2d85d41b29', 'TUITION_PER_YEAR', 'INTERNATIONAL', 2500.00, 'https://www.uni-sofia.bg/index.php/eng/admission/international_students/tuition_fees_in_sofia_university_for_the_academic_2025_2026_year', '2026-08-28', 'Stated directly in EUR by Sofia University''s official fee schedule for the "European Union and European Integration" bachelor''s programme, 2025-2026 academic year — no conversion needed.'),
    ('07d31889-09a9-41a4-b39d-7da3781c7287', 'a594369f-9af6-4097-a4b2-9a2d85d41b29', 'APPLICATION_FEE', 'INTERNATIONAL', 25.00, 'https://www.uni-sofia.bg/index.php/eng/admission/international_students/application_procedure/applicants_from_non_eu_member_countries/application_documents', '2026-08-28', 'Stated directly in EUR: "Application fee 25 € payable by bank transfer."'),
    ('4815b6e9-8075-4469-92b1-473c1491dd54', '27ca5833-70b0-421a-a7f8-cbf861429edd', 'TUITION_PER_YEAR', 'INTERNATIONAL', 9950.00, 'https://mu-sofia.bg/en/admission/admissions-of-foreign-citizen/', '2026-08-28', 'Stated directly in EUR: "EUR 9950 per year" for Medicine (Bulgarian- or English-taught) — no conversion needed.'),
    ('cd76fdb0-614b-4481-b5f5-f2cd389bd260', '27ca5833-70b0-421a-a7f8-cbf861429edd', 'APPLICATION_FEE', 'INTERNATIONAL', 55.00, 'https://mu-sofia.bg/en/admission/admissions-of-foreign-citizen/', '2026-08-28', 'Stated directly in EUR: document-submission fee of "55 euro."'),
    ('9a6fec2e-50d0-4e6e-9f90-2d42b21fee73', '27ca5833-70b0-421a-a7f8-cbf861429edd', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 210.00, 'https://mu-sofia.bg/en/admission/admissions-of-foreign-citizen/', '2026-08-28', 'Stated directly in EUR: entrance-exam fee of "210 euro," explicitly "non-refundable," for the Medicine/Dentistry/Pharmacy entrance exam.'),
    ('0e69663c-3f23-428d-8329-db5bb079eefe', '2fb29357-8872-43df-9233-83f4c3c2d592', 'TUITION_PER_YEAR', 'INTERNATIONAL', 13800.00, 'https://www.aubg.edu/wp-content/uploads/2026/04/AUBG-Cost-of-Attendance_2026-2027.pdf', '2026-08-28', 'Stated directly in EUR ("€13,800") in AUBG''s official "Estimated Cost of Attendance for Academic Year 2026/2027" PDF (fetched live, no conversion needed). No application fee is mentioned on AUBG''s official admissions pages, so none is seeded here.'),
    ('17d3bf2f-6b2d-409f-a188-da8a2510bfab', 'ae2323fe-4dc5-4cd8-a82e-791327c48263', 'TUITION_TOTAL', 'INTERNATIONAL', 2000.00, 'https://www.fpzg.unizg.hr/novosti?@=2fcp8', '2026-08-28', 'Stated directly in EUR: "1.000,00 € / 7.534,50 HRK per semester (total fee of 2.000,00 € / 15.069,00 HRK)." Since this programme is exactly one year (two semesters), only this whole-programme TUITION_TOTAL figure is seeded — the per-semester figure (EUR 1,000) is not seeded as a separate row, to avoid double-counting the same cost twice in this project''s cost calculations. No application fee is mentioned on this page.'),
    ('bf1e1caa-1411-423a-80fb-5301ba81e7d3', '83c40e62-57d1-4e3b-96df-dbb0b2a3f300', 'TUITION_PER_YEAR', 'INTERNATIONAL', 12000.00, 'https://mefst.unist.hr/studies/medical-studies-in-english/call-for-applicants-and-application-procedure-for-admission-into-2026-2027-medical-studies-in-english/13242', '2026-08-28', 'Stated directly in EUR: "12.000 EUR" per year, "payable in full within one week from the date of receiving the formal letter of acceptance" — no conversion needed.'),
    ('b1eb57fe-4941-4d2e-9744-a8dd508aa576', '83c40e62-57d1-4e3b-96df-dbb0b2a3f300', 'APPLICATION_FEE', 'INTERNATIONAL', 200.00, 'https://mefst.unist.hr/studies/medical-studies-in-english/call-for-applicants-and-application-procedure-for-admission-into-2026-2027-medical-studies-in-english/13242', '2026-08-28', 'Stated directly in EUR: "200,00 EUR" non-refundable application fee.'),
    ('63ace89e-1862-4c16-8508-5015ece53f2a', '3e55539f-0e52-4090-b6a6-9b2b3ee1ca26', 'TUITION_PER_YEAR', 'INTERNATIONAL', 5000.00, 'https://efri.uniri.hr/en/education/study-programmes/university-undergraduate-programmes/university-undergraduate-programme-in-english/', '2026-08-28', 'Stated directly in EUR: "Non-EU citizens: €5,000 per year" (EU/Croatian citizens are charged a lower €2,000/year rate on the same page, not used here since student_category is INTERNATIONAL).'),
    ('0cb939eb-d49e-4abf-af86-aa377167cd3c', '3e55539f-0e52-4090-b6a6-9b2b3ee1ca26', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 58.20, 'https://efri.uniri.hr/en/education/study-programmes/university-undergraduate-programmes/university-undergraduate-programme-in-english/', '2026-08-28', 'Stated directly in EUR: "Enrollment fee: €58.20" for all students, regardless of citizenship.'),
    ('d9966fde-0f7d-4f7e-a2e2-4e6b4e095d86', '1ef6832e-b294-4001-8852-f559a67f6585', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 400.00, 'https://www.uni.lu/en/admissions/bachelor-master/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy. Stated directly in EUR: "400€/ sem." — the University of Luxembourg''s flat-rate tuition, no conversion needed.'),
    ('faacc0e6-9524-433a-9152-732497088805', '1ef6832e-b294-4001-8852-f559a67f6585', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://www.uni.lu/en/admissions/bachelor-master/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy. Stated directly in EUR: "Pay the 100 € administrative fee per application" — non-refundable, but "100€ will be deducted from the first semester''s tuition fees" upon enrolment.'),
    ('a57b85df-b0be-425f-a1fe-9647d8412fde', 'bfc6af16-ca1c-4a89-ac33-f5896c89d719', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 400.00, 'https://www.uni.lu/en/admissions/bachelor-master/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy. Same University of Luxembourg flat-rate tuition as this batch''s other two Luxembourg programmes: "400€/ sem. (semester 1,2,3,4)."'),
    ('07883f67-8003-48f5-a113-4f96917786e5', 'bfc6af16-ca1c-4a89-ac33-f5896c89d719', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://www.uni.lu/en/admissions/bachelor-master/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy. Same flat EUR 100 administrative/application fee as this batch''s other two Luxembourg programmes.'),
    ('5f5ef6b1-955c-40fd-8cc4-596e64fdc8cc', '7492687e-fb06-4ba9-9215-89c75ccf8687', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 400.00, 'https://www.uni.lu/en/admissions/bachelor-master/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy. Same University of Luxembourg flat-rate tuition as this batch''s other two Luxembourg programmes: "400€/ sem. (semester 1,2,3,4)."'),
    ('5808e3b1-fb73-41a5-a73d-689e0482d722', '7492687e-fb06-4ba9-9215-89c75ccf8687', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://www.uni.lu/en/admissions/bachelor-master/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy. Same flat EUR 100 administrative/application fee as this batch''s other two Luxembourg programmes.');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('d847bee7-af98-4d4a-a692-2be266a552a1', 'AUBG Funded Scholarship', 'American University in Bulgaria', 'BG', '326ec084-de2c-485e-b1fd-e47ce6c83187', NULL, 'PARTIAL_TUITION', 5520.00, 'Quoted verbatim: "Up to 40% off tuition. Based on the applicant''s academic credentials. No additional documents necessary. Valid for eight semesters of study." Every bachelor''s applicant is automatically reviewed for it upon application submission. amount_eur here is this batch''s calculated maximum award value (40% of this batch''s seeded EUR 13,800/year AUBG tuition figure = EUR 5,520) — the actual award for any given student may be lower, per the source''s own "based on academic credentials" language. AUBG also lists nine full-tuition "Distinguished Scholarships" specifically for students from Bulgaria/Balkans/CIS on the same page, not seeded separately here since they target a narrower applicant pool.', NULL, 'https://www.aubg.edu/admissions/bachelors/cost-aid/scholarships/', 'https://www.aubg.edu/admissions/bachelors/cost-aid/scholarships/', '2025-06-16'),
    ('00696f89-b26b-4b6d-a803-c0a81e83990f', 'Scholarships of the Republic of Croatia (Bilateral Scholarships)', 'Croatian Ministry of Science, Education and Youth / Agency for Mobility and EU Programmes', 'HR', NULL, NULL, 'LIVING_STIPEND', 300.00, 'Quoted verbatim (2025/2026 call): "Undergraduate/graduate studies (A1, A2, B) — 300,00 EUR monthly financial support (July and August excluded). Subsidized accommodation in student residence halls. Subsidized meals at student restaurants." Eligible applicants are citizens of countries with a bilateral education agreement with Croatia (the source''s list includes Bulgaria, China, Czech Republic, Greece, Hungary, Israel, Italy, Poland, Portugal, Romania, Slovakia, Turkey, Ukraine, among others), or international students currently studying Croatian language/Slavic Studies abroad. "Only persons who are younger than 36 can use student accommodation." The 2025/2026 cycle deadline (the call that stated this EUR figure) was 4 April 2025; a newer 2026/2027 call was found with a deadline of 10 April 2026, but that later call''s fetched text did not repeat the EUR amounts, so this row''s figures are sourced from the 2025/2026 call specifically — both deadlines are disclosed here rather than one silently assumed to carry the same terms.', NULL, 'https://mzom.gov.hr/highlights/calls-417/scholarships-of-the-republic-of-croatia-call-for-applications-for-the-academic-year-2025-2026/6767', 'https://mzom.gov.hr/UserDocsImages/dokumenti/Engleski/2025/call-for-applications-croatia-2025-2026.pdf', '2026-08-28'),
    ('ce0c01ba-875b-4d3d-aaa3-ebe25f024c6d', 'Guillaume Dupaix International Excellence Scholarship', 'University of Luxembourg', 'LU', 'cab9794d-355b-4b3e-bd42-1c9f5da5c828', NULL, 'LIVING_STIPEND', 11526.00, 'Quoted verbatim: "5.763€ per semester = 11.526€ per annum," for up to 2 years (the standard Master''s duration). Explicitly covers living expenses and accommodation, not tuition. Open to full-time Master''s applicants at the University of Luxembourg in any field; not eligible if the Master''s requires a mandatory semester/year abroad, or if the applicant already receives Luxembourg''s State Financial Aid for Higher Education. "30 students per annum (10 per faculty)" are selected: 15 general plus 15 from a list of target countries (Western Balkans, Ibero-American nations, Thailand, Vietnam, Belarus, Egypt, India, Moldova, Russia, United Kingdom, Turkey, Ukraine). Applications are submitted alongside the Master''s application itself.', '2026-03-24', 'https://www.uni.lu/life-en/financial-support/scholarships/guillaume-dupaix-international-scholarship/', 'https://www.uni.lu/life-en/financial-support/scholarships/guillaume-dupaix-international-scholarship/', '2026-08-28');

INSERT INTO living_cost_estimates (estimate_id, country_code, city, university_id, category, monthly_estimate_eur, source_url, source_checked_on, notes) VALUES
    ('b57827ce-a51b-4863-a653-840f59119f00', 'BG', 'Blagoevgrad', '326ec084-de2c-485e-b1fd-e47ce6c83187', 'ACCOMMODATION', 360.00, 'https://www.aubg.edu/wp-content/uploads/2026/04/AUBG-Cost-of-Attendance_2026-2027.pdf', '2026-08-28', 'AUBG''s official Cost of Attendance PDF states off-campus housing at "up to €360 per month" (1-bed) or "up to €460 per month" (2-bed); this row uses the lower, 1-bed figure. On-campus housing is instead seeded as this batch''s AUBG student_accommodations row.'),
    ('5b86992c-af5d-491b-8b11-787861d9999b', 'BG', 'Blagoevgrad', '326ec084-de2c-485e-b1fd-e47ce6c83187', 'FOOD', 166.67, 'https://www.aubg.edu/wp-content/uploads/2026/04/AUBG-Cost-of-Attendance_2026-2027.pdf', '2026-08-28', 'Same official Cost of Attendance PDF states meals at "€2,000" per year; converted here to a monthly-equivalent (2000 / 12 = 166.67) for consistency with this column''s monthly basis.'),
    ('f38d67f1-d638-4304-bade-a30b9f4dda46', 'HR', NULL, NULL, 'GENERAL', 500.00, 'https://www.studyincroatia.hr/live-and-work-in-croatia/finance-and-living-costs/', '2026-08-28', 'Study in Croatia (the official national promotion portal) states directly: "Average monthly living expenses in Croatia are estimated between 500 and 800 EUR." This row uses the lower bound; the page gives no city-level breakdown, only noting that larger/touristic cities tend to be more expensive.'),
    ('980cf10a-656b-40f6-a16a-6b6ba2288020', 'HR', 'Rijeka', 'ee11285b-d766-45a6-b900-0976453954ae', 'ACCOMMODATION', 120.00, 'https://uniri.hr/wp-content/uploads/2023/02/UNIRI-International-students-guide-2023.pdf', '2026-08-28', 'University of Rijeka''s own official International Student Guide states: "Accommodation – unsubsidized dormitory bed (monthly) ≈ 120 – 256" EUR; this row uses the lower bound. The document itself appears to internally reference the 2020/21 academic year despite its 2023 upload date, so it may be somewhat dated — flagged here rather than silently treated as current. The same guide states "the majority of Croatian higher education institutions do not offer scholarships or financial aid for international students," consistent with this batch''s reliance on a country-wide scholarship rather than a Rijeka-specific one.'),
    ('8ff3963a-4058-48de-a06b-53bbf2236df5', 'HR', 'Rijeka', 'ee11285b-d766-45a6-b900-0976453954ae', 'TRANSPORT', 18.00, 'https://uniri.hr/wp-content/uploads/2023/02/UNIRI-International-students-guide-2023.pdf', '2026-08-28', 'Same official guide: "the monthly student price for 1st city zone is ≈18 EUR" for public transport. Same staleness caveat as this batch''s Rijeka accommodation-category row applies.'),
    ('0bdc3c9a-dd94-4433-9d0b-840fad71ff28', 'LU', NULL, NULL, 'GENERAL', 1517.00, 'https://guichet.public.lu/en/citoyens/immigration/plus-3-mois/ressortissant-tiers/etudiant/etudiant-pays-tiers.html', '2026-08-28', 'Luxembourg''s official citizen/government-services portal (Guichet.lu) requires proof of "at least 80% of the current social inclusion income" per month for a student temporary-stay authorization, quantified elsewhere (the University of Luxembourg''s own admissions page) as "a minimum of €1,517 per month" — cross-verified as consistent across both official sources. This is an immigration financial-sufficiency threshold, not a general cost-of-living survey figure — see the visa_requirements row for this same batch''s related annual figure.'),
    ('082a0fcd-9b00-45e1-aabe-ffe06f891695', 'LU', NULL, 'cab9794d-355b-4b3e-bd42-1c9f5da5c828', 'ACCOMMODATION', 450.00, 'https://www.uni.lu/life-en/cost-of-living/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy. University of Luxembourg''s own cost-of-living page states: "University housing rent: minimum 450 € / month." This figure differs from the EUR 400/month figure on the university''s separate accommodation "offer" page (used in this batch''s student_accommodations row for Luxembourg) — both are disclosed rather than one silently discarded.'),
    ('ff33bf66-ac5e-4b98-aaf0-5628b8bff009', 'LU', NULL, 'cab9794d-355b-4b3e-bd42-1c9f5da5c828', 'FOOD', 360.00, 'https://www.uni.lu/life-en/cost-of-living/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy. Same page states: "Meals: 360 € / month" (at university canteen, "5€ per meal").');

INSERT INTO visa_requirements (visa_requirement_id, destination_country_code, applicant_country_code, visa_type, financial_proof_eur, estimated_processing_days, minimum_passport_validity_months, required_documents, application_url, source_url, source_checked_on, notes) VALUES
    ('bbde39fa-f14f-4d61-adad-6a32648f23b1', 'BG', NULL, 'STUDY_VISA', NULL, NULL, 18, ARRAY['passport_copy', 'passport_photo', 'moes_certificate_of_acceptance', 'travel_medical_insurance_30000_eur_coverage', 'proof_of_accommodation', 'proof_of_financial_means', 'police_clearance_certificate'], NULL, 'https://www.mfa.bg/upload/99380/2_Visa_D.pdf', '2026-08-28', 'Covers Bulgaria''s long-stay "Visa D" for students. Passport validity is a clean, directly confirmed official figure: "It should have a validity of at least 18 months" (plus "at least 2 empty pages for visa") — this batch''s only confirmed absolute minimum-passport-validity figure; every other country in this batch states either a relative rule or none at all. Financial means required: "minimum of 6 monthly wages," not itself quantified in EUR on this document, so financial_proof_eur is left NULL rather than computed from a minimum-wage figure sourced elsewhere. Insurance must cover a minimum of "30,000 euros" for repatriation and emergency medical care. Visa validity for students: up to one year ("360 days"). No processing-time figure is stated on this official document. A follow-on residence-permit application is required after arrival at Bulgaria''s Migration Directorate; the only official leaflet found for that step was explicitly titled for EU citizens and their family members, so its processing times are not used here as they do not apply to the general (mostly non-EU) international-student population.'),
    ('008a1f83-99ae-4300-b1a3-2bb9a43d0478', 'HR', NULL, 'RESIDENCE_PERMIT', NULL, NULL, NULL, ARRAY['travel_document', 'proof_of_purpose_of_stay', 'proof_of_sufficient_funds', 'health_insurance_proof'], NULL, 'https://mup.gov.hr/aliens-281621/stay-and-work/temporary-stay-of-third-country-nationals/281661', '2026-08-28', 'Covers Croatia''s temporary stay permit for third-country nationals studying at a Croatian university, per the Ministry of Interior (MUP). Quoted verbatim: "prove the purpose of their temporary stay," "have a valid travel document," "have funds to support themselves," "have health insurance." Passport-validity rule ("valid for at least 3 months longer than the period of validity of a temporary stay permit") is relative to the permit''s own length, not a fixed number, so minimum_passport_validity_months is left NULL — same discipline applied to Denmark and Lithuania''s relative rules in prior batches. No fixed-EUR minimum-funds figure or processing-time figure is stated on this official page (an unconfirmed secondary-source figure of "25% of average monthly net salary" was found but not verified on mup.gov.hr or mvep.gov.hr directly, so it is not used here). Temporary stay is granted "for up to one year"; residence address must be reported to the local police "not later than three days" after entry.'),
    ('ace42426-d328-4391-b1e9-7e146f3cd007', 'LU', NULL, 'RESIDENCE_PERMIT', 18211.00, 60, NULL, ARRAY['passport_copy', 'enrollment_certificate', 'proof_of_sufficient_resources', 'health_insurance_proof', 'criminal_record_extract_or_affidavit'], NULL, 'https://guichet.public.lu/en/citoyens/immigration/plus-3-mois/ressortissant-tiers/etudiant/etudiant-pays-tiers.html', '2026-08-28', 'Covers Luxembourg''s temporary authorization to stay for third-country-national students, per Guichet.lu (the official government-services portal). Financial requirement quoted verbatim: "at least 80% of the current social inclusion income" per month, cross-verified against the University of Luxembourg''s own admissions page, which states this as "€18,211 per academic year, or a minimum of €1,517 per month" — the annual figure is used here for consistency with this table''s other rows (note: €1,517 x 12 = €18,204, a EUR 7 discrepancy against the source''s own stated €18,211 annual figure; both figures are the source''s own, not recalculated). Processing time quoted verbatim: "The Ministry of Home Affairs normally responds within 60 days." Passport validity: only advisory language is given ("If the applicant''s passport is due to expire in less than 6 months, they are advised to renew it") — not a hard requirement, so minimum_passport_validity_months is left NULL rather than treated as a rule. Parental authorization is additionally required if the applicant is under 18.');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('e5bc394c-0020-4b08-a4db-7e1e168c347f', '1cf22577-039f-49fc-9ab2-424b7fd46566', 'UNIVERSITY_DORM', 'Sofia University "Studentski Grad" Hostels', 'Sofia', 60.00, 60.00, NULL, NULL, NULL, NULL, 'https://www.uni-sofia.bg/index.php/eng/the_university/international_relations_office/exchange_students/accommodation', '2026-08-28', 'Stated directly in EUR by this (EUR-updated) official page: "about 60-80 EUR (approx. 120-160 BGN)" per month, including water/heating/electricity; this row uses the lower bound. Deposit is "one month''s rent," refundable on departure — this row uses the same EUR 60 lower-bound figure. A separate, older Sofia University page (https://www.uni-sofia.bg/index.php/eng/admission/international_students/being_a_student_in_sofia) still quotes "approximately 50-70 BGN" for the same hostels and has not been updated to EUR post-euro-adoption; that BGN-only page is not used here. Rooms are furnished, shared by 2-3 students (no singles). Distance to campus is not stated on this page.'),
    ('4d427206-c85c-4232-8638-c51f27c996ff', '326ec084-de2c-485e-b1fd-e47ce6c83187', 'UNIVERSITY_DORM', 'American University in Bulgaria (Skaptopara Campus Residence Halls)', 'Blagoevgrad', 154.17, NULL, NULL, NULL, NULL, NULL, 'https://www.aubg.edu/wp-content/uploads/2026/04/AUBG-Cost-of-Attendance_2026-2027.pdf', '2026-08-28', 'Residence halls named "Skaptopara I," "Skaptopara II," and "Skaptopara III" (per https://www.aubg.edu/offices/residence-life-and-housing/, Wayback snapshot dated 2022-11-29). Rent figure: AUBG''s official Cost of Attendance PDF (fetched live 2026-08-28) states on-campus housing at "€1,850" to "€2,300" per year; this row uses the lower-bound annual figure converted to a monthly-equivalent (1850 / 12 = 154.17). No deposit figure or exact distance-to-classrooms is stated on either official page.'),
    ('bee61072-8672-4cdc-92ee-a0bacf22134a', 'b187620b-a811-4624-a9d6-de1b6bccf732', 'UNIVERSITY_DORM', 'University of Zagreb Student Residence Hall "Stjepan Radić"', 'Zagreb', 131.00, NULL, NULL, NULL, NULL, NULL, 'https://www.unizg.hr/fileadmin/rektorat/english/Student_services/Stjepan_Radic_brochure.pdf', '2026-08-28', 'Stated directly in EUR: "The monthly rate is 131,00 EUR payable in cash and card," for a shared double room (buildings 11/12). The same official brochure notes: "Only Croatian students enrolled in full degree programs at UNIZG are entitled to a state subsidy for accommodation. International students pay the full price." No deposit figure or distance-to-campus figure is stated in this document.'),
    ('742cf098-8acf-4bd3-bb7c-dbf5c3f9ac7c', '67285c9a-75e9-4d4c-9c56-208043d47fc4', 'UNIVERSITY_DORM', 'University of Split Student Dormitory (Hostel Spinut / "dr. Franjo Tuđman" Campus)', 'Split', 240.00, 500.00, NULL, NULL, NULL, NULL, 'https://www.unist.hr/accommodation/21697', '2026-08-28', 'Stated directly in EUR: "The monthly rent for a double room is 240 EUR"; "a reservation deposit of 500 EUR." Two dormitories are named: "Hostel Spinut" and the "dr. Franjo Tuđman (Campus)" dorm, the latter explicitly "situated at the University campus" (no numeric distance given for either).'),
    ('0704dc49-eba2-4fd6-9275-1ee1a9210df2', 'cab9794d-355b-4b3e-bd42-1c9f5da5c828', 'UNIVERSITY_DORM', 'University of Luxembourg Student Residences', 'Esch-sur-Alzette', 400.00, 900.00, NULL, NULL, NULL, NULL, 'https://www.uni.lu/life-en/accommodation/offer/', '2026-08-28', 'Fetched via the r.jina.ai read-only proxy. The university operates "33 residences" across Esch-sur-Alzette, Belvaux, Niederkorn, Oberkorn, Dudelange, Mondercange, Noertzange, and Luxembourg City. This page states rent of "€400 per month for Bachelor, Master, and incoming exchange students" (used here) — a separate official page (uni.lu/life-en/cost-of-living/, seeded as this batch''s Luxembourg ACCOMMODATION living_cost_estimates row) instead states "minimum 450 € / month"; both figures are disclosed rather than reconciled. Deposit figure (EUR 900) is the cost-of-living page''s own literal example, itself tied to its EUR 450 rent figure ("900€ for 450€ monthly rent") rather than recalculated against the EUR 400 figure used here for monthly_rent_eur — flagged rather than silently adjusted. Housing is explicitly not guaranteed: "all candidates are strongly encouraged to explore alternative accommodation options." Distance to campus is not stated on this page.');
-- Batch: additional global/country-wide scholarships and student financial-
-- support resources (research/verification pass 2026-08-28/2026-08-29), not
-- tied to any single seeded university. GBP figures (Commonwealth Shared
-- Scholarships) converted at 1 EUR = 0.8572 GBP (ECB reference rate via
-- frankfurter.dev, 2026-08-28); Germany/France/Netherlands figures are
-- already in EUR.
-- Deliberate omissions / notable findings from this batch:
--  - Erasmus Mundus Joint Master Degrees: no official EU page (EACEA's own
--    catalogue page, or the EU-hosted Erasmus Mundus Association flyer)
--    states a specific EUR stipend figure — both describe coverage only in
--    general terms ("participation costs, travel, visa, and living
--    allowances"), so amount_eur is left NULL rather than using the
--    EUR 1,000-1,400/month figures found only on third-party scholarship-
--    aggregator sites.
--  - Australia Awards Scholarships: the official government pages checked
--    (dfat.gov.au, studyaustralia.gov.au) list what is covered (tuition,
--    return travel, establishment allowance, OSHC, a living-expenses
--    contribution) but none state the exact AUD stipend figure — a fortnightly
--    "A$1,323.42" figure exists only on a university's own scholarships page,
--    not a DFAT page, and direct fetches of that university page were
--    blocked (HTTP 403) — amount_eur is left NULL rather than using an
--    unconfirmed-on-an-official-government-page figure.
--  - Two well-known standardized-test fee-waiver programs were investigated
--    and explicitly EXCLUDED rather than seeded, because they are not
--    genuinely open to international students residing/testing abroad: the
--    ETS TOEFL Fee Reduction Service ("Foreign exchange students are not
--    eligible for fee reduction vouchers," US high-school seniors only) and
--    the College Board SAT fee waiver ("International Students... residing
--    overseas and studying outside the US will not be eligible"). The ETS
--    GRE Fee Reduction Program was also excluded for the same reason (US
--    citizens/permanent residents only). A British Council/IDP IELTS fee-
--    waiver programme could only be confirmed as a regionally-limited
--    (India-specific) offering, not a genuinely international one, and is
--    also excluded.
--  - The IIE Emergency Student Fund is seeded with an explicit caveat: it is
--    nomination-based (a student cannot apply directly; their US host
--    institution must nominate them), restricted to students already
--    matriculated at an accredited US institution, and periodically closed
--    between crisis-specific funding windows — reported honestly as a
--    narrower resource than a general open emergency fund, not oversold.
--  - Jesuit Worldwide Learning was investigated for REFUGEE_SUPPORT but not
--    seeded: its official "About Us" page did not state whether tuition is
--    free/subsidized, and a follow-up admissions page 404'd before cost/
--    eligibility could be confirmed.
--  - Nightline Association (UK student listening service) was investigated
--    for MENTAL_HEALTH but not seeded: nightline.ac.uk returned HTTP 404 or
--    empty content on every direct fetch attempt during this research pass,
--    so no official quote could be obtained; Samaritans is seeded instead,
--    since its official page was fetchable and explicit about being free,
--    24/7, and open to anyone regardless of nationality/status.
--  - Campus France and the DAAD regional-office/information-centre network
--    are both seeded under FREE_ADVISING, but neither official page fetched
--    during this research pass explicitly states the word "free" the way
--    EducationUSA's own page does — both are long-established, embassy-
--    affiliated public diplomacy/education-promotion agencies (not
--    commission-based agents), and this nuance is disclosed in each row's
--    notes rather than asserting "free" as directly confirmed fact.
--  - The EducationUSA Opportunity Funds Program's coverage/eligibility
--    details are sourced from an official NACAC page's own description of
--    the programme (nacacnet.org, directly fetched) rather than
--    educationusa.state.gov itself, since every attempt to fetch a detail
--    page on educationusa.state.gov during this pass returned HTTP 500; the
--    programme's real, current existence was independently confirmed via a
--    direct fetch of one of its own official event-announcement pages.

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('bbe31358-b515-4bd2-a830-a42e329cb85b', 'Erasmus Mundus Joint Master Degrees (EMJM) Scholarships', 'European Union (Erasmus+ programme, administered by EACEA)', NULL, NULL, NULL, 'FULL_FUNDING', NULL, 'Open to Master''s-level students worldwide ("Master''s level students from all over the world can apply"). Applicants must "have a bachelor''s degree (first degree), or be in your last year of bachelor studies" and graduate before the programme starts (or hold an officially recognised bachelor''s-equivalent level of learning). Covers a joint or multiple degree studied at 2+ universities in different countries. Per the EU-hosted Erasmus Mundus Association flyer: "Full scholarships are available for the best-ranked students worldwide, covering participation costs, travel, visa, and living allowances" — no official EUR monthly-stipend figure is stated on either this flyer or EACEA''s own catalogue page (a commonly-cited EUR 1,000-1,400/month figure appears only on third-party scholarship-aggregator sites and is not used here). Applications are NOT submitted to one central EU body: "Interested students should visit the master website and directly contact the consortium for information on courses, application procedures and scholarships availability." Applications are typically due "between October and January" for the following academic year; a new list of funded joint master''s programmes is published annually in the Erasmus Mundus Catalogue.', NULL, 'https://www.eacea.ec.europa.eu/scholarships/erasmus-mundus-catalogue_en', 'https://www.eacea.ec.europa.eu/scholarships/erasmus-mundus-catalogue_en', '2026-08-28'),
    ('37a4922c-0fa4-40c3-84b3-bccbca657f7a', 'Commonwealth Shared Scholarships', 'Commonwealth Scholarship Commission in the UK (CSC), UK Foreign, Commonwealth & Development Office', 'GB', NULL, NULL, 'FULL_FUNDING', 1693.89, 'Quoted verbatim: "full fees are covered by agreement between the CSC and the UK university"; stipend "£1,452 per month, or £1,781 per month for those at universities in the London metropolitan area" (amount_eur here uses the standard, non-London rate, converted at 1 EUR = 0.8572 GBP — the London rate converts to roughly EUR 2,077.69/month instead); "Approved airfare from the Scholar''s home country to the UK and return at the end of the award"; a warm clothing allowance "where applicable." Restricted to citizens of, or those granted refugee status by, one of 42 eligible Commonwealth countries (e.g. Bangladesh, Ghana, India, Jamaica, Kenya, Nigeria, Pakistan, South Africa), who are "permanently resident" there. "These scholarships are for Master''s courses only and not for undergraduate or PhD study" (a separate, differently-structured Commonwealth Scholarship/Split-site PhD scheme exists for other degree levels, not this row). Applicants must not have "studied or worked for more than one (academic) year or more in a high income country." Intended for candidates from least-developed and middle-income countries "who would not otherwise afford to study in the UK." Applications for the 2026/27 academic year were already closed at the time of this research pass (2026-08-28) — check the official page for the next cycle''s dates.', NULL, 'https://cscuk.fcdo.gov.uk/scholarships/commonwealth-shared-scholarships/', 'https://cscuk.fcdo.gov.uk/scholarships/commonwealth-shared-scholarships/', '2026-08-28'),
    ('6c2ecc35-53be-44a2-909d-2fd069905fe7', 'Study Scholarships - Master Studies for All Academic Disciplines', 'DAAD (German Academic Exchange Service)', 'DE', NULL, NULL, 'LIVING_STIPEND', 992.00, 'Quoted verbatim: monthly "Scholarship payments of 992 euros a month," plus "payments towards health, accident and personal liability insurance," a "travel allowance (upon application only)," and an "annually study allowance of €460." Eligibility: "You can apply if you have completed your first degree (e.g. Bachelor''s or Diplom) at the latest by the time the funding period begins" — the degree should generally not date back more than 6 years at the application deadline. Duration: "intended for visits of between 10 and 24 months," depending on the chosen programme''s length, for a postgraduate course of study in Germany. Stated directly in EUR — no conversion needed. At the time of this research pass, the page stated funding for this specific cycle "must begin in 2027" and that applications were not yet open ("Currently you cannot apply for this programme") — check the official page for the current application window (normally opens 1 June, with a stated deadline).', NULL, 'https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database/?detail=50026200', 'https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database/?detail=50026200', '2026-08-28'),
    ('4db2454e-9f31-4b4a-b457-87fc3583a038', 'NL Scholarship (formerly Holland Scholarship)', 'Nuffic (Dutch Organisation for Internationalisation in Education), on behalf of the Dutch Ministry of Education, Culture and Science', 'NL', NULL, NULL, 'PARTIAL_TUITION', 5000.00, 'Quoted verbatim: "The scholarship amounts to €5,000. You will receive this in the first year of your studies." A one-time award, not renewable across multiple years. Eligibility, quoted verbatim: "Your nationality is non-EEA" — this requirement explicitly excludes European Economic Area (and Swiss) citizens. Applicant must apply "to a participating Dutch institution for a full-time bachelor''s or master''s programme," satisfy that institution''s own specific requirements, and have no prior degree from a Dutch educational institution. "They will grant scholarships to 2,112 students per academic year" nationally, across all participating institutions combined. The application itself is submitted through the individual participating Dutch university/university of applied sciences the student is applying to, not centrally through Nuffic — deadlines therefore vary by institution.', NULL, 'https://www.studyinnl.org/finances/nl-scholarship', 'https://www.studyinnl.org/finances/nl-scholarship', '2026-08-28'),
    ('e85d84c0-1ea3-4ddf-8105-c6e076057966', 'Australia Awards Scholarships', 'Australian Government, Department of Foreign Affairs and Trade (DFAT)', 'AU', NULL, NULL, 'FULL_FUNDING', NULL, 'Quoted verbatim (Study Australia, the official Australian government study-destination portal): coverage includes "Full tuition fees," "Return air travel," "Establishment allowances," "Overseas Student Health Cover (OSHC)," and "Contribution to living expenses." No official government page found in this research pass states the exact stipend amount in AUD — a fortnightly "A$1,323.42" Contribution to Living Expenses figure appears only on a receiving university''s own scholarships page (fetch blocked, HTTP 403), not a DFAT page, so amount_eur is left NULL rather than using that unconfirmed-on-a-government-source figure. Eligibility is restricted to "individuals from a selection of developing countries" across Asia, the Pacific, Africa, and the Middle East — NOT globally open; applicants must check DFAT''s own country-participation list, since a country not listed makes an applicant ineligible regardless of other qualifications. Open to both undergraduate and postgraduate study. Applicants must demonstrate "leadership skills, a strong commitment to development, and the potential to make a positive impact," and must not hold Australian or New Zealand citizenship/permanent residency. The most recent confirmed intake deadline: "30 April 2026, 14.00 AEST" (already elapsed at the time of this research pass, 2026-08-28) — check the official page for the next cycle''s date.', '2026-04-30', 'https://www.studyaustralia.gov.au/en/tools-and-resources/news/australia-awards-scholarships-applications-2027', 'https://www.studyaustralia.gov.au/en/tools-and-resources/news/australia-awards-scholarships-applications-2027', '2026-08-28');

-- Correction to a row from an earlier batch (France/Belgium/Australia,
-- 2026-08-23): that batch's Eiffel Excellence Scholarship row was sourced
-- from Sorbonne Université's own re-statement of the programme and left
-- amount_eur NULL, since Sorbonne's page didn't itself state a stipend
-- figure (only an unconfirmed secondary-source ~EUR 1,181/month was noted
-- and deliberately excluded). This batch's direct fetch of Campus France's
-- own official programme page found a clean, directly-stated, current
-- figure, so the existing row is corrected in place here rather than
-- duplicated as a second row for the same scholarship.
UPDATE scholarships
SET amount_eur = 1200.00,
    coverage_type = 'LIVING_STIPEND',
    eligibility_notes = eligibility_notes || ' UPDATE (2026-08-28, sourced from Campus France''s own official programme page rather than a receiving institution''s page): Master''s-level scholars receive "a monthly allowance of €1,200 (from January 2026)"; a separate doctoral track pays "a monthly stipend of €2,100 (from January 2026)" (not used as this row''s amount_eur, which reflects the Master''s tier — this newer, officially-sourced figure supersedes this row''s original ~EUR 1,181/month secondary-source mention, which was correctly left unused at the time). Both levels additionally receive international/national transportation, insurance, and housing-search support. Explicitly: "tuition fees are not covered by the France Excellence Eiffel program." Critical process detail confirmed on the official page: a student cannot apply directly — "Applications sent directly by students or by foreign institutions will be declared ineligible." The French higher-education institution itself must submit the nomination online via Campus France.',
    source_url = 'https://www.campusfrance.org/en/the-france-excellence-eiffel-scholarship-program',
    source_checked_on = '2026-08-28'
WHERE scholarship_id = '2b070f42-7f30-4b45-8659-bd15976d4705';

INSERT INTO support_resources (resource_id, name, provider, category, country_code, description, eligibility_notes, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('9372570f-61eb-4584-9122-043f0f1e31bb', 'UNICORE (University Corridors for Refugees)', 'Italian universities, with support of UNHCR, the Italian Ministry of Foreign Affairs and International Cooperation, Caritas Italiana, Diaconia Valdese, and Centro Astalli', 'REFUGEE_SUPPORT', 'IT', 'A university-corridor programme giving recognized refugees a complete tuition-fee waiver at roughly 40 participating Italian universities, plus financial support for plane tickets and visa-related expenses, and a study grant for living costs in Italy.', 'Restricted to recognized refugees currently residing in one of 13 specific countries: Bangladesh, Burkina Faso, Cameroon, Ethiopia, India, Kenya, Mozambique, Niger, Nigeria, South Africa, Uganda, Zambia, or Zimbabwe — not open to refugees generally or from other countries of residence. Around 80 places are available per cycle.', 'https://universitycorridors.unhcr.it/', NULL, 'https://universitycorridors.unhcr.it/', '2026-08-29', 'Quoted verbatim: "Participation in university corridors, including the application process, is completely free of charge or fees." Most recent confirmed cycle deadline: 17 April 2026, for courses starting September 2026.'),
    ('5b38aa5c-8f23-471b-9fb5-b353b9ab2876', 'Windle Trust International Scholarships', 'Windle Trust International', 'REFUGEE_SUPPORT', NULL, 'Scholarships covering tuition, living expenses, travel, and study materials for postgraduate study (with UK, African, and distance-learning tracks), plus leadership and welfare support for the scholar during their studies.', 'Restricted to refugees, internally displaced persons, women/girls, people with disabilities, and other marginalised individuals who are specifically residents of Kenya, Uganda, Sudan, South Sudan, or Somalia — not a globally open programme; country_code is left NULL here because eligibility is based on the applicant''s country of residence, not one destination country (the programme funds study in the UK, Africa, or via distance learning).', 'https://applications.windle.org.uk/user/login', 'info@windle.org.uk', 'https://www.windle.org.uk/for-scholarship-applicants', '2026-08-29', 'Contact phone: +44 1865 712900.'),
    ('ba730885-bdc8-4c87-a1ee-bff42e069112', 'Kiron Education', 'Kiron Education (formerly Kiron Open Higher Education)', 'REFUGEE_SUPPORT', NULL, 'A free digital-access platform offering 700+ self-paced online courses (via partnerships with Coursera, DataCamp, Codecademy, and others), job-readiness programmes (e.g. its THRIVE programme), and community-integration support for refugees and migrants. This is NOT a degree-granting university-placement programme — it is upskilling and educational access, distinct from the tuition-waiver/scholarship programmes elsewhere in this table.', 'Open to refugees, migrants, and underserved communities globally, with no stated nationality or geography restriction; the organisation states it has reached learners from 160 countries.', 'https://campus.kiron.ngo', NULL, 'https://www.kiron.ngo/', '2026-08-29', 'Quoted verbatim (organisational mission statement): "everyone has an equal right to access quality education."'),
    ('303a4c1f-b1c0-443f-87cf-954acbaed027', 'Emergency Student Fund', 'Institute of International Education (IIE)', 'EMERGENCY_FUND', 'US', 'Provides emergency grants to international students already enrolled at an accredited US institution whose financial support has been disrupted by a natural disaster, war, or other sudden crisis (e.g. a specific 2026 window allowed IIENetwork member institutions to nominate students financially impacted by the June 2026 earthquakes in Venezuela).', 'IMPORTANT CAVEAT: this is NOT a fund a student applies to directly, and it is NOT open to prospective students. A student must already be "matriculated at an accredited U.S. educational institution," and that institution itself must nominate the student ("IIENetwork member institutions may now nominate up to 5 international students" per crisis window). The general programme is periodically "closed for nominations" between specific crisis-response windows, rather than continuously open — reported here as a narrower, institution-mediated resource rather than a general open emergency fund.', NULL, 'ESF@iie.org', 'https://www.iie.org/programs/emergency-student-fund/', '2026-08-29', 'Current Funding Efforts page: https://www.iie.org/programs/emergency-student-fund/current-funding-efforts — check this page for whichever crisis-specific window is currently open, since eligibility criteria and nomination caps shift with each one.'),
    ('62363b96-4ed4-427a-bb0a-3a968bedbb0a', 'Samaritans', 'Samaritans (UK-registered charity)', 'MENTAL_HEALTH', 'GB', 'A free, confidential, 24-hour listening service for anyone struggling to cope, reachable by phone, in person at local branches, or by letter.', 'No nationality or immigration-status restriction is stated — the official page describes it as open to anyone who wants "to talk about all sorts of concerns." A parallel service operates in the Republic of Ireland (Samaritans Ireland); this row is seeded under GB for the phone line quoted here.', NULL, NULL, 'https://www.samaritans.org/how-we-can-help/contact-samaritan/', '2026-08-29', 'Quoted verbatim: the phone line "is free to call from both landlines and mobiles, including pay-as-you-go mobiles," available "any time, day or night" on 116 123 (Welsh-language line: 0808 164 0123). Callers are not required to give their name; "your number is not displayed to our volunteer."'),
    ('d646d6ff-4541-4e61-b178-4cded3f7c672', 'UKCISA Student Advice Line', 'UK Council for International Student Affairs (UKCISA)', 'LEGAL_AID', 'GB', 'A free, independent, confidential phone advice line for international students (and their parents) with questions on UK immigration/visas, fee status, and student experience, staffed by advisers registered with the UK''s Immigration Advice Authority (IAA).', 'Aimed at international students studying in, or applying to study in, the UK; the official page describes the line as being for use "after reviewing website resources" but does not explicitly restrict it to only already-enrolled students.', NULL, NULL, 'https://www.ukcisa.org.uk/about-us/student-advice-line/', '2026-08-29', 'Quoted verbatim: "free, independent, and confidential, one-to-one advice" (though "you may be charged by your service provider" for the call itself); open "Monday to Friday (except for public holidays) from 13.00 to 16.00 (UK time)" on +44 (0) 20 7788 9214. Explicitly phone-only: "We do not provide advice on social media or via email."'),
    ('347dd0b2-0ae2-454b-913f-3154e6f52fc3', 'Campus France Advising Network', 'Campus France (French public agency, under the authority of French embassies)', 'FREE_ADVISING', 'FR', 'A worldwide network of around 255-327 Campus France offices and annexes (figures vary slightly by page/date) across roughly 124-139 countries, staffed by counsellors who help prospective students choose a French programme, understand the application procedure for their specific situation, and navigate student-visa/residence-permit requirements.', 'Open to any prospective international student interested in studying in France; find the nearest office via the official geolocation search tool.', 'https://www.campusfrance.org/en/espaces', NULL, 'https://www.campusfrance.org/en/Campus-France-missions', '2026-08-29', 'Campus France is a public agency operating under the authority of French embassies (not a commission-based education agent), but no official page fetched during this research pass explicitly states the word "free" for its advising services the way EducationUSA''s own page does — this nuance is disclosed rather than asserting "free" as a directly confirmed fact.'),
    ('15c46e96-bb35-4246-bbde-67fe77243d28', 'DAAD Regional Offices and Information Centres', 'DAAD (German Academic Exchange Service)', 'FREE_ADVISING', 'DE', 'A global network of regional offices and information centres/information points covering more than 70 countries, offering academic advice to students and researchers interested in studying in Germany or engaging with the German research sector.', 'Open to any prospective student interested in studying in Germany; DAAD''s Info-Center also offers direct phone consultation in German and English.', NULL, NULL, 'https://www.daad.de/en/the-daad/daad-network/', '2026-08-29', 'Quoted verbatim: "The DAAD relies on a network of Regional Offices and Information Centres with coverage for more than 70 countries," where "Regional Offices and numerous Information Centres offer academic advice to students and researchers around the world." Info-Center phone consultation: +49 (228) 882-180, Mon-Thu 9am-12pm and 2pm-4pm CET/CEST, Fri 9am-2pm. No official page fetched during this research pass explicitly states the word "free" for this advising, unlike EducationUSA''s own page — disclosed here rather than asserted as directly confirmed fact.'),
    ('878108b5-2dae-49ee-a976-ee51546f8c7a', 'NACAC Fee Waiver', 'National Association for College Admission Counseling (NACAC)', 'APPLICATION_FEE_WAIVER', 'US', 'A standardized application-fee-waiver form, accepted by many (but not all) US colleges, that a student with demonstrated economic need can submit alongside a college application in place of paying the application fee — for up to four universities per form.', 'Quoted verbatim: "international students who will be first-time undergraduate students and can justify their economic need for a fee waiver are welcome to use the fee waiver form" — explicitly open to international applicants, not just US-domestic students. Economic-need criteria include prior eligibility for an SAT/ACT fee waiver, enrollment/eligibility in the US Free or Reduced Price Lunch programme, family income within the form''s alternate income-eligibility guidelines, or enrollment in a federal/state/local low-income-student support programme (e.g. Upward Bound). The form must be completed with the help of an authorized official (school counselor or community-based organisation) and sent directly to each university''s admissions office; each college "reserves the right to accept or decline" the waiver, so acceptance is not guaranteed everywhere.', NULL, NULL, 'https://www.nacacnet.org/student/fee-waivers/', '2026-08-29', 'The same official page recommends international students also consult an EducationUSA advising center and mentions the EducationUSA Opportunity Funds programme (seeded separately in this table) for students needing help with upfront testing/application/travel costs.'),
    ('c3d253e8-e955-4a1b-8303-404ef0c3de21', 'EducationUSA Opportunity Funds Program', 'U.S. Department of State, via EducationUSA advising centers', 'APPLICATION_FEE_WAIVER', 'US', 'A cohort-based advising and cost-assistance programme for highly qualified international students who are likely to receive substantial US financial aid but lack the up-front cash to apply — covering costs such as standardized-test fees (TOEFL/GRE/GMAT/SAT), college application fees, transcript/degree evaluations, US visa and SEVIS fees (including transport to a visa interview), airfare, and a one-time settling-in allowance.', 'Per the description on NACAC''s own official page (fetched directly), the programme "assists highly qualified students who lack financial resources to cover upfront costs to apply, such as testing, application fees, or airfare." Students are selected competitively via their local EducationUSA advising center for a one-to-two-year cohort-advising relationship — this is not a resource a student can access by applying directly online; contact your nearest EducationUSA advising center (seeded elsewhere in this table) to ask whether it runs an Opportunity Funds cohort.', 'https://educationusa.state.gov/find-advising-center', NULL, 'https://www.nacacnet.org/student/fee-waivers/', '2026-08-29', 'This row''s coverage/eligibility description is sourced from NACAC''s own official page describing the programme, since every direct-fetch attempt against educationusa.state.gov''s own Opportunity Funds detail pages returned HTTP 500 during this research pass; the programme''s current, real existence was independently confirmed via a direct fetch of one of its own official event-announcement pages on educationusa.state.gov.');
-- Batch: Malta, Slovenia (research/verification pass 2026-08-29). Both
-- countries use EUR directly, so no currency conversion was needed anywhere
-- in this batch. This closes out the project's full EU-27 country coverage.
-- Deliberate omissions / notable findings from this batch, documented here
-- so a future reader doesn't mistake a gap for an oversight:
--  - Malta: the American University of Malta (AUM) was the original third
--    target institution but its domain (aum.edu.mt) returned HTTP 403 on
--    every fetch attempt and a related subdomain failed DNS resolution;
--    Global College Malta (GCM), a real NCFHE-accredited private
--    institution, was substituted instead. No scholarship row is seeded for
--    GCM: no official page states one currently exists, and Malta's
--    national "Get Qualified" scheme (which GCM's own site links to) was
--    directly confirmed to explicitly exclude international students
--    ("Persons liable to tax in Malta" only). MCAST's final-year fee-
--    exemption scholarship is real and confirmed, but its euro value is
--    left NULL rather than computed by dividing its whole-programme total
--    by three, since the source never states fees are split evenly across
--    years. MCAST's own pages disagree on the international application
--    deadline (one states "30th June 2026," another "between April and
--    Mid-August") — both are disclosed rather than one silently picked.
--    Malta's visa document states passport validity as "a minimum of 3
--    months validity beyond the extended stay, OR ... at least 8 months of
--    validity, which is not older than ten years" — an ambiguous dual rule
--    that isn't a single clean absolute figure, so
--    minimum_passport_validity_months is left NULL rather than picking one
--    of the two readings. The official visa-fee amount is shown only as an
--    unreadable image on the government page and is not seeded.
--  - Slovenia: University of Maribor's own price-list document states a
--    base tuition figure (EUR 2,950/year) but explicitly warns that
--    English-medium delivery "will also include ... the actual costs that
--    arise from the implementation of the additional scope" — since no
--    page states the actual, final figure for the English-taught
--    specialisation this batch targets, no program_fees row is seeded for
--    it at all, rather than seeding the incomplete base figure as if it
--    were final. University of Maribor's and University of Primorska's
--    living-cost/accommodation data could not be verified via a directly
--    fetched official page in this research pass (JS-rendered pages,
--    broken links, or simply not reached) — Ljubljana's confirmed figures
--    are used as this batch's one representative Slovenia example instead
--    of guessing at either other city's numbers. University of Primorska's
--    Computer Science programme duration (commonly cited elsewhere as 3
--    years/180 ECTS) could not be confirmed on an official page reachable
--    in this pass and is left NULL rather than assumed. The country-wide
--    "Ad futura" scholarship confirmed in this batch (call 380) is
--    explicitly Master's-level and restricted to Western Balkan nationals
--    only — not a general international-student scholarship — and is
--    disclosed as such rather than presented as broadly open.

