INSERT INTO academic_programs (program_id, university_id, title, degree_level, field_of_study, duration_months, programme_url) VALUES
    ('76488e55-1da2-4f88-8b12-96621ce6eff2', '743e355d-39ec-49d8-80cf-a0fab04fd48f', 'Bachelor of Science (Honours) (Computing Science)', 'BACHELOR', 'Computer Science', 36, 'https://www.um.edu.mt/courses/overview/ubschicgcft-2026-7-o/'),
    ('bfbac67d-9238-47b5-8dae-a22b1eee987d', 'cfc89ff4-628e-4385-bf8b-429b7e663eb9', 'Bachelor of Science (Honours) in Creative Computing', 'BACHELOR', 'Computer Science', 36, 'https://mcast.edu.mt/wp-content/plugins/coursesimporter/data/ICT/IT6-A03-23_PIT.pdf'),
    ('e7c9db2e-3315-44f7-8d97-2f840721d537', 'f0ff4ed4-81ee-45f1-8ef7-43d3db98e21e', 'BA in Management', 'BACHELOR', 'Business Administration', 36, 'https://gcm.edu.mt/course/ba-in-management/'),
    ('6c894279-c776-4b62-ba0e-0ef711219ef0', '5a194110-40bb-415c-8a47-4ed9801c79a1', 'University Degree Programme in Business and Economics', 'BACHELOR', 'Business and Economics', 36, 'https://www.uni-lj.si/en/programmes/university-degree-programme-in-business-and-economics'),
    ('afbeacb0-b764-49f3-b253-87feba25aee8', '8f75ddbe-d003-41f6-b5ec-0243d1db6144', 'Economic and Business Studies (Economic and Business Sciences)', 'BACHELOR', 'Business Administration', 36, 'https://www.epf.um.si/en/study-programmes/study-in-english/1st-cycle-bachelors-degree-study-programme/'),
    ('293280b9-247d-4db3-be7d-b230da9a7735', '6f7cf326-e285-48c1-95c9-d39e3d4d0cf5', 'Computer Science', 'BACHELOR', 'Computer Science', NULL, 'https://www.famnit.upr.si/en/computer-science-studies/');

INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('3ea9bb78-fac8-4cc7-9605-7ed75e38324d', '76488e55-1da2-4f88-8b12-96621ce6eff2', NULL, NULL, 'IELTS', '6.0', NULL, 'https://www.um.edu.mt/study/admissionsadvice/international/englishlanguagerequirements', '2026-08-29', 'IELTS Academic overall 6.0 (Writing 6.0, Reading/Listening/Speaking 5.5 each). TOEFL iBT alternative: overall 80 (pre-January 2026) or overall 4/Writing 4.5 (ETS''s post-rescale figures, from January 2026); ISET Band 5 also accepted. "All test scores remain valid for 2 years from course commencement." Academic entry route (international/overseas qualifications): "Two Advanced Level passes at Grade C or better in Pure Mathematics and one other subject" plus "One Intermediate Level pass in any subject" — no single numeric CGPA/percentage figure is published, so left NULL rather than guessed. Application deadlines for the October 2026 intake: general late deadline 15 September 2026, 14:00; non-EU applicants who will need a visa must apply earlier, by 1 July 2026, 14:00.'),
    ('8081aede-0804-4639-a3dc-e667e1a3a4a1', 'bfbac67d-9238-47b5-8dae-a22b1eee987d', NULL, NULL, NULL, NULL, NULL, 'https://mcast.edu.mt/wp-content/plugins/coursesimporter/data/ICT/IT6-A03-23_PIT.pdf', '2026-08-29', 'MCAST''s official Public Information Template for this course states only that "International candidates will be requested to meet English language certification requirements for access to the course" — no specific IELTS/TOEFL number is published on this official document (a commonly-cited "IELTS 6.0" figure appears only on third-party sites and is not used here), so language_test_name/minimum_language_score are left NULL. Academic entry route: "MCAST Advanced Diploma in IT (iGaming or Software Development or Multimedia Software Development)" OR "2 A-Level passes and 2 I-Level passes" with a compulsory A-Level in Computing and a compulsory A-Level or I-Level in Mathematics (Pure or Applied) or Physics. Two official MCAST pages disagree on the international application deadline: https://mcast.edu.mt/int-students/ states "Applications for international applicants open in October 2026. The deadline for applications is 30th June 2026," while https://mcast.edu.mt/key-information-for-full-time-programmes/ states applications "are accepted between April and Mid-August" — both are reported here rather than one silently picked.'),
    ('c764732e-a6d8-4897-a164-23ffad8f1980', 'e7c9db2e-3315-44f7-8d97-2f840721d537', NULL, NULL, 'IELTS', '5.5', ARRAY['cv', 'academic_transcripts', 'police_conduct_certificate_if_applicable', 'passport_copy', 'english_language_certificate', 'personal_statement', 'reference_letter'], 'https://gcm.edu.mt/admissions-process/', '2026-08-29', 'IELTS overall 5.5 minimum, per GCM''s general admissions-process page (not confirmed as a programme-specific figure). Academic entry route (Maltese matriculation-equivalent): "two subjects at an advanced level, three other subjects at an intermediate level" OR "three subjects at Advanced Level (MQF 4)," plus "a pass at Grade 5 or better in the English Language Secondary Education Certificate." No numeric minimum-CGPA figure is published. Application deadlines (per the programme''s own course page): September 2026 intake, Friday 19 June 2026; December 2026 intake, Friday 4 September 2026.'),
    ('87b2ca87-a96d-4ff0-9c4c-8b8912d770e5', '6c894279-c776-4b62-ba0e-0ef711219ef0', NULL, NULL, 'CEFR', 'B2', NULL, 'https://www.ef.uni-lj.si/en/study/bachelors-programmes/prijava-in-vpis', '2026-08-29', 'English requirement for the English-taught track: CEFR B2; TOEFL iBT 72-93 also accepted as evidence (range as stated on the page). Accepted qualifications: "a General Matura certificate," "a Vocational Matura certificate ... plus General Matura Mathematics," or an equivalent final exam completed before 1 June 1995. Where places are limited, General Matura holders are selected using a weighted formula ("60% based on exam results + 40% based on GPA in years 3-4") rather than one published minimum-CGPA threshold, so minimum_cgpa_percentage is left NULL. Application deadlines for 2026/27: first period 18 February - 18 March 2026; second period 20-27 August 2026. No documents checklist beyond the qualification routes above is itemised on this page, so left NULL rather than guessed.'),
    ('9a0a8db5-7f79-4912-91b1-6734bdfe3b57', 'afbeacb0-b764-49f3-b253-87feba25aee8', NULL, NULL, NULL, NULL, NULL, 'https://moja.um.si/en/future-students/Strani/enrolment.aspx', '2026-08-29', 'No numeric overall CGPA/percentage figure or English-test score is published for this specific programme on a reachable official page, so both are left NULL rather than guessed. Non-EU application periods for 2026/27: first period 18 February - 18 March 2026; second period 3-4 September 2026. Decisions are issued "by the 1st of September 2026 at the latest," or "by 14 July 2026" specifically for candidates applying to English-taught programmes. As of the 2026/27 cycle (per the Higher Education Act, ZVIS-1, Art. 13), a mandatory interview applies to foreign-citizen applicants from a designated list of "higher migration risk" countries (the official list includes, among others, India, Pakistan, China, and Nigeria).'),
    ('b8ead8e7-b5a4-48e1-b852-2fa8d822520e', '293280b9-247d-4db3-be7d-b230da9a7735', NULL, NULL, NULL, NULL, NULL, 'https://welcome.upr.si/student/prepare/application-enrolment/', '2026-08-29', 'No numeric overall CGPA/percentage figure, English-test score, or itemised documents checklist could be confirmed for this specific programme on a reachable official page during this research pass (several dedicated programme-detail pages returned only navigation content or a 404 on a linked course-description PDF) — all left NULL/unstated rather than guessed. A CEFR "B1 (*some courses require B2)" English requirement is stated elsewhere on the site, but only for exchange/mobility applicants, not confirmed as applying to degree-seeking Computer Science bachelor''s applicants specifically. Non-EU application periods (except Western Balkan citizens, who follow a different process): first period 18 February - 18 March 2026 (document deadline the same, or 13 July 2026 for candidates whose certificates were issued in 2026), results by 17 July 2026; second period 20-27 July 2026, results by 3 August 2026.');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('29bc9567-9154-4fb9-9b37-7cdb90e68035', '76488e55-1da2-4f88-8b12-96621ce6eff2', 'TUITION_PER_YEAR', 'INTERNATIONAL', 10800.00, 'https://www.um.edu.mt/courses/overview/ubschicgcft-2026-7-o/', '2026-08-29', 'Stated directly in EUR: "€10,800 per academic year" for Non-EU/International students — no conversion needed.'),
    ('b7c90c70-268f-4b0c-a250-e0c23a14e998', '76488e55-1da2-4f88-8b12-96621ce6eff2', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://www.um.edu.mt/study/feesfunding/', '2026-08-29', 'Stated directly in EUR: "EUR 100 until the first deadline"; a higher EUR 200 fee applies to late applications (not seeded separately here).'),
    ('c48cc700-29a4-4213-ae15-c77f7af8e5f6', 'bfbac67d-9238-47b5-8dae-a22b1eee987d', 'TUITION_TOTAL', 'INTERNATIONAL', 19500.00, 'https://mcast.edu.mt/wp-content/plugins/coursesimporter/data/ICT/IT6-A03-23_PIT.pdf', '2026-08-29', 'Stated directly in EUR: "€19,500.00 (Applicable for Non-EU and Non-EEA Countries)" for the whole 3-year programme, explicitly marked "indicative" in MCAST''s official Public Information Template — no conversion needed. No application fee is confirmed on an official MCAST page, so none is seeded.'),
    ('0cc5263a-3f02-4371-abc9-e32029b8fb56', 'e7c9db2e-3315-44f7-8d97-2f840721d537', 'TUITION_PER_YEAR', 'INTERNATIONAL', 6100.00, 'https://gcm.edu.mt/course/ba-in-management/', '2026-08-29', 'Stated directly in EUR: "International students: €6,100" per year (Local/EU students pay a lower €4,500/year rate, not used here since student_category is INTERNATIONAL) — no conversion needed.'),
    ('ae0d9180-8600-4eb1-9026-177ba7ab30ec', 'e7c9db2e-3315-44f7-8d97-2f840721d537', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://gcm.edu.mt/course/ba-in-management/', '2026-08-29', 'Stated directly in EUR: "€100" application fee — no conversion needed.'),
    ('65c466dc-bf3e-4648-bc62-fa2741b4724f', 'e7c9db2e-3315-44f7-8d97-2f840721d537', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 250.00, 'https://gcm.edu.mt/course/ba-in-management/', '2026-08-29', 'Stated directly in EUR: a Year-1 "Registration Fee" of "€250." A separate, additional Year-1 "International Visa Support Document Fee" of €200 is also listed on the same page but not seeded as its own row.'),
    ('9f71f94b-06b0-4da1-a8ad-5ebd2edbca6c', '6c894279-c776-4b62-ba0e-0ef711219ef0', 'TUITION_PER_YEAR', 'INTERNATIONAL', 3400.00, 'https://www.ef.uni-lj.si/en/study/bachelors-programmes/solnina-in-cenik', '2026-08-29', 'Stated directly in EUR: "The Tuition fee for Full-time study is €3,400 per year" — no conversion needed. No application fee is stated on this page.'),
    ('e30b2969-e7fa-44b5-b6c1-738601fd99f1', '293280b9-247d-4db3-be7d-b230da9a7735', 'TUITION_PER_YEAR', 'INTERNATIONAL', 3150.00, 'https://www.upr.si/en/study--enrolment/529-tuition-fees/', '2026-08-29', 'Stated directly in EUR: "Computer Science (academic) - in Slovene / English language - 3.150,00 €" per year — no conversion needed. The same page states tuition is free of charge for students from Slovenia, the EU/EEA, Serbia, Bosnia and Herzegovina, Montenegro, North Macedonia, and Kosovo (not applicable to the INTERNATIONAL category used here).');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('aa3423f3-73e7-4eaf-aa08-fb6382eab85a', 'Islands & Small States Institute Scholarships', 'University of Malta, Islands and Small States Institute', 'MT', '743e355d-39ec-49d8-80cf-a0fab04fd48f', NULL, 'FULL_TUITION', 1000.00, 'Covers "University of Malta Tuition Fees" for the Master''s programme in Research on Islands and Small States, plus a "EUR 1,000 research grant available for a maximum of twelve (12) months only" (amount_eur here reflects only this quantifiable research-grant component, not the separately-covered tuition amount). Restricted to "nationals of Small Island Developing States eligible for Official Development Assistance"; "Dual nationals who also hold EU/EEA or non-SIDS nationality are not eligible." Requires full acceptance to the M.A. in Research on Islands and Small States — not tied to this batch''s seeded Computing Science bachelor''s programme. An annual enrolment fee of €400 applies if a one-year extension is needed.', '2026-07-01', 'https://www.um.edu.mt/study/feesfunding/scholarships/postgraduateissischolarships/', 'https://www.um.edu.mt/study/feesfunding/scholarships/postgraduateissischolarships/', '2026-08-29'),
    ('e2db879b-d9af-4a28-b224-c055d5d13b91', 'Ad futura Scholarship for Foreign Citizens (Public Call 380)', 'Public Scholarship, Development, Disability and Maintenance Fund of the Republic of Slovenia (Ad futura)', 'SI', NULL, NULL, 'LIVING_STIPEND', 9600.00, 'Quoted verbatim (translated): "the scholarship may be granted for living costs in the amount of EUR 9,600 annually" — covers living expenses only, not tuition. Restricted to nationals of Western Balkan countries (Bosnia and Herzegovina, Montenegro, Kosovo, North Macedonia, Serbia); Master''s (postgraduate) level only; limited to approved fields (natural sciences, mathematics, statistics, ICT, engineering, construction, agriculture, forestry, fisheries, veterinary science, healthcare, social services) — not a general international-student scholarship, and not tied to any one of this batch''s three seeded (bachelor''s-level) programmes. Other Ad futura sub-programmes exist with potentially different eligibility but were not independently confirmed in this research pass.', '2026-09-02', 'https://www.srips-rs.si/vsi-razpisi/razpis/javni-razpis-za-dodelitev-stipendij-tujim-drzavljanom-za-studij-v-sloveniji-za-leto-2026-380-javni-razpis', 'https://www.srips-rs.si/vsi-razpisi/razpis/javni-razpis-za-dodelitev-stipendij-tujim-drzavljanom-za-studij-v-sloveniji-za-leto-2026-380-javni-razpis', '2026-08-29');

INSERT INTO living_cost_estimates (estimate_id, country_code, city, university_id, category, monthly_estimate_eur, source_url, source_checked_on, notes) VALUES
    ('0d7f7fb7-8173-4c02-ab96-1953c6aaa6d6', 'MT', 'Msida', '743e355d-39ec-49d8-80cf-a0fab04fd48f', 'ACCOMMODATION', 550.00, 'https://www.um.edu.mt/international/students/livingcosts/', '2026-08-29', 'University of Malta''s own official living-costs page states "Shared Accommodation: €550-700" per month; this row uses the lower bound. Single accommodation (residence/apartment) is stated separately as €800-1,600/month and is not used here.'),
    ('f3efef16-a459-49f9-ae1f-17c2c719fa39', 'MT', 'Msida', '743e355d-39ec-49d8-80cf-a0fab04fd48f', 'FOOD', 450.00, 'https://www.um.edu.mt/international/students/livingcosts/', '2026-08-29', 'Same official page states: "Food & Beverages: €450 (excluding eating out and take outs)" per month.'),
    ('0217cc20-d780-4032-b14a-6ae165d45efc', 'SI', 'Ljubljana', '5a194110-40bb-415c-8a47-4ed9801c79a1', 'GENERAL', 600.00, 'https://www.uni-lj.si/en/study/international-students/accommodation-transport-and-cost-of-living', '2026-08-29', 'University of Ljubljana''s own official page states directly: "you will need to have at least 600,00 € monthly for living costs, above the cost of your tuition." The same page notes sample costs: a subsidised student meal ~€5, a non-subsidised restaurant meal €8-15, and a monthly public-transport (Urbana) card ~€20.');

INSERT INTO visa_requirements (visa_requirement_id, destination_country_code, applicant_country_code, visa_type, financial_proof_eur, estimated_processing_days, minimum_passport_validity_months, required_documents, application_url, source_url, source_checked_on, notes) VALUES
    ('fca6fc3d-311d-4cd4-a8d2-b2158330fd83', 'MT', NULL, 'STUDY_VISA', 11400.00, 56, NULL, ARRAY['application_form', 'passport_copy', 'passport_photo', 'travel_medical_insurance', 'proof_of_accommodation', 'proof_of_financial_means', 'flight_booking', 'letter_of_acceptance'], NULL, 'https://identita.gov.mt/central-visa-unit-national-visa-long-stay-visa/', '2026-08-29', 'Covers Malta''s National Long-Stay (D) Visa for study, "issued for a period exceeding 90 days, but no longer than 365 days," per Identity Malta Agency''s Central Visa Unit. Financial-proof figure is the University of Malta''s own stated e-Residence Permit bank-statement requirement ("a minimum of 950 Euro for each month of stay in Malta"), annualized here (x12) for consistency with this table''s other rows; a separate, differently-worded visa-stage requirement on the same UM page states "a minimum balance of at least 75% of the national minimum wage for every month of study or Eur 18 for each day" — both figures are disclosed rather than one silently discarded. Estimated processing time reflects the upper end of the government page''s stated "6-8 weeks" range (56 days). Passport-validity wording is an ambiguous dual rule — "a minimum of 3 months validity beyond the extended stay, OR ... at least 8 months of validity, which is not older than ten years" — not one clean absolute figure, so minimum_passport_validity_months is left NULL rather than picking one reading. Non-EU/EEA students studying at least one academic year must additionally apply for an e-Residence Permit "within the first 3 months (90 days) of their arrival in Malta." The official visa fee is shown only as an unreadable image on the government page and is not seeded.'),
    ('23b35de3-253a-44ea-a0c3-da8e396ea5f9', 'SI', NULL, 'RESIDENCE_PERMIT', 6089.16, NULL, NULL, ARRAY['application_form', 'signature_form', 'passport_copy', 'biometric_photo', 'fingerprints', 'proof_of_enrollment', 'health_insurance_proof', 'criminal_record_certificate'], NULL, 'https://www.uni-lj.si/en/study/international-students/temporary-residence-permit/non-eu-citizens/temporary-residence-permit-for-studies', '2026-08-29', 'Covers Slovenia''s Temporary Residence Permit for Studies (non-EU citizens). Financial-proof figure is the page''s own stated monthly requirement ("EUR 507,43 per month"), annualized here (x12) for consistency with this table''s other rows. No processing-time figure is stated on this page — it states only that timing "depends on the administrative office or Slovenian diplomatic mission." Passport-validity wording ("passport needs to be valid at least until the end of December next year") is a relative, calendar-tied administrative rule rather than a fixed number of months, so minimum_passport_validity_months is left NULL — same discipline applied to Denmark, Lithuania, and Croatia''s relative rules in prior batches. Administrative fees noted on the same page (not modelled as a table column): permit issuance/renewal EUR 50.00, application fee EUR 4.50, card printing EUR 15.47.');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('449aebda-d553-4d09-b641-75f94d686411', '743e355d-39ec-49d8-80cf-a0fab04fd48f', 'UNIVERSITY_DORM', 'Campus Hub Residence (University of Malta)', 'Msida', 940.33, NULL, NULL, NULL, NULL, NULL, 'https://maltauniversityaccommodation.com/wp-content/uploads/2025/12/Student-accommodation-rates-2026-27.pdf', '2026-08-29', 'Official 2026/27 rate card: a single ensuite room (shared kitchen) for the full academic year (19/09/2026-26/06/2027, 280 nights) is "€217.00/week," converted here to a monthly-equivalent (217 x 52/12 = €940.33/month); the same room for one semester (140 nights) is €231.00/week instead. A Twin Room runs €6,440.00 for the academic year and a Studio Apartment €12,040.00 (neither seeded separately). A mandatory one-time booking fee of €150.00 applies (not modelled as a deposit here, since the source describes it as a booking fee, not a refundable deposit) alongside a small mandatory ECO contribution (€0.50/person, capped at €5.00). Located inside the University of Malta''s own campus (Block O, Level 7, Msida), so no separate distance-to-campus figure applies. No deposit amount is stated on the official rate card.'),
    ('0d8aee3a-57ed-49ce-bf14-55e83937f5e8', '5a194110-40bb-415c-8a47-4ed9801c79a1', 'UNIVERSITY_DORM', 'Študentski dom AK (Ljubljana Student Residence Halls)', 'Ljubljana', 119.28, NULL, NULL, NULL, NULL, NULL, 'https://www.uni-lj.si/en/study/international-students/accommodation-transport-and-cost-of-living', '2026-08-29', 'University of Ljubljana''s own official page states: "The average price is €197.44, with the most expensive being €230.89 in Dom XIV and the cheapest being €119.28 in Dom AK, plus additional expenses of approximately €30.00." This row uses the cheapest named option (Dom AK); Dom XIV, the most expensive named option, is €230.89/month and is not seeded separately. Rooms are described as "double occupancy with shared bathrooms and kitchens." No deposit figure or distance-to-campus figure is stated on this page.');
-- Depth batch (added 2026-08-29): Germany, Italy, Spain. Requested specifically
-- by the user to deepen already-seeded countries, explicitly including small/
-- niche institutions alongside larger ones, not just flagship universities.
-- Every fact below was researched live against an official source on
-- 2026-08-29; all three countries use EUR, so no currency conversion is
-- needed. Where a fact could not be confirmed from a directly-fetched
-- official page, it is left NULL rather than guessed — several such gaps are
-- called out below and in individual row notes:
--   - LUISS Guido Carli's tuition for its Bachelor in Economics and Business
--     appears differently across three sources spanning different academic
--     years (2024/25 api.luiss.it ~EUR 12,000; 2026/27 WebSearch-snippet-only
--     ~EUR 14,000; 2027/28 official program page EUR 15,000). The 2027/28
--     official-page figure is used as the seeded value; the other two are
--     disclosed, not discarded, in the fee row's notes.
--   - University of Trento's MEIS program fee is NOT seeded at all: the
--     official page states fees are "based on the admission score you get"
--     with no published amount, and a WebSearch-only aggregator figure
--     (EUR 8,000-15,000/year) could not be independently verified.
--   - Several admission_requirements rows (LUISS's 2027/28 cycle, IE
--     University, UC3M, EU Business School) have no language-test/GPA
--     minimum recorded because the institution's own page did not publish
--     one (LUISS: not yet published for this cycle; the others: no minimum
--     found on the pages checked, or found only via an unverified aggregator
--     snippet, disclosed as such in notes rather than seeded as fact).
--   - ESADE's admission GPA is published only as "3.3/4.0 (>=B+) unweighted";
--     minimum_cgpa_percentage here (82.50) is a derived decimal-scale
--     conversion of that figure, disclosed in notes, not an officially
--     published percentage — same spirit as this project's disclosed
--     currency-conversion rows, applied to a grading-scale conversion
--     instead of an FX rate.
--   - UC3M's TUITION_PER_YEAR (EUR 6,822.60) is a calculated figure: the
--     official non-EU per-credit rate for this degree's fee band
--     (EUR 113.71/credit, "Type 3") multiplied by a standard 60-credit
--     academic year, disclosed in the row's notes along with the rate and
--     band it was calculated from.
--   - ESMT Berlin's and Frankfurt School's official pages both display a
--     TOEFL minimum as "5.0", which does not match the standard 0-120 iBT
--     scale and looks like a newer per-section display format. Rather than
--     seed a number that may be misread, only the same pages' unambiguous
--     IELTS minimum is recorded, with the TOEFL formatting question
--     disclosed in notes for a future reader to verify directly.
-- Existing DE/IT/ES universities (LMU Munich; Politecnico di Torino,
-- University of Bologna, Sapienza University of Rome; UPC, UPM, Universidad
-- de Granada) were checked for name overlap — no duplicates with the 15
-- universities below. Country-level visa_requirements rows for DE/IT/ES
-- already exist from earlier batches and are not duplicated here.

