INSERT INTO academic_programs (program_id, university_id, title, degree_level, field_of_study, duration_months, programme_url) VALUES
    ('dec71aae-2e15-4d92-a150-7523badc3c2f', '21ebda6f-d0d2-4797-84f8-c8208b3ecc8e', 'Bachelor of Science in Computer Science', 'BACHELOR', 'Computer Science', 36, 'https://constructor.university/programs/undergraduate-education/computer-science'),
    ('0a2dbf15-ee7e-431d-93ca-97457f04f164', 'cead504b-fecf-4260-866d-a2e325bef2bd', 'Master in Global Management', 'MASTER', 'Management', 24, 'https://esmt.berlin/master-programs/master-global-management/admissions'),
    ('b22f707a-aed1-4925-957e-c37ade73dee4', '32fb52c3-dcef-401d-82fd-2d0f1d4eead0', 'BA in Economics, Politics, and Social Thought', 'BACHELOR', 'Economics, Politics, and Social Thought', NULL, 'https://berlin.bard.edu/academics/degree-programs/studienprogramme'),
    ('dd969049-b102-4db6-b5e0-58906c4ddaf6', '100d5def-a82b-41ae-933a-4d7c06d79c42', 'Master in Management (MSc)', 'MASTER', 'Management', 24, 'https://www.frankfurt-school.de/en/study/master/master-in-management'),
    ('cfac3f1f-5ba9-49e9-b708-f7f5010fda2a', 'e1951b4f-4dc7-4174-afb9-2f37e1654106', 'Business Consulting (MSc)', 'MASTER', 'Business Consulting', 18, 'https://www.hs-furtwangen.de/en/programmes/business-consulting-master/details-of-programme/'),
    ('a5794141-a9cf-4bb9-9899-2c99129138be', '3fe37168-bbea-4b9a-924a-48d6df9b47fa', 'MSc in Computer Science and Engineering', 'MASTER', 'Computer Science and Engineering', 24, 'https://www.polimi.it/en/education/laurea-magistrale-programmes/programme-detail/computer-science-and-engineering'),
    ('52f91533-1e6c-4e73-aeb1-ac7bf2080379', 'f0caaefc-2f81-4367-a3c4-0ee3169e7f2e', 'Bachelor in Computer Science (L-31)', 'BACHELOR', 'Computer Science', 36, 'https://www.unibz.it/en/faculties/engineering/bachelor-computer-science'),
    ('5155dc7f-665f-4414-9acf-c3c94dbbf7f7', '90a23a68-1198-4036-b301-8f9c0d6584f3', 'Bachelor of Arts in International Affairs', 'BACHELOR', 'International Affairs', NULL, 'https://www.johncabot.edu/academics/degree-programs.aspx'),
    ('a8975438-e696-4a6a-8d9c-2711c80dc218', '6b6ff459-43ff-4ef1-b24b-17e05bbfcdec', 'Master''s Degree in European and International Studies (MEIS)', 'MASTER', 'European and International Studies', 24, 'https://corsi.unitn.it/en/european-and-international-studies'),
    ('0782d15d-2e35-4030-956c-bb1cff48da03', '3e4cb768-e5e1-4bc9-ab61-320391f909e6', 'Bachelor''s Degree in Economics and Business', 'BACHELOR', 'Economics and Business', 36, 'https://www.luiss.it/en/ammissione/offerta-formativa/laurea-triennale/economics-and-business'),
    ('02c81cf1-e791-4398-8ded-66aa08d1fd1e', '763c263f-b646-4d4d-aedc-f32aef85397e', 'Bachelor in International Relations', 'BACHELOR', 'International Relations', 48, 'https://www.ie.edu/university/studies/academic-programs/bachelor-international-relations/admissions-fees/'),
    ('9d4c58a9-0522-4164-9900-3fc2b62e7e0c', '76fbfa4c-e9ae-43c4-897a-f744e8bdfc92', 'Bachelor of Business Administration (BBA)', 'BACHELOR', 'Business Administration', NULL, 'https://www.esade.edu/bachelor/en/degrees/admissions/admission-requirements'),
    ('fbcceb0d-da76-45be-ba3d-3ceb1961f5db', '662a2a2e-f152-4128-9325-28f004bc83fc', 'Bachelor in International Studies', 'BACHELOR', 'International Studies', 48, 'https://www.uc3m.es/bachelor-degree/international-studies'),
    ('fd8aa591-9b63-4397-a6ab-53f61f14cb93', 'c9614c60-bb65-48e2-867f-3e030c333edb', 'Bachelor of Business Administration (BBA)', 'BACHELOR', 'Business Administration', 42, 'https://www.euruni.edu/en/Programs/Tuition-Fees.html'),
    ('2e27a8ce-3eb5-4bb9-8f85-70beb2f273c3', '1effb5e0-7966-4edd-bc8e-aca2e5f5da5d', 'Bachelor''s Degree in International Business', 'BACHELOR', 'International Business', 48, 'https://iqs.edu/en/studies/bachelors-degree-international-business/');

INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('d3afec62-0e25-408a-866d-e4287259703c', 'dec71aae-2e15-4d92-a150-7523badc3c2f', NULL, NULL, 'IELTS', '6.5', ARRAY['passport', 'secondary_school_transcripts', 'cv', 'motivation_statement', 'proof_of_english_proficiency'], 'https://constructor.university/admission-aid/application-information-undergraduate', '2026-08-29', 'No GPA minimum published — evaluated holistically. Accepted English-test alternatives: TOEFL iBT new-scoring 4.5 (old 0-120 scale: 90), Duolingo 110, Cambridge CPE grade A/B/C or C1 pass, SAT EBRW 600.'),
    ('0d934231-f220-446a-926b-024009b863df', '0a2dbf15-ee7e-431d-93ca-97457f04f164', NULL, NULL, 'IELTS', '7.0', ARRAY['bachelor_degree', 'cv', 'transcripts', 'recommendation_letter', 'gmat_or_gre_or_esmt_bat_score'], 'https://esmt.berlin/master-programs/master-global-management/admissions', '2026-08-29', 'Waived if native English speaker or prior degree fully taught in English. TOEIC 850 also accepted. GMAT below 600 / GRE below 304 described as "not considered competitive"; alternative ESMT Business Admissions Test (BAT), US$100. The official page also displays a TOEFL minimum of "5.0", which does not match the standard 0-120 iBT scale and appears to be a newer per-section score display — not recorded here as a number pending direct clarification; use the IELTS figure instead.'),
    ('4cc08918-d2a7-4b32-86b5-24490eed74a9', 'b22f707a-aed1-4925-957e-c37ade73dee4', NULL, NULL, 'TOEFL iBT', '100', ARRAY['secondary_school_transcript', 'school_report_from_counselor', 'two_recommendation_letters', 'common_app_or_coalition_app_with_scoir'], 'https://www.bard.edu/admission/international/', '2026-08-29', 'IELTS >=7 and Duolingo >=120 also accepted; waived for students schooled fully in English for 3+ years. Test-optional for SAT/ACT ("for over 50 years"). No GPA minimum published.'),
    ('170f2723-7fe5-4c6e-97ed-7463c1b7fda0', 'dd969049-b102-4db6-b5e0-58906c4ddaf6', NULL, NULL, 'IELTS', '7.0', ARRAY['bachelor_degree_min_180_ects', 'gmat_or_gre_or_internal_admission_test', 'admissions_interview'], 'https://www.frankfurt-school.de/en/study/master/master-in-management', '2026-08-29', 'Same TOEFL-formatting caveat as ESMT Berlin above: the official page displays a TOEFL minimum of "5.0", not the standard 0-120 iBT scale — not recorded here as a number. Admissions interview is required.'),
    ('414fa645-6a64-4d84-be9c-2ddc67ecb11f', 'cfac3f1f-5ba9-49e9-b708-f7f5010fda2a', NULL, NULL, 'IELTS', '6.0', ARRAY['above_average_bachelor_degree_in_related_field', 'min_1_year_professional_experience'], 'https://www.hs-furtwangen.de/en/programmes/business-consulting-master/apply-now/', '2026-08-29', 'Bachelor''s must be in economics, computer science, business informatics, or a related field (min. 3 years full-time study). "Above-average" grade required but no numeric GPA cutoff is published. TOEFL iBT >=76 also accepted; waived for native speakers or a degree from the UK, Ireland, USA, Canada, Australia, or New Zealand. Application window: 15 April - 15 October for the March 1 start.'),
    ('dc1cfa40-0fc7-4569-8c9d-8d23f57f065d', 'a5794141-a9cf-4bb9-9899-2c99129138be', NULL, NULL, NULL, NULL, ARRAY['bachelor_degree_or_equivalent'], 'https://www.polimi.it/en/prospective-students/how-to-apply/admission-to-laurea-programmes/requirements-to-participate-in-the-admission-test', '2026-08-29', 'No specific IELTS/TOEFL minimum or GPA cutoff found on the official pages checked. Foreign secondary-school/degree qualifications are evaluated against Ministry-set equivalence rules to determine admission-test eligibility.'),
    ('628939d8-2535-4c65-9f12-7e20ceb97185', '52f91533-1e6c-4e73-aeb1-ac7bf2080379', NULL, NULL, 'CEFR', 'B2 (2 of 3)', NULL, 'https://www.unibz.it/en/faculties/engineering/bachelor-computer-science', '2026-08-29', 'Trilingual instruction (Italian/German/English): B2 required in at least two of the three teaching languages, B1 in the third (for exams held in it). Only 4 non-EU places available in the early-bird round for this program; single application window, no late applications; post-admission visa is handled via the Universitaly portal.'),
    ('bf04d2f9-5687-421f-91de-b0d2b332e8b8', '5155dc7f-665f-4414-9acf-c3c94dbbf7f7', NULL, NULL, 'TOEFL iBT', '95', ARRAY['application_form_or_common_app', '600_word_essay', 'official_transcripts_certified_translation_if_needed', 'two_recommendation_letters', 'online_admissions_interview'], 'https://www.johncabot.edu/admissions/undergraduate/english-language-requirements', '2026-08-29', 'IELTS equivalent to CEFR C1; Cambridge CAE 180+, FCE 160-180, PET 140-160; Linguaskill C1 (180+); PTE Academic 58; Duolingo reviewed case-by-case with no fixed cutoff. SAT/ACT optional. No GPA minimum published.'),
    ('e8112376-9667-4463-8596-6e7b623faa3e', 'a8975438-e696-4a6a-8d9c-2711c80dc218', NULL, NULL, 'IELTS', '5.5', ARRAY['bachelor_degree_or_higher', 'min_60_ects_across_2_of_history_philosophy_economics_law_political_science_sociology_or_foreign_languages'], 'https://corsi.unitn.it/en/european-and-international-studies/enrollment/admission-non-europeans', '2026-08-29', 'English B2 minimum (certificates dated after March 2024): TOEFL iBT 21, Cambridge B2 First 165 also accepted; exempt if prior degree was fully English-taught. Programmed (limited) access: 10 seats for this round, application deadline 2026-03-04 12:00 CET, rankings published 2026-04-30. No exact tuition figure is published (see program_fees notes).'),
    ('09bbb79d-74b4-4f91-9d46-0aeb24bf1e59', '0782d15d-2e35-4030-956c-bb1cff48da03', NULL, NULL, NULL, NULL, NULL, 'https://www.luiss.it/en/entra-luiss/ammissione-triennali-e-ciclo-unico/studenti-extra-ue', '2026-08-29', 'LUISS''s official page states non-EU admission requirements, documents, and deadlines for the 2027/2028 cycle "will be published in the relevant notices... available from October 2026" — not yet public at time of this research pass. An unverified WebSearch snippet (likely referencing an earlier cycle) cites IELTS 5.5 / TOEFL 46 / Duolingo 90, exempt if prior study was fully English-taught, but this was not confirmed on a live official page and is not recorded as fact here.'),
    ('97669728-f8da-4534-8bbe-59d2d1af5f2b', '02c81cf1-e791-4398-8ded-66aa08d1fd1e', NULL, NULL, NULL, NULL, NULL, 'https://www.ie.edu/university/admission/access-to-university/', '2026-08-29', 'Admission is via IE''s own Admissions Test (verbal/logical/numerical reasoning), an online assessment, a personal interview, and a Final Committee decision, rather than a published IELTS/TOEFL/GPA cutoff — none of those three figures were found on the official pages checked. IE states "over 80% of our students are international... more than 140 different countries."'),
    ('720a513f-1348-4622-b7da-7af74ac67950', '9d4c58a9-0522-4164-9900-3fc2b62e7e0c', 82.50, NULL, 'IELTS', '7.0', NULL, 'https://www.esade.edu/bachelor/en/degrees/admissions/admission-requirements', '2026-08-29', 'The official page publishes the GPA cutoff as "3.3/4.0 (>=B+), unweighted", not as a percentage — the 82.50 recorded here is a derived decimal-scale conversion (3.3/4.0 = 0.825) disclosed for comparison purposes; treat the original 3.3/4.0 figure as authoritative. IELTS Academic 7 required (6.5-7 accepted with Language Department validation); TOEFL iBT 100 (90-99 with validation), Cambridge C1/C2 Advanced 190, SAT EBRW 650, ACT English 27, PTE Academic 76, Duolingo 160 also accepted.'),
    ('8a92959a-7f5d-4654-826b-d77ac504432e', 'fbcceb0d-da76-45be-ba3d-3ceb1961f5db', NULL, NULL, NULL, NULL, NULL, 'https://www.uc3m.es/bachelor-degree/admission/application/international-students', '2026-08-29', 'UC3M distinguishes a "general application" process (for countries without an admission agreement) from an "early admission process" track, but the exact IELTS/TOEFL minimum and GPA cutoff for non-EU applicants were not found — the linked sub-pages for these details returned 410 Gone during this research pass.'),
    ('20c80d2e-c9c6-4559-a0eb-6642a7a8b910', 'fd8aa591-9b63-4397-a6ab-53f61f14cb93', NULL, NULL, NULL, NULL, NULL, 'https://www.euruni.edu/en/Programs/Tuition-Fees.html', '2026-08-29', 'No official English-test minimum or GPA cutoff was found on the fetched tuition page. An unverified third-party/aggregator source cites IELTS 6.5 / TOEFL 89 / PTE 59, but this could not be confirmed against an official euruni.edu page during this research pass and is not recorded as fact here.'),
    ('9782bc38-2fa0-4f6b-8717-9b4f173711e1', '2e27a8ce-3eb5-4bb9-8f85-70beb2f273c3', NULL, NULL, NULL, NULL, ARRAY['passport_or_national_id', 'passport_photo', 'academic_transcripts_last_two_years', 'spanish_university_access_credential_via_unedasiss_or_equivalent'], 'https://iqs.edu/en/studies/bachelors-degree-international-business/', '2026-08-29', 'Non-Spanish-system applicants also sit IQS''s own online admissions test (psychometric plus an integrated English-level component) rather than an external IELTS/TOEFL minimum — no separate numeric English threshold is published. Triple-degree track available: 2 years abroad at IESEG (France) and Sheffield Hallam University (UK), yielding three European degrees; dual-degree alternatives via Kedge Business School (France) or Pforzheim University (Germany).');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('44b69cb3-f67a-4edb-99f6-1cca75028168', 'dec71aae-2e15-4d92-a150-7523badc3c2f', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 10000.00, 'https://constructor.university/programs/undergraduate-education/computer-science', '2026-08-29', 'Confirmed on both the program page and the admission-aid financing page. This is a per-semester figure (i.e. EUR 20,000/year for a full-time bachelor''s student).'),
    ('588401b4-5c8a-4131-a8bc-9e2f3ffcbf2c', '0a2dbf15-ee7e-431d-93ca-97457f04f164', 'TUITION_TOTAL', 'INTERNATIONAL', 36000.00, 'https://esmt.berlin/master-programs/scholarships-financing', '2026-08-29', 'Total tuition for the whole 2-year Master in Global Management, paid in 3 installments over 2 academic years — covers courses, materials, orientation, and career support.'),
    ('878f2367-4c2b-4d21-94b5-e2b7c1469559', '0a2dbf15-ee7e-431d-93ca-97457f04f164', 'APPLICATION_FEE', 'INTERNATIONAL', 75.00, 'https://esmt.berlin/master-programs/master-global-management/admissions', '2026-08-29', NULL),
    ('55357648-dd8e-45b0-95ed-0d9269fcc1d9', 'b22f707a-aed1-4925-957e-c37ade73dee4', 'TUITION_PER_YEAR', 'INTERNATIONAL', 38250.00, 'https://berlin.bard.edu/admissions/finances/tuition-and-fees/', '2026-08-29', 'This is the 2026-27 on-campus "Comprehensive Fee" (bundles tuition, housing, a Mon-Fri meal plan, mental-health service, and gym/sauna access), not a pure tuition figure. An off-campus alternative also exists (EUR 27,500/year: tuition plus mental-health service and gym/sauna access, no housing) — not seeded as a separate row since it is a mutually exclusive alternative for the same programme, to avoid double-counting the same real-world cost. Additional mandatory costs not included here: a semester transit ticket (EUR 453.60/semester) and a course-materials "Reader Fee" (EUR 10-90).'),
    ('8a026203-4d39-4a95-be04-5e2cfb490a75', 'dd969049-b102-4db6-b5e0-58906c4ddaf6', 'TUITION_TOTAL', 'INTERNATIONAL', 35500.00, 'https://www.frankfurt-school.de/en/study/master/master-in-management', '2026-08-29', 'Total tuition for the whole 4-semester Master in Management, 2026 cohort. Early-bird discounts of up to EUR 4,000 are available for applications submitted by 2025-11-30 (not reflected in this figure). Application deadline 2026-06-30; program starts 2026-08-24.'),
    ('2c914024-f941-47f0-ab25-d46d7cb5c3f8', 'dd969049-b102-4db6-b5e0-58906c4ddaf6', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://www.frankfurt-school.de/en/study/master/master-in-management', '2026-08-29', NULL),
    ('f88bfd14-7878-40fe-b36b-680026aed29f', 'dd969049-b102-4db6-b5e0-58906c4ddaf6', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 400.00, 'https://www.frankfurt-school.de/en/study/master/master-in-management', '2026-08-29', 'Enrolment fee, separate from tuition and the application fee.'),
    ('5ce88c98-bf6f-4006-97e2-b8f48ed73552', 'cfac3f1f-5ba9-49e9-b708-f7f5010fda2a', 'TUITION_TOTAL', 'INTERNATIONAL', 4500.00, 'https://www.hs-furtwangen.de/en/programmes/business-consulting-master/apply-now/', '2026-08-29', 'Total tuition for the complete 3-semester program — a fee-charging exception to HFU''s otherwise tuition-free public-university model (this program-specific fee replaces, rather than adds to, Baden-Wurttemberg''s general EUR 1,500/semester non-EU state tuition). Full first payment (this figure plus the first semester''s administrative fee, EUR 4,676 total) is due upon admission, before program start, with no payment plan available.'),
    ('d54fa322-9c2b-431e-ab14-c641ab1c8b21', 'cfac3f1f-5ba9-49e9-b708-f7f5010fda2a', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 176.00, 'https://www.hs-furtwangen.de/en/programmes/business-consulting-master/apply-now/', '2026-08-29', 'Standard HFU administrative/semester fee, recurring each of the program''s 3 semesters (this row records a single semester''s fee, not the multiplied 3-semester total, to avoid double-counting a recurring charge as a lump sum).'),
    ('d3e0309b-09d0-4d5c-8f25-ea80dc975a11', 'a5794141-a9cf-4bb9-9899-2c99129138be', 'TUITION_PER_YEAR', 'INTERNATIONAL', 3883.04, 'https://www.polimi.it/en/prospective-students/how-much-does-it-cost/laurea-laurea-magistrale-and-single-cycle-programmes', '2026-08-29', 'Non-EU students without a scholarship pay the top income bracket for the standard 46-74 ECTS study plan, 2026/2027: 1st instalment EUR 880.04 + 2nd instalment up to EUR 3,003.00 = EUR 3,883.04/year maximum (combined here). An informally-cited aggregator average of "~EUR 3,726/year" was not used since it is not independently confirmed on this official page.'),
    ('9ecf96aa-065a-41e5-adef-d2aa0e98d164', '52f91533-1e6c-4e73-aeb1-ac7bf2080379', 'APPLICATION_FEE', 'INTERNATIONAL', 50.00, 'https://www.unibz.it/en/faculties/engineering/bachelor-computer-science', '2026-08-29', 'Non-refundable, for non-EU applicants living abroad.'),
    ('b95a776a-37dc-48da-991a-6e1b574d073e', '52f91533-1e6c-4e73-aeb1-ac7bf2080379', 'TUITION_PER_YEAR', 'INTERNATIONAL', 1200.00, 'https://guide.unibz.it/en/study-career/general-information/fees', '2026-08-29', 'Public-university tuition rate, split into two EUR 600 instalments (1st due mid-October, 2nd due 2027-03-31). Rises to an EUR 900 first instalment from the 2nd year beyond normal program duration. A EUR 30 late-payment fine applies; students with recognized disabilities or Italian government grants pay only a EUR 16 revenue stamp instead.'),
    ('a2841fda-0835-4b04-86dc-b9943ddbbec3', '5155dc7f-665f-4414-9acf-c3c94dbbf7f7', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 11350.00, 'https://www.johncabot.edu/admissions/tuition-and-fees/fall-2026-spring-2027-eur', '2026-08-29', 'Fall 2026 & Spring 2027 rate, published directly in EUR (no currency conversion needed). Includes a EUR 320 student-activity fee bundled into the figure. Additional per-semester costs not included here: Permit to Stay EUR 180, Declaration of Presence EUR 30, an optional meal plan EUR 480, and health insurance (~USD 78/month, required for non-EU long-term-visa students).'),
    ('ff7894cb-99a9-4b76-b20f-e41428b69e8e', '5155dc7f-665f-4414-9acf-c3c94dbbf7f7', 'APPLICATION_FEE', 'INTERNATIONAL', 50.00, 'https://www.johncabot.edu/admissions/undergraduate/', '2026-08-29', 'Listed on the official page as "$50/EUR 50".'),
    ('e6f5ae1e-88a1-449f-8544-42896127a841', 'a8975438-e696-4a6a-8d9c-2711c80dc218', 'APPLICATION_FEE', 'INTERNATIONAL', 30.00, 'https://corsi.unitn.it/en/european-and-international-studies/enrollment/admission-non-europeans', '2026-08-29', 'No TUITION_* fee row is seeded for this program: the official page states tuition "is based on the admission score you get" without listing an amount, and a WebSearch-only aggregator figure (EUR 8,000-15,000/year) could not be independently verified — omitted rather than guessed.'),
    ('452ea786-7ad6-4fd2-8f6a-fb1b0df62542', 'a8975438-e696-4a6a-8d9c-2711c80dc218', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 100.00, 'https://corsi.unitn.it/en/european-and-international-studies/enrollment/admission-non-europeans', '2026-08-29', 'Confirmation fee, paid separately from the EUR 30 application fee above.'),
    ('d1e0d381-78af-422b-b6cf-1d5a7c6ba274', '0782d15d-2e35-4030-956c-bb1cff48da03', 'TUITION_PER_YEAR', 'INTERNATIONAL', 15000.00, 'https://www.luiss.it/en/ammissione/offerta-formativa/laurea-triennale/economics-and-business', '2026-08-29', 'This is the 2027/2028 academic-year figure stated on the current official program page (3 installments + regional tax). Two other figures were found and are disclosed rather than discarded: a WebSearch-snippet-only ~EUR 14,000/year attributed to the 2026/2027 cycle (not independently fetched from a live page), and EUR 12,000/year (3 installments of EUR 4,000 each) fetched directly from api.luiss.it but explicitly labeled "2024/2025 Academic Year" with a payment due date already in the past — that page appears stale relative to luiss.it. These three figures span three different academic years and are not necessarily contradictory (a rising fee schedule), but were not reconciled into one number; the most current, directly-fetched, program-specific figure is used here.'),
    ('19232d5d-a722-4af2-a319-35cae80617d7', '02c81cf1-e791-4398-8ded-66aa08d1fd1e', 'TUITION_PER_YEAR', 'INTERNATIONAL', 26500.00, 'https://www.ie.edu/university/studies/academic-programs/bachelor-international-relations/admissions-fees/', '2026-08-29', 'First-year (2026-2027) rate. The same official page states a 2027-2028 rate of EUR 27,300/year — not seeded as a separate row since it is the same programme''s year-2 rate, not an additional cost.'),
    ('5e1e315f-c638-4921-8eec-d35b02723237', '9d4c58a9-0522-4164-9900-3fc2b62e7e0c', 'TUITION_PER_YEAR', 'INTERNATIONAL', 21300.00, 'https://www.esade.edu/bachelor/en/degrees/tuition-fees', '2026-08-29', 'First-year rate for the BBA and several other ESADE bachelor''s degrees sharing the same figure. Double-degree tracks are priced higher (EUR 24,500) but are a distinct programme, not seeded here. Payment structure: 25% deposit to reserve a place, 75% due later.'),
    ('86d5c950-84dd-4681-93c3-e105567770b0', 'fbcceb0d-da76-45be-ba3d-3ceb1961f5db', 'TUITION_PER_YEAR', 'INTERNATIONAL', 6822.60, 'https://www.uc3m.es/bachelor-degree/admission/application/enrollment/prices/non-eu', '2026-08-29', 'Calculated figure: UC3M''s non-EU 2026/27 per-credit rate for this degree''s fee band ("Type 3": Social Sciences/Humanities) is EUR 113.71/credit, multiplied by a standard 60-credit academic year = EUR 6,822.60. Other fee bands range up to EUR 136.44/credit (Type 1, e.g. Biomedical/Neuroscience) — not applicable to this degree. An administrative fee, school insurance, and a new-student file-opening fee are stated as additional on the official page but not quantified there, so they are not included in this figure.'),
    ('2c594eb2-ead1-427c-b13c-f3c1af22cec6', 'fd8aa591-9b63-4397-a6ab-53f61f14cb93', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 7350.00, 'https://www.euruni.edu/en/Programs/Tuition-Fees.html', '2026-08-29', '2026-2027 rate for the 7-semester/3-year Barcelona-campus BBA.'),
    ('39ca1b2d-37ab-4f1a-bdb0-80e70ff523e5', 'fd8aa591-9b63-4397-a6ab-53f61f14cb93', 'APPLICATION_FEE', 'INTERNATIONAL', 200.00, 'https://www.euruni.edu/en/Programs/Tuition-Fees.html', '2026-08-29', 'Non-refundable.'),
    ('b8733d0e-ace2-49f4-bf5e-d038e98d802e', 'fd8aa591-9b63-4397-a6ab-53f61f14cb93', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 630.00, 'https://www.euruni.edu/en/Programs/Tuition-Fees.html', '2026-08-29', 'Dissertation/capstone fee, due on completion rather than at enrollment.'),
    ('e27110cc-ae64-4072-8f36-5b2064927e56', '2e27a8ce-3eb5-4bb9-8f85-70beb2f273c3', 'APPLICATION_FEE', 'INTERNATIONAL', 125.00, 'https://iqs.edu/en/studies/bachelors-degree-international-business/', '2026-08-29', 'Pre-registration fee, non-refundable except if the applicant is not admitted.'),
    ('cd5bf5c3-3d6b-4bab-997b-10e4f8263b49', '2e27a8ce-3eb5-4bb9-8f85-70beb2f273c3', 'TUITION_PER_YEAR', 'INTERNATIONAL', 14160.00, 'https://iqs.edu/en/bachelors-degrees-admissions/admissions-process/', '2026-08-29', '2026-2027 rate: EUR 236/credit x 60 credits/year (recognized transfer credit is discounted to EUR 165.20/credit). A separate EUR 3,000 pre-enrolment deposit specific to this degree is also required, but is credited toward this tuition figure rather than an additional cost, so it is not seeded as a separate row.');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('89b8b9ff-3962-4328-ac9f-ec2b1536633d', 'Academic Achievement Scholarship', 'Constructor University Bremen', 'DE', '21ebda6f-d0d2-4797-84f8-c8208b3ecc8e', 'dec71aae-2e15-4d92-a150-7523badc3c2f', 'PARTIAL_TUITION', 10000.00, 'Automatic merit-based scholarship for admitted undergraduate applicants, based on school-leaving GPA; no separate application required. Awarded "up to EUR 10,000" — the exact amount scales with the applicant''s academic record, so this figure is the stated maximum, not a guaranteed amount for every recipient.', NULL, NULL, 'https://constructor.university/admission-aid/financing-undergraduate', '2026-08-29'),
    ('acffa222-f546-4521-8431-d26473b6636e', 'BMW Group Change Maker Fellowship', 'ESMT Berlin, with BMW Group', 'DE', 'cead504b-fecf-4260-866d-a2e325bef2bd', '0a2dbf15-ee7e-431d-93ca-97457f04f164', 'PARTIAL_TUITION', 17500.00, 'One of several named scholarships toward ESMT''s Master in Global Management (total tuition EUR 36,000). Specific eligibility criteria for this particular award were not itemized beyond its name and amount on the fetched financing page.', NULL, NULL, 'https://esmt.berlin/master-programs/scholarships-financing', '2026-08-29'),
    ('89bb787a-74d9-44ba-9aee-d8e6899e8f74', 'PIESC Scholarship (Program for International Education and Social Change)', 'Bard College Berlin', 'DE', '32fb52c3-dcef-401d-82fd-2d0f1d4eead0', 'b22f707a-aed1-4925-957e-c37ade73dee4', 'FULL_FUNDING', 38250.00, 'For students from crisis regions. Covers "up to the full on-campus comprehensive fee plus additional living-expense support" — amount_eur here is the stated on-campus Comprehensive Fee maximum (which itself bundles tuition, housing, and meals), not a separate cash award on top of it.', NULL, NULL, 'https://berlin.bard.edu/admissions/finances/scholarships/', '2026-08-29'),
    ('23682154-e8f9-493d-902e-dee679f01832', 'Master''s Degree Scholarships for International Students (English-taught programmes)', 'Politecnico di Milano', 'IT', '3fe37168-bbea-4b9a-924a-48d6df9b47fa', 'a5794141-a9cf-4bb9-9899-2c99129138be', 'FULL_FUNDING', 10000.00, 'Awarded via the Early Bird admissions window (2025-10-01 to 2025-12-01 for the confirmed cycle). Combines a full tuition-fee waiver (regular non-EU tuition is otherwise up to ~EUR 3,883.04/year, see program_fees) plus a non-refundable EUR 170 admin fee, plus a gross living allowance described as "up to EUR 10,000/year" — amount_eur here reflects only the disclosed living-allowance figure, not the combined value of the tuition waiver plus allowance.', NULL, NULL, 'https://www.polimi.it/en/prospective-students/how-much-does-it-cost/scholarships', '2026-08-29');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('76c5a0a9-9060-4d4c-bf1d-e5491fb3c5ac', '21ebda6f-d0d2-4797-84f8-c8208b3ecc8e', 'UNIVERSITY_DORM', 'Constructor University Residential Colleges (Krupp / Mercator / College III / College Nordmetall)', 'Bremen', 444.44, NULL, NULL, ARRAY['furnished', 'shared_apartment'], NULL, NULL, 'https://constructor.university/programs/undergraduate-education/computer-science', '2026-08-29', 'Original stated figure: EUR 4,000 for the September-May period (shared room), a 9-month academic-year span, divided here into an average monthly rent of EUR 444.44. On-campus housing is organized into four residential colleges; distance_to_university_km left NULL since it is on-campus. Confirm current-year pricing and room-type options directly with Constructor University Student Life before relying on this figure.');


-- =====================================================================
-- USA / UK depth batch (added 2026-08-30)
-- 5 new US universities (Fort Hays State, Alcorn State, Berklee College
-- of Music, Agnes Scott College, Missouri Southern State) + 5 new UK
-- institutions (Leeds Trinity, Arts University Bournemouth, Regent's
-- University London, Trinity Laban Conservatoire, University of Dundee),
-- deliberately including small/niche institutions per user request,
-- alongside a mix with 1-2 more recognizable names (Berklee, Dundee).
--
-- Research method: two parallel subagents, each required to fetch only
-- the institution's own official domain (never ranking-aggregator
-- sites) and to quote exact figures/wording, flagging every ambiguity
-- rather than guessing. Checked 2026-08-30 throughout.
--
-- FX: all USD/GBP figures converted to EUR using the ECB reference rate
-- for 2026-08-28 (the latest published business-day rate at the time of
-- this batch): 1 EUR = 1.1643 USD, 1 EUR = 0.8572 GBP. Original
-- figure + conversion basis is disclosed in each row's notes, matching
-- the project's established FX-disclosure convention.
--
-- Deliberate omissions (per "when unconfirmed, omit rather than guess"):
--   * No new visa_requirements row for the US. The SEVIS I-901 fee and
--     the current MRV/Visa-Integrity-Fee figures could not be confirmed
--     via a direct fetch of an official source (travel.state.gov and
--     ice.gov/fmjfee.com all returned HTTP 403 to automated fetches);
--     only third-party aggregator figures were found, which this
--     project's rules exclude as a source. Left for a future batch once
--     an official figure can be directly fetched/quoted.
--   * Alcorn State's "Hazel Ann Brown Memorial Endowed Scholarship" was
--     found only on a School of Nursing scholarships page (unclear if
--     nursing-specific or university-wide) with no published amount —
--     not seeded.
--   * Agnes Scott's "$100K+ Promise" (international eligibility not
--     explicitly stated) and "Marvin B. Perry Presidential Scholarship"
--     (terms not independently confirmed via a direct official quote,
--     only third-party summaries) — neither seeded.
--   * Agnes Scott's international application fee: the official page
--     states a fee is mandatory for all international applicants but
--     never publishes the dollar figure (a commonly cited $30 appears
--     only in third-party summaries) — no APPLICATION_FEE row seeded.
--   * Accommodation rows are seeded ONLY where the official source gives
--     a monthly figure directly, or a weekly/annual figure whose
--     underlying period is unambiguous enough to convert without
--     guessing (a stated "9-month" academic year, or a stated weekly
--     rate converted via the standard 52/12 weeks-per-month factor).
--     Skipped entirely for Alcorn, Berklee, Agnes Scott, MSSU, and
--     Regent's University London, where the official page only gives a
--     "per semester"/"per term" figure without stating that period's
--     exact length in months — dividing by an assumed month-count would
--     be guessing, which this project's rules forbid. (Regent's Reid
--     Hall figures additionally conflict on which academic year they
--     apply to, per the source page itself.)
--   * Regent's University London's live site (regents.ac.uk) returns
--     HTTP 403 to automated fetches (Cloudflare bot-challenge). Its
--     facts below were sourced via Wayback Machine archives of the
--     exact same official pages instead (archive URLs given per row) —
--     still the institution's own text, just accessed via archive.org.
--   * University of Dundee's "International Relations and Politics MA
--     (Hons)" is seeded with degree_level = BACHELOR, not MASTER: in the
--     Scottish system, "MA (Hons)" denotes an undergraduate honours
--     degree, not a taught postgraduate master's — a naming trap flagged
--     explicitly by the research pass.
--   * Existing US universities (UTA, Toledo, Wichita State) and existing
--     GB university (Manchester) were checked beforehand — no overlap
--     with the 10 new names below.
-- =====================================================================

