    ('db30396b-be82-49e9-ac50-792342ed15e1', '06ddf9f2-2dbf-4669-8d97-15c6b9ea2512', 'Bachelor of Music', 'BACHELOR', 'Music', NULL, 'https://college.berklee.edu/admissions/undergraduate/international'),
