    ('4287ff56-fef4-487d-a25c-dd5f88b4a21a', '7a17bb5a-c054-4913-b729-b96b764644a6', 'BSBA General Business', 'BACHELOR', 'Business Administration', 48, 'https://www.mssu.edu/academics/business/business-admin/degree-general-business.php'),
    ('f34f4fcd-28cc-4ecb-8f6b-d9f156f99b36', '3fec40cf-1efd-470c-8c30-a7a2bf80cc74', 'BA (Hons) Business Management', 'BACHELOR', 'Business Management', 36, 'https://www.leedstrinity.ac.uk/courses/undergraduate/business-management/'),
    ('da6fdb5b-348a-48c6-b931-01b7d65e3b0c', 'e66717ce-2eae-4b4c-b8e1-d0671ab7723c', 'BA (Hons) Fashion', 'BACHELOR', 'Fashion Design and Production', 36, 'https://aub.ac.uk/ba-hons-fashion'),
    ('0a13f406-f475-49e5-879f-67dc41518610', '0ae62c03-4aee-4e31-91c1-e97ad51f54ec', 'MSc Psychology (Conversion)', 'MASTER', 'Psychology', 12, 'https://www.regents.ac.uk/postgraduate/psychotherapy-psychology/msc-psychology'),
    ('c3fc13c7-b0c0-450a-a605-ce9c122a167f', 'e036c8b3-054b-410e-82d0-403e57e95483', 'BA (Hons) Musical Theatre Performance', 'BACHELOR', 'Musical Theatre / Performing Arts', 36, 'https://www.trinitylaban.ac.uk/courses/ba-hons-musical-theatre-performance/'),
    ('d2c6259a-0912-4a23-b7df-0819b63184f0', '995da90e-9ba4-45b4-bc03-04e73298f1ec', 'International Relations and Politics MA (Hons)', 'BACHELOR', 'International Relations and Politics', 48, 'https://www.dundee.ac.uk/undergraduate/international-relations-politics');

INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('510f27a3-17dc-4ac8-8a94-dfdcf14d9201', '333330ea-ed9b-400b-84ef-c135aa3e9fb2', 62.50, NULL, 'IELTS', '6.0', ARRAY['undergraduate application', '$50 application fee', 'passport ID page or government ID copy', 'official transcripts (English translation)', 'proof of HS graduation', 'language proficiency documentation', 'immigration status verification if in US', 'health insurance waiver request'], 'http://www.fhsu.edu/international/international-admissions/Admission-Requirements', '2026-08-30', 'minimum_cgpa_percentage is a derived decimal-scale conversion of the official published cutoff "2.5 on a 4.0 scale," not an officially published percentage. FHSU''s own pages disagree on the TOEFL iBT minimum (70 on one page vs 78 on another) -- not seeded as a number pending re-verification; Duolingo 95 / iTEP 3.8 / graduate IELTS 6.5-Duolingo 110 also published. "Institutional TOEFL Scores will not be accepted." All materials must be mailed to the Registrar''s Office -- email/fax not accepted. Deadlines: Fall June 1, Spring Oct 15, Summer Apr 1.'),
    ('a048640d-2ef2-47f9-898a-974f7317684c', 'c03159cc-0df4-4725-bb6e-983c1d3b04f7', NULL, NULL, 'TOEFL iBT', '71', ARRAY['ACT (18+ composite) or SAT equivalent', 'NACES course-by-course transcript evaluation', 'proof of financial support (submitted after online application)'], 'https://www.alcorn.edu/admissions/international-admission/', '2026-08-30', 'No minimum GPA is stated on Alcorn''s official international-admission page -- left unconfirmed rather than guessed. Same source also expresses the TOEFL minimum as "525 Paper-based / 195 Computer-based." English requirement waived if English is the applicant''s country''s official language. Deadlines: Fall Apr 15, Spring Nov 15. Application fee $60.'),
    ('f2fd5bce-4fae-411d-afe6-da470ceefb99', 'db30396b-be82-49e9-ac50-792342ed15e1', NULL, NULL, 'IELTS', '6.0', ARRAY['credential evaluation report (course-by-course, non-US/Canada applicants)', 'official HS/college transcripts in English', 'I-20/F-1 visa documentation'], 'https://college.berklee.edu/admissions/undergraduate/international', '2026-08-30', 'Berklee admits by audition/portfolio, not GPA -- "does not require essays, personal statements, or standardized test (e.g., SAT/ACT) scores"; self-reported GPA is optional, not a cutoff. IELTS 6.0 shown here is for the Bachelor of Music / BA Black Music and Culture track specifically (BA Music Industry Leadership and Innovation requires IELTS 7.0 instead). TOEFL is published on two different scales (72 before 2026-01-21 vs "4" after) -- ambiguous, not seeded as a number; Duolingo 110 / PTE Academic 48 also published. Application fee $150 (50% off if applying by Nov 1 for summer/fall).'),
    ('a7452c20-147f-4816-ae25-4f7f3359378f', '9d443ffa-8955-48cf-80f4-e57c41fce0f4', NULL, NULL, 'TOEFL iBT', '80', ARRAY['Common Application + supplemental documents', 'official transcripts in sealed envelopes', 'notarized translations if not in English', 'proof of financial support less than 6 months old', 'current visa status documentation if applicable'], 'https://www.agnesscott.edu/admission/undergraduate-admission/international-students/application-requirements.html', '2026-08-30', 'No minimum GPA is published -- the official page only states the *average* GPA of recently admitted students (3.63), which is descriptive, not a requirement. IELTS 6.5 / Duolingo 110 / Cambridge CAE 176 / SAT Verbal or ACT English 520/20 also accepted; waived for applicants from English-speaking countries or 3+ years at a US high school. An international application fee is stated as mandatory ("required of all international applicants and cannot be waived") but its dollar amount is never published on any official page fetched -- a commonly cited $30 figure appears only in third-party search summaries and was NOT seeded. Agnes Scott does not offer need-based aid to international students. Deadlines: ED Nov 1, EA I Nov 15, EA II (scholarship priority) Jan 15, RD Mar 15.'),
    ('2eae44a9-a3f0-4e10-bb4e-eafee720e991', '4287ff56-fef4-487d-a25c-dd5f88b4a21a', 56.25, NULL, 'TOEFL iBT', '68', ARRAY['online International Student Application', 'scanned passport photo page', 'HS transcripts translated to English', 'English proficiency test scores', 'financial verification for one academic year', 'health center screening before enrollment'], 'https://www.mssu.edu/admissions/international-admissions.php', '2026-08-30', 'minimum_cgpa_percentage is a derived decimal-scale conversion of the official published cutoff "2.25" on a 4.0 scale, not an officially published percentage; the same page offers an alternative path of "top 50% of high school class." IELTS 6.0 / Duolingo 95 also accepted. Students below the language minimum may enter MSSU''s Intensive English Program. Application fee $60, non-refundable. Deadlines: Spring Nov 1, Summer Apr 1, Fall June 1.'),
    ('a7dc59a7-e5de-4fa5-8e27-df31dfe87587', 'f34f4fcd-28cc-4ecb-8f6b-d9f156f99b36', NULL, NULL, 'IELTS', '6.0 (5.5 min)', ARRAY['degree/transcripts', 'proof of English language', 'references', 'statement of purpose', 'passport copy', 'copies of any previous visas/refusals'], 'https://www.leedstrinity.ac.uk/international/how-to-apply/english-language-requirements/', '2026-08-30', 'UCAS points, not a percentage scale -- minimum_cgpa_percentage left NULL rather than force-converted. Representative programme (Business Management BA) requires 112 UCAS Tariff points plus GCSE-equivalent English/Maths at grade C/4. The required-documents list here is transcribed from Leeds Trinity''s postgraduate how-to-apply page, since the undergraduate page did not itemize one -- flagged, may not be undergraduate-exact. TOEFL iBT overall 4 (min 4/component, from 21 Jan 2026) and Cambridge C1 Advanced 169 (min 162/component) also accepted; elevated to IELTS 7.0 for Nursing/Biomedical Science. Country-specific entry-grade tables exist on the site but exact figures were not extractable via automated fetch. Application deadline for representative programme: 30 June 2026 (Sept 2026 entry).'),
    ('42045080-430d-4028-b9e2-133a60507aa2', 'da6fdb5b-348a-48c6-b931-01b7d65e3b0c', NULL, NULL, NULL, NULL, ARRAY['personal statement', 'reference', 'portfolio or audition where appropriate', 'application form', 'academic transcripts'], 'https://aub.ac.uk/apply/undergraduate', '2026-08-30', 'No degree-level IELTS/TOEFL minimum could be confirmed via direct fetch of AUB''s dedicated English-language-requirements page -- only pre-sessional course bands were found (undergraduate pre-sessional entry IELTS 4.5-5.5, exit 6.0; postgraduate pre-sessional entry IELTS 5.0-6.0, exit 6.5), so no direct-entry score is seeded here pending re-verification. AUB''s own pages state its UCAS Tariff entry figure inconsistently across fetches (104-120 vs 112-120) -- also not seeded pending re-verification. Country-specific examples confirmed directly on the apply page: Australia ATAR 85+, China 70%+ (or CAFA Foundation Year 70%+), India 65%+ in Standard 12, Singapore A-level BBB+ or recognized polytechnic diploma. UCAS Equal Consideration deadline 14 January 2026 for Sept 2026 entry; portfolio required within 30 days of request.'),
    ('49ab53fa-3aa5-4131-be24-438137f1e368', '0a13f406-f475-49e5-879f-67dc41518610', NULL, NULL, 'IELTS', '6.5 (5.5 min)', ARRAY['passport photo-ID page copy', 'academic transcripts/certificates', '500-700 word personal statement', 'proof of English proficiency if not a native speaker'], 'http://web.archive.org/web/20250912011936/https://www.regents.ac.uk/postgraduate/psychotherapy-psychology/msc-psychology', '2026-08-30', 'Sourced via Wayback Machine archive (capture 2025-09-12) of Regent''s own official programme page, since the live regents.ac.uk site returns HTTP 403 to automated fetches (Cloudflare bot-challenge) -- content is the institution''s own text, just accessed via archive.org. Academic requirement is quoted verbatim as "Minimum second class UK undergraduate degree" OR "Equivalent international qualifications, as deemed acceptable by Admissions & UK ENIC" -- no percentage figure to convert, so minimum_cgpa_percentage is left NULL. GCSE English grade C(4), IB SL/HL English, and a UG degree from a UKVI-defined English-speaking country are also accepted alternatives. Quoted directly: "there''s no application fee" and "we do not accept home/online editions of English language tests." Rolling admissions, no fixed deadline stated. A general (non-programme-specific) UG entry-requirements page citing "56 UCAS points" was found only via search snippet, not a direct fetch or archive -- not seeded.'),
    ('2a94b98c-edfc-437b-b4a7-94a47b64653f', 'c3fc13c7-b0c0-450a-a605-ce9c122a167f', NULL, NULL, 'IELTS', '5.5 (all 4)', ARRAY['proof of identity', 'documentary evidence of qualifications', 'certified translations if not in English'], 'https://www.trinitylaban.ac.uk/english-language-requirements/', '2026-08-30', 'Academic requirement is two A-level passes (Performing Arts subject preferred) or BTEC/NVQ equivalent with relevant prior experience; minimum age 17 by registration -- not a GPA/percentage scale, so minimum_cgpa_percentage is left NULL. TOEFL iBT overall 4 (minimum 4 in all four skills) and PTE Academic overall 59 (minimum 59/component) also accepted at undergraduate level. Confirmed absence of an international scholarship for this institution (see scholarships table note). On-time deadline 14 January 2026; recorded-audition deadline 23 January 2026, 18:00 GMT (via UCAS Conservatoires).'),
    ('a0d93605-8373-4e0f-a951-b66ac570f54f', 'd2c6259a-0912-4a23-b7df-0819b63184f0', NULL, NULL, 'IELTS', '6.0 (5.5 min)', ARRAY['passport copy', 'academic transcripts and certificates', 'English-language certificates', 'UCAS personal statement'], 'https://www.dundee.ac.uk/undergraduate/international-relations-politics/entry-requirements', '2026-08-30', 'This programme''s formal title uses the Scottish "MA (Hons)" designation, which denotes an UNDERGRADUATE honours degree in the Scottish system (not a taught postgraduate master''s) -- seeded here with degree_level = BACHELOR accordingly, to avoid the common naming trap. Scottish Higher/Advanced Higher requirement quoted verbatim as "CCCC" (both Standard and Widening Access routes); the page''s A-level/IB figures sit behind a country-selector dropdown that could not be expanded via automated fetch -- not seeded pending direct browser verification. TOEFL iBT 60 (also LanguageCert/PTE/Trinity ISE at the same minimum) also accepted; IELTS Writing must be 6.0, other components minimum 5.5. No Dundee-specific application fee could be confirmed on an official page -- third-party figures of £22-28.50 found elsewhere are generic UCAS platform fees, not a Dundee charge, and were excluded.');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('ad338440-adda-4db1-bb20-1c1280cb5203', '333330ea-ed9b-400b-84ef-c135aa3e9fb2', 'APPLICATION_FEE', 'INTERNATIONAL', 42.94, 'https://www.fhsu.edu/international/admissions/financial/tuition/estimated-educational-expenses.pdf', '2026-08-30', 'Original figure: USD 50, non-refundable, converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28).'),
    ('8de4eb59-098a-41c8-96f7-e7c8ba46dde4', '333330ea-ed9b-400b-84ef-c135aa3e9fb2', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 6333.11, 'https://www.fhsu.edu/sfs/students_parents/fy26-tuition-and-fees.pdf', '2026-08-30', 'Calculated from FHSU''s official Fall 2025-Summer 2026 Non-Resident rate of USD 614.47/credit hour (the rate international students pay -- the same schedule states "An international student is a Non-Resident student for tuition calculation purposes") x a standard 12-credit semester = USD 7,373.64, converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28). A separate FHSU international-estimate PDF projects USD 651/credit for 2026-27 (USD 7,812/semester), explicitly marked as an estimate "to be determined 7/1/2026" -- disclosed here, not seeded as a second row to avoid double-counting the same tuition charge. Mandatory health insurance (USD 3,000/year), a USD 150 orientation/registration fee, and a USD 40 housing application fee also apply and are not included in this figure.'),
    ('801ed4b4-5b5c-4019-900d-5f3a7a6afff1', 'c03159cc-0df4-4725-bb6e-983c1d3b04f7', 'APPLICATION_FEE', 'INTERNATIONAL', 51.53, 'https://www.alcorn.edu/admissions/international-admission/', '2026-08-30', 'Original figure: USD 60, converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28).'),
    ('fbd6d36d-4256-4e2e-9392-b8cfc6a90960', 'c03159cc-0df4-4725-bb6e-983c1d3b04f7', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 3480.63, 'https://www.alcorn.edu/wp-content/uploads/2026/02/25-26-Tuition-Sheet-Signed.pdf', '2026-08-30', 'Original figure: USD 4,052.50/semester at 12 credit hours full-time (Alcorn''s official 2025-2026 Tuition Sheet bills "RESIDENT & NON-RESIDENT" undergraduates at the same combined rate -- it does not differentiate by residency), converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28).'),
    ('ec5d1398-536e-415c-aa89-d0896c380960', 'c03159cc-0df4-4725-bb6e-983c1d3b04f7', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 515.33, 'https://www.alcorn.edu/wp-content/uploads/2026/02/25-26-Tuition-Sheet-Signed.pdf', '2026-08-30', 'Original figure: USD 600/semester "International Fee," a mandatory charge specific to international students on Alcorn''s official Tuition Sheet, converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28). Other mandatory fees on the same sheet (Orientation USD 100, Capital Improvement USD 50/semester, Technology USD 20/hour, Student Activity USD 50/semester) apply to all students, not just international ones, and are not seeded here.'),
    ('2ed364c1-325f-4384-ad09-fd31f37a7fb6', 'db30396b-be82-49e9-ac50-792342ed15e1', 'APPLICATION_FEE', 'INTERNATIONAL', 128.83, 'https://college.berklee.edu/admissions/undergraduate/how-to-apply', '2026-08-30', 'Original figure: USD 150 (50% off if applying for summer/fall entry by November 1), converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28).'),
    ('91f9bae7-b22b-4ea0-995c-b833543e2666', 'db30396b-be82-49e9-ac50-792342ed15e1', 'TUITION_PER_YEAR', 'INTERNATIONAL', 46396.98, 'https://www.berklee.edu/student-accounts/tuition-and-related-costs', '2026-08-30', 'Original figure: USD 27,010 (Fall 2026) + USD 27,010 (Spring 2027) = USD 54,020/year, converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28). The official page does not publish a separate international-student tuition rate -- this appears to be the same rate charged to domestic students. Excludes the USD 800/semester mandatory comprehensive fee and USD 2,781/year mandatory health insurance.'),
    ('426136d2-2173-40f5-8d26-9c43305b09b5', '9d443ffa-8955-48cf-80f4-e57c41fce0f4', 'TUITION_PER_YEAR', 'INTERNATIONAL', 45740.79, 'https://www.agnesscott.edu/admission/undergraduate-admission/cost-of-attendance.html', '2026-08-30', 'Original figure: USD 53,256/year (2026-2027 international-student tuition, distinct from the school''s domestic figure), converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28). Excludes the USD 350 Student Activity Fee (billed the same to all students).'),
    ('1ac2e082-2b16-4336-b8cc-6a1ca7729c62', '9d443ffa-8955-48cf-80f4-e57c41fce0f4', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 472.39, 'https://www.agnesscott.edu/admission/undergraduate-admission/cost-of-attendance.html', '2026-08-30', 'Original figure: USD 550 international-student Orientation Fee (higher than the USD 250 fee charged to domestic students on the same official cost-of-attendance page), converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28).'),
    ('df041909-b9e7-4f91-b311-548b09275446', '4287ff56-fef4-487d-a25c-dd5f88b4a21a', 'APPLICATION_FEE', 'INTERNATIONAL', 51.53, 'https://www.mssu.edu/admissions/international-admissions.php', '2026-08-30', 'Original figure: USD 60, non-refundable, converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28).'),
    ('e52222ee-aaee-442f-8418-8fcfc595c0db', '4287ff56-fef4-487d-a25c-dd5f88b4a21a', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 8464.31, 'https://www.mssu.edu/student-affairs/bursar/undergrad-out-of-state-cost-on-campus.php', '2026-08-30', 'Calculated from MSSU''s official 2026-27 out-of-state on-campus rate of USD 627.00/credit hour plus a USD 30.00/credit hour "Lion Fee" (USD 657/credit combined) x a 15-credit semester = USD 9,855, converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28). This official page does not explicitly state that international students are billed at the "out-of-state" rate -- flagged as the best available official figure, not independently confirmed as international-specific with an exact quote. A separate, unverified aggregate estimate of USD 16,052/year for international undergraduates also exists but was not independently confirmed and is not used here.'),
    ('da8f250c-2daa-4d41-adcf-8fb5892b03ac', 'f34f4fcd-28cc-4ecb-8f6b-d9f156f99b36', 'TUITION_PER_YEAR', 'INTERNATIONAL', 13999.07, 'https://www.leedstrinity.ac.uk/international/international-fees-and-funding/tuition-fees/', '2026-08-30', 'Original figure: GBP 12,000/year (2026-27 international rate for standard undergraduate courses excluding Nursing), converted at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28). Nursing programmes are GBP 14,500/year and a placement year is GBP 3,000, both at this same institution but not seeded here since they don''t apply to the representative programme.'),
    ('a4cd1949-8d04-477f-8091-18316c876b85', 'da6fdb5b-348a-48c6-b931-01b7d65e3b0c', 'TUITION_PER_YEAR', 'INTERNATIONAL', 23273.45, 'https://aub.ac.uk/fees/undergraduate', '2026-08-30', 'Original figure: GBP 19,950/year (2026/27 rate, applies including the Integrated Foundation Year), converted at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28). An optional placement year costs an additional GBP 1,850, not included here. No application fee was found on AUB''s apply or fees pages.'),
    ('db825762-4978-433f-9db5-ff9813ca0a56', '0a13f406-f475-49e5-879f-67dc41518610', 'TUITION_TOTAL', 'INTERNATIONAL', 33539.43, 'http://web.archive.org/web/20260220062938/https://www.regents.ac.uk/admissions/tuition-fees', '2026-08-30', 'Original figure: GBP 28,750, the fixed total programme fee for the September 2026 intake of this 12-month MSc (Regent''s own page states "Your tuition fee will be fixed for the duration of your course" and "All students pay the same tuition fees, regardless of nationality"), converted at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28). The January 2026 intake of the same programme is GBP 27,000 over a 16-month duration instead -- not seeded as a second row since it is a mutually exclusive alternative entry point for the same programme, not an additional charge. Sourced via Wayback Machine archive (capture 2026-02-20) since the live regents.ac.uk site returns HTTP 403 to automated fetches. A non-refundable advance deposit of GBP 5,000 (Sept 2026/Jan 2027 intakes) also applies and is credited toward this total, not an additional charge.'),
    ('40620d12-6506-4374-8a72-91ddc04a9f62', 'c3fc13c7-b0c0-450a-a605-ce9c122a167f', 'APPLICATION_FEE', 'INTERNATIONAL', 58.33, 'https://www.trinitylaban.ac.uk/courses/ba-hons-musical-theatre-performance/', '2026-08-30', 'Original figure: GBP 50 audition fee, converted at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28). A further GBP 28.95 UCAS Conservatoires administration fee also applies but is charged by UCAS Conservatoires itself, not Trinity Laban, so it is not included here.'),
    ('93f78260-e42e-4381-86e2-4c559054d78c', 'c3fc13c7-b0c0-450a-a605-ce9c122a167f', 'TUITION_PER_YEAR', 'INTERNATIONAL', 31614.56, 'https://www.trinitylaban.ac.uk/courses/ba-hons-musical-theatre-performance/', '2026-08-30', 'Original figure: GBP 27,100 (2026-27 international rate; GBP 26,060 for 2025-26), converted at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28).'),
    ('f5058d12-68d3-4283-9ad6-a35fab967ae9', 'd2c6259a-0912-4a23-b7df-0819b63184f0', 'TUITION_PER_YEAR', 'INTERNATIONAL', 27006.53, 'https://www.dundee.ac.uk/undergraduate/international-relations-politics/fees-and-funding', '2026-08-30', 'Original figure: GBP 23,150/year, converted at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28). A GBP 5,000 international-applicant deposit also applies (creditable toward tuition, balance payable over 7 interest-free monthly instalments). Dundee''s own fee-increase policy is quoted verbatim: increases are capped at "either... a 5% increase on the previous year''s tuition fee... [or] an increase in accordance with the Consumer Prices Index," whichever is higher.');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('12d83a77-577f-489f-a254-ab8e3c24c8d5', 'World Ready International Scholarship', 'Fort Hays State University', 'US', '7f8ad90e-be90-4290-8379-be14a583bebd', NULL, 'PARTIAL_TUITION', NULL, 'Quoted verbatim: "No application required. Eligible students will automatically be awarded"; renewable if eligibility is maintained. Amount is not published as a fixed figure ("varies") -- left NULL rather than guessed. FHSU also separately lists the Stouffer Scholarship, the Solko & Olliff Family International Student Scholarship (both application-based, amount varies, not renewable), and the OAS Rowe Fund (restricted to Latin America/Caribbean F/J visa holders) -- not seeded here as they are narrower or differently structured.', NULL, 'https://www.fhsu.edu/international/admissions/financial/scholarships/', 'https://www.fhsu.edu/international/admissions/financial/scholarships/', '2026-08-30'),
    ('f250e3ca-d477-48ec-a05e-f1fce02c0cb2', 'MOSO International Achievement Scholarship (MIAS)', 'Missouri Southern State University', 'US', '7a17bb5a-c054-4913-b729-b96b764644a6', '4287ff56-fef4-487d-a25c-dd5f88b4a21a', 'PARTIAL_TUITION', 4723.87, 'Original figure: USD 5,500 (first year, based on 24 credit hours), converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28). Freshman eligibility: TOEFL 68 / IELTS 6.0 / Duolingo 95, plus "must have a 2.75 high school GPA" (or 3.00 GPA / ACT 21 / SAT 1060 from English-speaking countries). Transfer eligibility: 3.0 GPA in 24+ transferable hours. Renewable up to 8 (freshman) or 6 (transfer) semesters while cumulative MSSU GPA stays at/above 2.75.', NULL, 'https://www.mssu.edu/student-affairs/financial-aid/scholarships/international-scholarships.php', 'https://www.mssu.edu/student-affairs/financial-aid/scholarships/international-scholarships.php', '2026-08-30'),
    ('a4afafa8-1f40-4f38-8053-e6e8496e5676', 'MOSO First-Year International Award', 'Missouri Southern State University', 'US', '7a17bb5a-c054-4913-b729-b96b764644a6', '4287ff56-fef4-487d-a25c-dd5f88b4a21a', 'PARTIAL_TUITION', 858.89, 'Original figure: USD 1,000, one-time, non-renewable, converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28). Eligibility: new first-time degree-seeking international students, 2.25 high school GPA, same English proficiency minimums as MIAS above.', NULL, 'https://www.mssu.edu/student-affairs/financial-aid/scholarships/international-scholarships.php', 'https://www.mssu.edu/student-affairs/financial-aid/scholarships/international-scholarships.php', '2026-08-30'),
    ('a0c99be4-6ac5-4832-bc4f-ad2efd38fab2', 'MOSO International Retention Scholarship', 'Missouri Southern State University', 'US', '7a17bb5a-c054-4913-b729-b96b764644a6', '4287ff56-fef4-487d-a25c-dd5f88b4a21a', 'PARTIAL_TUITION', 858.89, 'Original figure: USD 1,000 total (USD 500/semester), converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28). Eligibility: 3.0 cumulative GPA, 24+ completed credit hours at MSSU, and "must live on campus." Renewable up to 6 semesters while cumulative GPA stays at/above 3.0.', NULL, 'https://www.mssu.edu/student-affairs/financial-aid/scholarships/international-scholarships.php', 'https://www.mssu.edu/student-affairs/financial-aid/scholarships/international-scholarships.php', '2026-08-30'),
    ('381b4880-b51a-4583-b004-4bd91f46d9a7', 'International Undergraduate Scholarship', 'Arts University Bournemouth', 'GB', 'e66717ce-2eae-4b4c-b8e1-d0671ab7723c', 'da6fdb5b-348a-48c6-b931-01b7d65e3b0c', 'PARTIAL_TUITION', 5832.94, 'Original figure: "up to GBP 5,000," converted at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28) -- the amount shown is the published maximum, actual awards may be lower. Awarded for the first year only, to students holding an offer for 2026/2027 who are classified as overseas fee payers; cannot be combined with other AUB awards.', NULL, 'https://aub.ac.uk/international/international-scholarships/international-undergraduate-and-postgraduate-scholarships', 'https://aub.ac.uk/international/international-scholarships/international-undergraduate-and-postgraduate-scholarships', '2026-08-30'),
    ('c7509403-eeaa-463a-a5ee-50f08cc7e643', 'Dr Nicholas Bowen Award for Excellence', 'Regent''s University London', 'GB', '0ae62c03-4aee-4e31-91c1-e97ad51f54ec', NULL, 'PARTIAL_TUITION', 2333.18, 'Original figure: GBP 2,000, converted at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28). Quoted verbatim: awarded "for their academic performance, enterprising spirit and commitment to internationalism." Sourced via Wayback Machine archive (capture 2026-03-02) since the live regents.ac.uk site returns HTTP 403 to automated fetches. Regent''s also lists a "PG Global Scholarship" and "UG Global Scholarship" for September 2026, but their amounts/eligibility could not be confirmed (dedicated pages are 403-blocked live with no Wayback snapshot available) -- not seeded.', NULL, 'http://web.archive.org/web/20260302083021/https://www.regents.ac.uk/admissions/scholarships-and-funding', 'http://web.archive.org/web/20260302083021/https://www.regents.ac.uk/admissions/scholarships-and-funding', '2026-08-30'),
    ('d9ad35c7-2a0f-400c-b06c-cf4762b489ae', 'Global Excellence Scholarship Undergraduate (September 2026)', 'University of Dundee', 'GB', '995da90e-9ba4-45b4-bc03-04e73298f1ec', 'd2c6259a-0912-4a23-b7df-0819b63184f0', 'PARTIAL_TUITION', 8749.42, 'Original figure: GBP 7,500/year, converted at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28). Automatically considered, no separate application. Eligibility quoted verbatim: offer for "a full-time, on-campus taught Bachelor''s programme in any academic School" (excluding Medicine/Dentistry), "programme fee of GBP 21,800 or above," "AAB at A-Level or above (or equivalent)," and the student must be "classified as an International Fee-paying student, as confirmed in your offer letter." The seeded International Relations and Politics MA (Hons) programme (GBP 23,150/year) meets the fee threshold.', NULL, 'https://www.dundee.ac.uk/scholarships/global-excellence-scholarship-undergraduate-september-2026', 'https://www.dundee.ac.uk/scholarships/global-excellence-scholarship-undergraduate-september-2026', '2026-08-30');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, source_url, source_checked_on, notes) VALUES
    ('59e25706-a6e0-4192-b56a-1bde6c015fe0', '7f8ad90e-be90-4290-8379-be14a583bebd', 'UNIVERSITY_DORM', 'McMindes Hall', 'Hays', 928.07, NULL, NULL, ARRAY['open access meal plan'], NULL, 'https://www.fhsu.edu/international/admissions/financial/tuition/estimated-educational-expenses.pdf', '2026-08-30', 'Original figure: USD 9,725 for the 2026-2027 academic year (double occupancy, room + open-access meal plan), divided by the standard 9-month US academic year (Aug-May) to derive a monthly figure, then converted at 1 EUR = 1.1643 USD (ECB reference rate, 2026-08-28). On-campus, so distance to university is not applicable (left NULL, same convention used elsewhere in this schema for on-campus housing).'),
    ('4382cd02-4437-4eb9-aa20-4aedbeccb6bd', '3fec40cf-1efd-470c-8c30-a7a2bf80cc74', 'PRIVATE_HALL', 'Clarence Dock Village', 'Leeds', 712.79, NULL, NULL, ARRAY['en-suite rooms', '5-6 person flats', 'utilities included', 'Wi-Fi included', 'insurance included', 'gym', 'cinema room', 'laundrette', '24-hour security'], NULL, 'https://www.leedstrinity.ac.uk/accommodation/clarence-dock-village/', '2026-08-30', 'Original figure: GBP 141/week, converted to a monthly figure using the standard 52/12 weeks-per-month factor, then to EUR at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28). Contract length 41 weeks. Located in Leeds city centre, described by the source as "a 15-minute walk from the city centre" / "less than a 20-minute walk" from the Leeds City Campus -- no distance in km was published, so distance_to_university_km is left NULL rather than estimated. Cheaper on-campus alternatives at Horsforth also exist (Kirkstall Hall from GBP 119/week; All Saints Court/Fountains Court GBP 145-149/week; Trinity Close GBP 149-155/week, returning students only) -- not seeded as separate rows.'),
    ('317916c2-3e01-4ab4-ba14-a79ef8b4c007', 'e036c8b3-054b-410e-82d0-403e57e95483', 'PRIVATE_HALL', 'Ironworks House', 'London', 1026.21, NULL, NULL, ARRAY['en-suite bathrooms', 'bills included', 'insurance included', 'Wi-Fi included', 'fitted kitchens', '24/7 security', 'bike storage'], NULL, 'https://www.trinitylaban.ac.uk/accommodation/student-halls/', '2026-08-30', 'Original figure: GBP 203.00/week ("Affordable Cluster" rate, 2026/27), converted to a monthly figure using the standard 52/12 weeks-per-month factor, then to EUR at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28). Trinity Laban''s own accommodation page states directly: "Ironworks House is not owned by Trinity Laban. It''s a privately owned halls of residence" that the conservatoire recommends to students -- seeded as PRIVATE_HALL accordingly, not UNIVERSITY_DORM. Described as ~20 min walk / 15 min bus / 7 min bike from Trinity Laban''s Laurie Grove site -- no distance in km was published, so distance_to_university_km is left NULL. Pricier "Discounted" (GBP 256.50-266.00/week), "Premium" (GBP 275.50-285.50/week), and "Premium Studio" (GBP 350.55-360.05/week) clusters also exist at the same hall -- not seeded as separate rows. Contract lengths are 44 or 51 weeks depending on cluster.'),
    ('e8277e50-297e-419a-8d38-310d028bdaa1', '995da90e-9ba4-45b4-bc03-04e73298f1ec', 'UNIVERSITY_DORM', 'West Park Flats (Standard)', 'Dundee', 1044.26, NULL, 1.93, ARRAY['en-suite rooms', 'shared kitchen (6 flatmates)', 'utility bills included', 'Wi-Fi included', '24-hour security', 'contents insurance', 'ResLife welfare support'], NULL, 'https://www.dundee.ac.uk/accommodation/flats/west-park-flats', '2026-08-30', 'Original figure: GBP 206.57/week (September 2026 session), converted to a monthly figure using the standard 52/12 weeks-per-month factor, then to EUR at 1 EUR = 0.8572 GBP (ECB reference rate, 2026-08-28). Distance to university: original figure "1.2 miles" from City Campus, converted to km (1 mile = 1.60934 km) -- both figures disclosed here since the conversion is a standard unit conversion, not an estimate. A cheaper "West Park Villas" option (GBP 179.48/week) and pricier "Premier" flats (GBP 213.57/week) and other halls (Seabraes 1/2, City Campus Flats) also exist -- not seeded as separate rows.');

-- Second USA/UK depth batch (added 2026-08-31), further deepening the two
-- largest international-student destination countries per explicit user
-- request ("make the usa and uk not shallow, feed them more seed data
-- first"), before any other country. Every fact below was researched live
-- against an official institutional (.edu / .ac.uk) source on 2026-08-31,
-- not invented. All GBP/USD figures are converted here to EUR using the ECB
-- euro reference exchange rate for 2026-08-28 (the latest available
-- business-day rate at time of writing: 1 EUR = 1.1643 USD, 1 EUR = 0.8572
-- GBP), with the original figure and conversion basis disclosed in every
-- affected row's notes so a future reader can verify or redo the conversion.
--
-- New universities: University of Montana, University of Alaska Fairbanks,
-- Louisiana Tech University, University of Maine, Northern Arizona
-- University (US); Bangor University, Queen's University Belfast,
-- University of Stirling, Coventry University, University of Sunderland
-- (GB). Checked beforehand for overlap with all previously-seeded US/GB
-- names (UTA, Toledo, Wichita State, Fort Hays State, Alcorn State,
-- Berklee, Agnes Scott, MSSU, Manchester, Leeds Trinity, AUB, Regent's
-- University London, Trinity Laban, Dundee) -- none found.
--
-- Notable decisions/omissions this batch:
--   * Ulster University was the original 5th UK candidate, but its live
--     site (ulster.ac.uk) returned a persistent Cloudflare bot-challenge
--     (HTTP 403) on every URL tried, via both the WebFetch tool and curl
--     with browser headers -- substituted Queen's University Belfast for
--     Northern Ireland coverage instead, per this project's rule to
--     substitute rather than guess when a site is unfetchable.
--   * QUB's own pages also bot-blocked the WebFetch tool specifically; its
--     facts below were instead fetched via curl with a browser user-agent
--     and the raw HTML read directly -- still the institution's own
--     official page text, just retrieved via a different method.
--   * GPA-to-percentage conversions (Montana 2.5/4.0=62.50, UAF
--     2.5/4.0=62.50, Louisiana Tech 2.5/4.0=62.50, NAU 2.5/4.0=62.50) are
--     disclosed derivations, not guesses, matching this project's
--     established GPA-conversion precedent. University of Maine's official
--     international admissions page does not state a minimum GPA at all,
--     so its minimum_cgpa_percentage is left NULL rather than guessed. All
--     five UK institutions use UCAS points, A-level/Higher grades, or IB
--     scores with no valid percentage conversion, so minimum_cgpa_percentage
--     is NULL for all of them -- the actual grade requirement is quoted
--     verbatim in each row's notes instead.
--   * Louisiana Tech runs a quarter-system academic calendar (Fall/Winter/
--     Spring/Summer), not semesters. This schema has no TUITION_PER_QUARTER
--     category, so its fee is stored under TUITION_PER_SEMESTER as the
--     nearest available slot, with a prominent note that it is actually a
--     per-quarter charge and must not be multiplied by 2 like a real
--     semester figure would be.
--   * UAF's tuition is billed per credit hour with no published lump-sum
--     total; the seeded TUITION_PER_SEMESTER figure is a disclosed
--     derivation (12 credits -- UAF's own stated full-time threshold --
--     times the official combined per-credit tuition+fee rate), not a
--     directly-published total.
--   * University of Maine has NO program_fees row seeded at all: its
--     official tuition page publishes only a per-credit rate with no
--     stated full-time annual credit-load figure, and the one secondary
--     page that reportedly gave a 30-credit/year budgeting standard
--     returned HTTP 404 on direct fetch -- rather than multiply by an
--     unconfirmed credit count, the annual tuition amount is omitted
--     entirely.
--   * Accommodation rows seeded only where an explicit month/week/lease
--     length was stated (Louisiana Tech's stated "9-month lease"; Bangor,
--     QUB, Stirling, and Sunderland's stated weekly rates, converted via
--     the standard 52/12 weeks-per-month factor) -- skipped for Montana,
--     UAF, Maine, NAU (all only "per semester"/"per academic year" with no
--     stated month count), and Coventry (Godiva Place's official page
--     gives only a price RANGE across room types with no single confirmed
--     room+price pairing).
--   * Scholarship amounts left NULL where the source itself does not
--     commit to one figure: Montana's UMAAS (no amount published), UAF's
--     Yu Quan Liu Scholarship (no amount published; also explicitly NOT
--     seeding UAF's larger Nanook Pledge Scholarship since its own page
--     does not confirm F-1 international-student eligibility), Louisiana
--     Tech's Bulldog Scholarship ("approximately 50%" waiver -- an
--     approximate percentage, not a dollar figure, so left NULL rather
--     than computed), and QUB's International Undergraduate Scholarship
--     (source states "GBP 3,500 or GBP 4,000 depending on Fee Rate"
--     without stating which rate gets which amount).
--   * Sunderland's Global Leaders Scholarship (GBP 6,000) does not state
--     whether the reduction recurs annually or is a first-year-only
--     award -- flagged explicitly in its row rather than assumed.

