    ('6f7a29ac-bcf0-4ebb-991f-186001d009af', '7b058bee-459c-4b5c-895b-9e9e46c88d91', 'BSc (Hons) Marine Biology and Oceanography', 'BACHELOR', 'Marine Biology and Oceanography', 36, 'https://www.bangor.ac.uk/courses/undergraduate/cf17-marine-biology-and-oceanography-bsc-hons'),
    ('c40e9c7c-8f13-4b76-982a-e957e0978ad4', 'abd12a2a-240a-4921-b30c-1997366c02e6', 'BSc (Hons) Physics', 'BACHELOR', 'Physics', 36, 'https://www.qub.ac.uk/courses/undergraduate/physics-bsc-f300/'),
