INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('f161efc2-ac4a-4ee4-8013-d803263b9c60', '282931db-f598-46b4-8edc-1472c647daaf', 62.50, 48087.26, 'IELTS', '6.0', ARRAY['Common_App', 'English_proficiency_test', 'International_Credential_Evaluation_Report', 'financial_documentation', 'passport_copy'], 'https://www.umt.edu/admissions/admission-requirements/international/full_admission.php', '2026-08-31', 'GPA quoted verbatim as "equivalent of a 2.5 U.S. GPA" for first-year international applicants (2.0 for transfer with 12+ university credits) -- minimum_cgpa_percentage here is a disclosed conversion (2.5/4.0 x 100 = 62.50), not the source''s own wording. English-proficiency minimums for Full Admission: TOEFL iBT 70, TOEFL PBT 525, IELTS 6.0 (used here), Duolingo 105, Cambridge English 180, PTE 48 -- lower Pathway-track minimums also exist but are not used here (source: https://www.umt.edu/admissions/admission-requirements/international/english-proficiency.php). official_funds_requirement_eur converted from USD 55,988 (Mountain Campus estimate; Missoula College campus estimate is lower at USD 40,382) using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28) -- https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html. Documents/funds source: https://www.umt.edu/admissions/admission-requirements/international/apply-international.php.'),
    ('eb837cc9-6c73-49ad-8387-cc1de53b501d', 'e2ef1e40-44aa-40ed-a209-99fae6210da0', 62.50, NULL, 'IELTS', '6.5', ARRAY['English_proficiency_test', 'official_diploma_if_no_graduation_date_on_transcript', 'NACES_credential_evaluation', 'UAF_financial_statement_for_international_students', 'passport_copy'], 'https://www.uaf.edu/admissions/apply/international.php', '2026-08-31', 'GPA requirement (general undergraduate policy, not international-specific, source: https://www.uaf.edu/admissions/apply/ug.php): cumulative 2.5 GPA, "Pass the 16-credit high school core curriculum with at least a 2.5" -- minimum_cgpa_percentage here is a disclosed conversion (2.5/4.0 x 100 = 62.50). English minimums: TOEFL iBT 79, IELTS 6.5 (used here), PTE 55, Duolingo 110. official_funds_requirement_eur left NULL: the "UAF Financial Statement for International Students" is required but no dollar threshold is published on the checked pages.'),
    ('a28edf75-1721-42de-9150-2d1487a054a9', '7bed2dd5-115d-42f6-8b07-7eeccc1f5483', 62.50, NULL, 'IELTS', '6.5', ARRAY['online_application', 'official_transcripts', 'bank_statement_or_scholarship_letter', 'English_proficiency_test', 'math_placement_qualification', 'DS-160', 'current_I-20_or_I-94_if_applicable'], 'https://www.latech.edu/student-life/international-affairs/undergaduate-admissions.php', '2026-08-31', 'Freshman minimum GPA quoted as "2.5 GPA (US-converted scale)" (2.25 for transfer) -- minimum_cgpa_percentage here is a disclosed conversion (2.5/4.0 x 100 = 62.50). English minimums: TOEFL iBT 79 (stated as 4.5 under a post-2026 TOEFL scoring scale per the source), IELTS 6.5 (used here), Duolingo 100, PTE 50. Funds requirement is stated only as "a bank statement or scholarship letter proving funds for each academic year" with no published dollar threshold, so official_funds_requirement_eur is left NULL rather than guessed. Louisiana Tech runs a quarter (not semester) academic calendar -- see this program''s program_fees row for how that affects the tuition figure.'),
    ('44689903-bdb9-4206-b037-acf3637036be', '20d313ca-7b48-4358-8bdf-d955fddb205c', NULL, NULL, 'IELTS', '6.5', ARRAY['Common_App_or_ApplyMaine', 'NACES_credential_evaluation', 'English_proficiency_test'], 'https://umaine.edu/admissions/apply/international-undergraduate-admissions/', '2026-08-31', 'COULD NOT CONFIRM a minimum GPA figure on the official international undergraduate admissions page -- left NULL rather than guessed. English minimums: TOEFL iBT 79 (4.5 under post-Jan-2026 scoring), TOEFL Essentials 8.5, IELTS 6.5 (used here), PTE 53, CEFR B2, Duolingo 110. official_funds_requirement_eur also left NULL (no published threshold found on the checked page). No program_fees row is seeded for this university''s tuition: the official tuition page (https://umaine.edu/sfs/tuition-and-fees/) publishes only a per-credit-hour rate (USD 1,278/credit for non-resident undergraduates) with no stated annual full-time credit-load figure, and a secondary page that reportedly gave a 30-credit/year budgeting standard (umaine.edu/stuaid/resources/financial-aid-glossary/) returned HTTP 404 on direct fetch -- rather than multiply by an unconfirmed credit count, the annual tuition amount is omitted entirely.'),
    ('de0b35e3-baf7-4c9e-9a89-a5f80102e4c8', '645d2329-c6fe-4e5d-a998-c03f54a0b36a', 62.50, NULL, 'IELTS', '6.0', ARRAY['online_application', 'passport_copy', 'official_transcripts', 'English_proficiency_test', 'financial_verification_form'], 'https://in.nau.edu/center-international-education/apply-bachelors/', '2026-08-31', 'General undergraduate international admission GPA quoted as "a minimum 2.5 grade-point average (GPA) on a 4-point scale" (2.0 if transferring with a US associate degree) -- minimum_cgpa_percentage here is a disclosed conversion (2.5/4.0 x 100 = 62.50). Note: the Forestry program itself additionally requires a 2.75 GPA with a C or better in major coursework as a gate into the professional-program component (https://catalog.nau.edu/Catalog/details?plan=FORBSFX) -- a program-specific requirement distinct from the general admission GPA seeded above. English minimums: TOEFL iBT 70, IELTS 6.0 (used here), Duolingo 95, ACT English&Reading 21, SAT EBRW 350, PTE 56. official_funds_requirement_eur left NULL: bank statements are required but no dollar threshold is published on the checked page.'),
    ('e691b6be-3524-4499-9953-cff77e8325a8', '6f7a29ac-bcf0-4ebb-991f-186001d009af', NULL, NULL, 'IELTS', '6.0', ARRAY['school_leaving_qualification_certificates', 'English_proficiency_test'], 'https://www.bangor.ac.uk/international/applying/entryrequirements', '2026-08-31', 'UK A-level/UCAS-tariff/IB grade requirements are a points/grades system, not a percentage -- minimum_cgpa_percentage is left NULL rather than force-converted, per this project''s standing rule for UK qualifications. General international academic requirement quoted verbatim: "a school leaving qualification which is equivalent to the British school leaving qualification, (A-levels / International Baccalaureate)." COULD NOT CONFIRM the exact course-specific A-level/UCAS-tariff/IB figure for BSc Marine Biology and Oceanography: the live course page was serving Clearing-period content at time of fetch (2026-08-31, active Clearing for Sept 2026 entry), which replaces the normal requirements table with generic Clearing messaging. IELTS minimum shown (6.0 overall, 5.5 in each sub-skill) is Bangor''s standard undergraduate requirement (https://www.bangor.ac.uk/international/future/englishlanguage); higher minimums apply for Law/Philosophy (6.5) and Nursing (7.0), not applicable here.'),
    ('ebdcc43b-c42f-491b-a2eb-b6350fe32fec', 'c40e9c7c-8f13-4b76-982a-e957e0978ad4', NULL, NULL, 'IELTS', '6.0', ARRAY['official_transcripts', 'GCSE_English_language_grade_C_4_or_equivalent', 'English_proficiency_test', 'passport_copy'], 'https://www.qub.ac.uk/courses/undergraduate/physics-bsc-f300/', '2026-08-31', 'A-level/IB/Irish-Leaving-Certificate grades are points/letter-grade systems, not percentages -- minimum_cgpa_percentage left NULL, per this project''s standing rule for UK/Irish qualifications. Grades quoted verbatim: A-level "ABB including Mathematics and Physics"; IB Diploma "33 points overall including 6 5 5 at Higher Level including Mathematics and Physics"; Irish Leaving Certificate "H3H3H3H3H3H3/H2H3H3H3H3 including Higher Level grade H3 in Mathematics and Physics." All applicants also need GCSE English Language grade C/4 (or equivalent). IELTS: "6.0 with a minimum of 5.5 in each test component." Substituted for Ulster University in this batch: Ulster''s site (ulster.ac.uk) returned a persistent Cloudflare bot-challenge (HTTP 403) on every URL tried, via both the WebFetch tool and curl with browser headers, so Queen''s University Belfast was researched instead for Northern Ireland coverage. QUB''s own WebFetch access was also bot-blocked; this page''s content was instead fetched via curl with a browser user-agent and the raw HTML read directly -- still the institution''s own official page text, just retrieved via a different method than the WebFetch tool.'),
    ('de59702a-df02-41e0-aa03-17919d57b477', '2bc20721-8fea-43d1-aba8-db27dd589a23', NULL, NULL, 'IELTS', '6.0', ARRAY['qualification_certificates', 'passport_copy_for_visa'], 'https://www.stir.ac.uk/courses/ug/marine-biology/', '2026-08-31', 'Scottish Highers/A-level/IB/BTEC grades are points/grade systems, not percentages -- minimum_cgpa_percentage left NULL. Year-1 (four-year honours) entry grades quoted verbatim: Scottish Highers "ABBB"; A-levels "BBB"; IB Diploma "28 points"; BTEC "DDM"; essential subject "one of Biology, Chemistry, Mathematics or Physics." IELTS: "6.0 with a minimum of 5.5 in each sub-skill." (Year-2 direct entry has different, higher requirements -- Advanced Highers/A-levels "ABB", IB "32 points" -- not seeded here since this row covers standard Year-1 entry.) This BSc (Hons) is a genuine undergraduate honours degree -- no Scottish "MA (Hons)" naming-trap risk here since the title itself is BSc, not MA. COULD NOT CONFIRM a complete itemized required-documents checklist for this specific course -- only general guidance (scanned qualification documents, passport for visa purposes) was found on the checked page.'),
    ('80212885-23e7-4396-8d66-7f42a564644e', '1de8064f-aa4f-4812-a6ec-df86ad635ae0', NULL, NULL, 'IELTS', '6.0', ARRAY['UCAS_application', 'English_proficiency_test'], 'https://www.coventry.ac.uk/course-structure/ug/eec/motorsport-engineering-mengbeng-hons/', '2026-08-31', 'UCAS Tariff is a points system, not a percentage -- minimum_cgpa_percentage left NULL. Confirmed directly: UCAS Tariff "72 points." COULD NOT CONFIRM the specific A-level letter-grade combination: the course page''s entry-requirements section renders via a JS "eligibility checker" widget not present in the fetched static HTML/DOM (confirmed by searching the raw page source for "A Level"/"IELTS"/"GCSE" text -- none found). IELTS minimum shown (6.0 overall, 5.5 in each component) is from Coventry''s general international-students hub page (https://www.coventry.ac.uk/international-students-hub/entry-requirements/), not course-specific, since the course page itself did not state one -- flagged accordingly.'),
    ('77874bc2-0ffd-41d1-9c0d-5585bdaa9eb6', 'b64dba4d-af1a-446b-b7c8-e8c9de943f9b', NULL, NULL, 'IELTS', '6.0', ARRAY['UCAS_application', 'GCSE_certificates_grade_C_4_maths_and_english', 'English_proficiency_test'], 'https://www.sunderland.ac.uk/undergraduate/ba-hons-sports-journalism', '2026-08-31', 'UCAS Tariff is a points system, not a percentage -- minimum_cgpa_percentage left NULL. Quoted verbatim: "104-120 UCAS Tariff points, from a combination of acceptable Level 3 qualifications" (A-levels, T-levels, BTEC, Scottish/Irish Highers, Access to HE, and IB all accepted); GCSE requirement of "three passes at GCSE grade C or above" including Mathematics and English Language (numerical GCSEs need minimum grade 4). An informal interview is also required, since this is an NCTJ-accredited course. IELTS minimum (6.0 overall, 5.5 in each component) is from Sunderland''s general international English-language page (https://london.sunderland.ac.uk/admissions/english-language-requirements/), since the course page''s own country-selector widget for language requirements did not render in the fetch.');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('199b1fc8-f394-42ca-8e84-87d43e96a248', '282931db-f598-46b4-8edc-1472c647daaf', 'TUITION_PER_YEAR', 'INTERNATIONAL', 29969.94, 'https://www.umt.edu/student-financial-services/cost-of-attendance/undergraduate-coa/undergraduate-out-of-state-coa.php', '2026-08-31', 'Original figure: USD 34,894/year (2026-27, non-resident/international undergraduate -- combined Fall+Spring: Registration Fee $30 + Tuition $3,420 + Non-Resident Tuition $12,276 + mandatory fees $1,721, per semester, x2), converted to EUR using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28) -- https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-usd.en.html. Per-semester figure is USD 17,447. COULD NOT CONFIRM a distinct international-student-specific fee beyond these standard mandatory fees.'),
    ('9c294e7f-ec5d-46fc-a30f-6f077a1cf056', 'e2ef1e40-44aa-40ed-a209-99fae6210da0', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 10682.81, 'https://catalog.uaf.edu/costs-financial-aid/tuition/', '2026-08-31', 'Derived, not directly published as a lump sum: UAF''s official per-credit combined rate for Fairbanks F100-F499 courses is USD 934/credit tuition + USD 56 Consolidated fee + USD 25 UA Infrastructure fee + USD 21.50 Bookstore Bundle fee = USD 1,036.50/credit, multiplied here by 12 credits -- the officially-stated full-time enrollment threshold for undergraduates (per UAF''s Nanook Pledge Scholarship terms: "full-time enrollment (12 credits)," https://www.uaf.edu/finaid/nonresident.php) -- giving USD 12,438/semester. Converted to EUR using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28). A one-time USD 225 Matriculation fee for newly admitted degree-seeking students is seeded separately below. Verify the current per-credit rate directly, since actual per-semester cost depends on the student''s actual credit load.'),
    ('28158ad3-4162-4987-926c-c7f480cb1515', 'e2ef1e40-44aa-40ed-a209-99fae6210da0', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 193.25, 'https://catalog.uaf.edu/costs-financial-aid/tuition/', '2026-08-31', 'Original figure: USD 225 one-time Matriculation fee for newly admitted degree-seeking students, converted to EUR using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28).'),
    ('653f23ac-82e6-41d2-a243-392e1434e1b3', '7bed2dd5-115d-42f6-8b07-7eeccc1f5483', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 6682.99, 'https://www.latech.edu/administration/finance/comptroller/tuition-fees.php', '2026-08-31', 'IMPORTANT SCHEMA CAVEAT: Louisiana Tech runs a quarter-system academic calendar (Fall, Winter, Spring, and Summer quarters -- confirmed via the university''s own catalog quarter pages, e.g. https://catalog.latech.edu/content.php?catoid=13&navoid=725), not a semester system. This schema has no TUITION_PER_QUARTER category, so this figure is stored under TUITION_PER_SEMESTER as the nearest available slot -- it is actually Louisiana Tech''s PER-QUARTER charge, not a true semester charge. Do NOT multiply by 2 to estimate an annual cost the way a real per-semester figure would be used; the exact number of quarters a given student enrolls in per year (3 vs 4, i.e. whether Summer is included) could not be confirmed from an official source, so no annual figure is derived here. Original figure: USD 7,781 for 12+ credit hours per quarter, College of Engineering and Science (the college housing Cyber Engineering) -- other colleges range USD 7,621-7,808/quarter for the same course-load tier. Converted to EUR using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28). Figure includes tuition, technology fee, energy surcharge, and average college fee, per the source. COULD NOT CONFIRM a distinct international-student fee beyond this.'),
    ('d2a5ff8a-d4f1-4139-b865-038a7960c225', '645d2329-c6fe-4e5d-a998-c03f54a0b36a', 'TUITION_PER_YEAR', 'INTERNATIONAL', 25766.56, 'https://in.nau.edu/center-international-education/tuition-fees/', '2026-08-31', 'Original figure: USD 30,000/year (2026-27, non-resident/international undergraduate, Flagstaff campus), converted to EUR using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28). Mandatory student fees (USD 1,625/year) and the mandatory NAU Student Health Insurance Plan (USD 2,876/year) are seeded as separate ADMINISTRATIVE_FEE rows below, since they are billed alongside but distinct from tuition itself.'),
    ('9f38f245-a6b5-4733-baf1-a51bb1893c7f', '645d2329-c6fe-4e5d-a998-c03f54a0b36a', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 1395.69, 'https://in.nau.edu/center-international-education/tuition-fees/', '2026-08-31', 'Original figure: USD 1,625/year mandatory student fees (2026-27), converted to EUR using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28).'),
    ('af6fe0ee-3155-45c4-ac0d-3894b78a99f3', '645d2329-c6fe-4e5d-a998-c03f54a0b36a', 'ADMINISTRATIVE_FEE', 'INTERNATIONAL', 2470.15, 'https://in.nau.edu/center-international-education/tuition-fees/', '2026-08-31', 'Original figure: USD 2,876/year, NAU Student Health Insurance Plan, converted to EUR using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28). Quoted verbatim as mandatory: "Enrollment in the NAU Student Health Insurance Plan is mandatory for all international students as required by Arizona Board of Regents policy."'),
    ('32a4ffda-dce3-450e-8ca9-53f4982161d9', '6f7a29ac-bcf0-4ebb-991f-186001d009af', 'TUITION_PER_YEAR', 'INTERNATIONAL', 24498.37, 'https://www.bangor.ac.uk/international/fees', '2026-08-31', 'Original figure: GBP 21,000/year (Band D, 2026 September entry) -- Bangor prices international undergraduate tuition in four subject bands: Band A (Arts & Humanities, Education, Law, Study Abroad) GBP 18,000; Band B (Business, Linguistics & Music, Accounting/Banking/Finance, Economics/Management/Marketing, Healthcare Science, Sport/Health/Exercise Science) GBP 19,000; Band C (Biological Sciences, Computer Science, Environmental Science & Forestry, Geography, Zoology) GBP 20,000; Band D (Design, Electronic Engineering, Medical Science, Ocean Science, Psychology, Nursing) GBP 21,000 -- Marine Biology and Oceanography falls under Ocean Science in Band D. Converted to EUR using the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28) -- https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-gbp.en.html. An International Experience Year costs an additional GBP 1,430, or a Placement Year GBP 1,907 -- not included here.'),
    ('7cfe2635-c805-428d-a2ff-82c3f35365f3', 'c40e9c7c-8f13-4b76-982a-e957e0978ad4', 'TUITION_PER_YEAR', 'INTERNATIONAL', 31031.26, 'https://www.qub.ac.uk/Study/Feesandfinance/FileStore/Tuition%20Fee%20and%20Related%20Charges%20Schedule%202026-27.pdf', '2026-08-31', 'Original figure: GBP 26,600/year (2026-27, International/EU-Other students, Fee Rate 2 -- laboratory-based, which Physics falls under; classroom-based Fee Rate 1 is GBP 22,400/year), from QUB''s official Tuition Fee and Related Charges Schedule 2026-27 PDF, converted to EUR using the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28).'),
    ('51a874a6-3df6-458f-8214-53632b0cf2cc', '2bc20721-8fea-43d1-aba8-db27dd589a23', 'TUITION_PER_YEAR', 'INTERNATIONAL', 27648.16, 'https://www.stir.ac.uk/courses/fees/', '2026-08-31', 'Original figure: GBP 23,700.00/year, full time, 2026/7 entry -- International students (including EU) -- course code UHX16-MFB, from Stirling''s official per-course fee-data listing page (the course page itself loads its fee via a JS widget not present in static HTML, so this authoritative fee-table page was used instead). Converted to EUR using the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28).'),
    ('aeab6103-0001-4922-8e09-6d461cfb9b00', '1de8064f-aa4f-4812-a6ec-df86ad635ae0', 'TUITION_PER_YEAR', 'INTERNATIONAL', 24265.05, 'https://www.coventry.ac.uk/course-structure/ug/eec/motorsport-engineering-mengbeng-hons/', '2026-08-31', 'Original figure: GBP 20,800/year (international, full-time, BEng/MEng Motorsport Engineering), converted to EUR using the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28).'),
    ('ebe0cbf6-84dd-4593-82d4-5ebe6569d747', 'b64dba4d-af1a-446b-b7c8-e8c9de943f9b', 'TUITION_PER_YEAR', 'INTERNATIONAL', 20415.31, 'https://www.sunderland.ac.uk/undergraduate/ba-hons-sports-journalism', '2026-08-31', 'Original figure: GBP 17,500/year (international), stated directly on the official course page, converted to EUR using the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28).');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('6bc704ae-5cca-48d8-9901-fe17acf725a4', 'University of Montana Academic Achievement Scholarship (UMAAS)', 'University of Montana', 'US', '74344530-5e75-4755-a1d7-68017c27fb89', NULL, 'PARTIAL_TUITION', NULL, 'Automatic consideration for out-of-state/international undergraduate and transfer students pursuing their first bachelor''s degree, upon admission -- no separate application required. COULD NOT CONFIRM the exact dollar amount or percentage: not stated on the official page.', NULL, NULL, 'https://www.umt.edu/finaid/scholarships/non-resident-scholarships-for-entering-students/default.php', '2026-08-31'),
    ('2ca17d7f-18d0-4c59-a8fe-673f1087cab9', 'Yu Quan Liu/Long Jin Huang/Yue-Ming Chou (Li Huang Chou) Scholarship', 'University of Alaska Fairbanks, Department of Natural Resources and Environment', 'US', '1934053f-2fd7-4702-8e70-1fc3c202443c', NULL, 'PARTIAL_TUITION', NULL, 'For an "international student (Chinese preferred)" studying plant health, plant biology, or agriculture at UAF. COULD NOT CONFIRM the exact dollar amount: not stated on the official page. Flagged separately: UAF''s larger Nanook Pledge Scholarship (nonresident-rate awards of USD 5,000-12,000/year for first-year students, USD 1,000-5,000/year for transfers, by GPA band) is NOT seeded here because its page addresses "nonresidents" generally and does not explicitly confirm F-1 international-student eligibility -- UAF''s own International Student and Scholar Services handbook instead directs international students to "University of Alaska Foundation and privately funded scholarships" (https://www.uaf.edu/isss/handbook/financial-aid/), which is what this smaller, explicitly international-eligible award represents.', NULL, NULL, 'https://www.uaf.edu/nre/undergraduate/scholarships.php', '2026-08-31'),
    ('077364ac-da6c-42b8-9463-2019e8922711', 'Bulldog Out-of-State Scholarship (International Student Track)', 'Louisiana Tech University', 'US', '62e43f34-7765-498f-aa5c-2007c8aa65aa', NULL, 'PARTIAL_TUITION', NULL, 'Described by the source only as a "tuition fee waiver of approximately 50%" for eligible international freshmen -- amount_eur is left NULL rather than computing a derived dollar figure from this approximate ("approximately 50%") percentage, since exact tuition depends on college/course-load and the source itself does not commit to a precise figure. Eligibility (international freshmen): minimum 2.5 GPA (US scale, assessed by the admissions coordinator) plus one qualifying score (TOEFL 4.5/79 pre-2026 scoring, IELTS 6.5, Duolingo 105, PTE 58, SAT 1130, or ACT 23). Transfer/enrolled international students: 12+ completed credit hours, cumulative 2.75 GPA. Maintenance requires a 2.0 quarterly GPA.', NULL, NULL, 'https://www.latech.edu/student-life/international-affairs/undergaduate-admissions.php', '2026-08-31'),
    ('01bb68c1-15cd-412a-8207-630fa14a1856', 'Flagship Match Commitment (International Scholarship, 2026-27)', 'University of Maine', 'US', '635749c9-a9de-4f5a-bb90-b34c9b6c88cb', NULL, 'PARTIAL_TUITION', 13913.94, 'Original figure: USD 16,200/year, converted to EUR using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28). Annual award for international undergraduates admitted for 2026-27; eligibility requires a minimum 2.5 cumulative high school GPA, with the exact award based on academic performance/coursework rigor. Related but separate awards on the same official page: Flagship Leaders Commitment (USD 9,000-12,000/year), Global Flagship Match Commitment (USD 25,110/year, specifically for "international students who graduate from Maine high schools" -- not applicable to a student applying from abroad), and an Early Action Award adding USD 3,000 for applications submitted by 1 Dec 2025 (already past for the 2026-27 cycle at time of writing). Renewal requires satisfactory academic progress and at least part-time enrollment (6+ graded credit hours/semester).', NULL, NULL, 'https://umaine.edu/admissions/cost-aid/merit-scholarships/international-scholarships-26-27/', '2026-08-31'),
    ('aabf63d6-93f0-4653-bcbb-832e4ecb6044', 'International Excellence Award (IEA)', 'Northern Arizona University', 'US', 'c8ae2731-d0ab-4209-955d-2cf33b53e948', NULL, 'PARTIAL_TUITION', 9447.74, 'Original figure: "up to USD 11,000 per year toward NAU tuition and fees" (source''s own wording) -- the amount shown here is that published maximum, converted to EUR using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28); actual awards may be lower. For first-time, full-time F-1 international students pursuing a bachelor''s or master''s degree at NAU''s Flagstaff campus; requires a minimum 3.0 GPA at time of admission, and submission of required I-20 financial documentation. Automatic consideration upon a complete international admission application -- no separate application. Renewable if full-time enrollment and 3.0 GPA are maintained. Excludes students with government sponsorship, athletic scholarships, or other tuition waivers.', NULL, NULL, 'https://in.nau.edu/isss/scholarships/', '2026-08-31'),
    ('6bac7b03-97c6-47f3-aa02-2c66cf7a0dbf', 'Dean''s Scholarship', 'Bangor University', 'GB', '7b058bee-459c-4b5c-895b-9e9e46c88d91', NULL, 'PARTIAL_TUITION', 6999.53, 'Original figure: GBP 6,000 per year of study, converted to EUR using the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28). Eligibility: predicted or achieved AAB or above at A-level (or equivalent), enrolled on a full 3-4 year on-campus degree (no advanced entry directly into year 2 or 3), and not fully funded by a third-party sponsor. Awarded at the university''s discretion; automatic consideration, no separate application needed.', NULL, NULL, 'https://www.bangor.ac.uk/international/future/deans-scholarship', '2026-08-31'),
    ('3ee25644-e0e2-41d1-9a7f-7e05c949a1e7', 'International Undergraduate Scholarship', 'Queen''s University Belfast', 'GB', 'abd12a2a-240a-4921-b30c-1997366c02e6', NULL, 'PARTIAL_TUITION', NULL, 'Source states the first-year award is "GBP 3,500 or GBP 4,000 depending on Fee Rate" without pairing which of QUB''s two fee rates (Fee Rate 1, classroom-based, GBP 22,400/year; Fee Rate 2, laboratory-based, GBP 26,600/year -- Physics is Fee Rate 2) receives which amount -- amount_eur is left NULL rather than guess the pairing. Automatic on enrolment, no application required; for new full-time international undergraduates only (excludes students on a placement year).', NULL, NULL, 'https://www.qub.ac.uk/Study/international-students/international-scholarships/south-asia/', '2026-08-31'),
    ('782240bc-b348-44f4-8ac1-ea3e6ececd3b', 'International Undergraduate Scholarship', 'University of Stirling', 'GB', '50c2c93b-30c4-4649-b937-5bb42604d590', NULL, 'PARTIAL_TUITION', 2916.47, 'Original figure: GBP 2,500/year (GBP 10,000 total over a standard four-year Scottish honours degree), converted to EUR using the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28). Eligibility: holds a conditional or unconditional offer for an eligible undergraduate course starting September 2026, January 2027, September 2027, or January 2028; classed as International for fee purposes; full-time study. Cannot be combined with other Stirling scholarships except the Sports Scholarship. No separate application needed -- automatic consideration.', NULL, NULL, 'https://www.stir.ac.uk/scholarships/general/undergraduate/international-undergraduate-scholarship/', '2026-08-31'),
    ('218b06bc-07c1-4457-b964-1ad6d7cca702', 'Coventry University Group Scholarship (2026-27)', 'Coventry University', 'GB', '453d0ea2-d429-4630-8bc0-e180b753e600', NULL, 'PARTIAL_TUITION', 2333.18, 'Original figure: GBP 2,000/year reduction off the tuition fee, totaling GBP 6,000 across a standard 3-year bachelor''s degree, converted to EUR using the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28). Eligibility: self-funded international students (excluding EU) starting a bachelor''s degree in 2026/27 at a Coventry University Group UK campus (excludes Coventry University Online).', NULL, NULL, 'https://www.coventry.ac.uk/international-students-hub/apply-for-a-scholarship/', '2026-08-31'),
    ('219ca668-aad0-4e5d-9b40-0bfed88e7fbf', 'Global Leaders Scholarship (2026/27)', 'University of Sunderland', 'GB', 'c8345875-e831-4aee-af7f-b7eebd95dcc3', NULL, 'PARTIAL_TUITION', 6999.53, 'Original figure: GBP 6,000 tuition fee reduction for undergraduate courses (a separate GBP 4,000 rate applies specifically to MPharm Pharmacy, and GBP 5,500 for postgraduate courses -- not applicable here), converted to EUR using the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28). Eligibility: international students from eligible countries studying an on-campus undergraduate course (excludes foundation, EAP, and pre-masters courses); for new 2026/27 entrants who have not yet paid a deposit. The source does not state whether this GBP 6,000 reduction recurs every year of study or is a one-off, first-year-only award -- flagged explicitly rather than assumed; treat conservatively as a first-year figure.', NULL, NULL, 'https://www.sunderland.ac.uk/study/scholarships-discounts-and-specialised-grants/international/', '2026-08-31');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('8fc8fa37-b878-4ebb-9108-eb62162277a0', '62e43f34-7765-498f-aa5c-2007c8aa65aa', 'SHARED_APARTMENT', 'Legacy Park (Louisiana Tech University)', 'Ruston', 210.90, NULL, NULL, NULL, NULL, NULL, 'https://www.latech.edu/student-life/housing-and-dining/housing/housing-options/legacy-park.php', '2026-08-31', 'Original figure: USD 2,210 per resident for a stated "9-month lease" (two-bedroom apartment, non-private/shared bedroom) -- monthly rent derived by dividing by the explicitly stated 9-month lease length (USD 245.56/month), then converted to EUR using the ECB reference rate (1 EUR = 1.1643 USD, 2026-08-28). A pricier private-bedroom Townhome option (four-bedroom unit, USD 2,820, also a 9-month lease) is also available at the same property -- not seeded as a separate row.'),
    ('51819c81-93dd-47b2-a5b3-fbef0f5b08d7', '7b058bee-459c-4b5c-895b-9e9e46c88d91', 'UNIVERSITY_DORM', 'St Mary''s Village (Bangor University)', 'Bangor', 945.33, NULL, NULL, NULL, NULL, NULL, 'https://www.bangor.ac.uk/accommodation/rooms/st-marys/en-suite-premium', '2026-08-31', 'Original figure: GBP 187/week (En-suite Premium room, 14.5-15m2, 2026/27), converted to a monthly figure using the standard 52/12 weeks-per-month factor (GBP 810.33/month), then to EUR at the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28).'),
    ('fc091a42-f508-4caf-9b92-17ce839fa1c3', 'abd12a2a-240a-4921-b30c-1997366c02e6', 'UNIVERSITY_DORM', 'Elms BT9 (Queen''s Accommodation)', 'Belfast', 601.57, NULL, NULL, NULL, NULL, NULL, 'https://www.qub.ac.uk/accommodation/student-accommodation/elms-bt9/', '2026-08-31', 'Original figure: GBP 119/week (Standard room, also expressed as GBP 4,760 for a 40-week contract -- confirmed consistent: 119 x 40 = 4,760), converted to a monthly figure using the standard 52/12 weeks-per-month factor (GBP 515.67/month), then to EUR at the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28). Queen''s Accommodation describes itself as "the largest provider of purpose built managed student accommodation in Belfast," directly operating Elms BT9 -- seeded as UNIVERSITY_DORM accordingly, not a private hall. Pricier 48-week (GBP 5,712 total) and 51-week (GBP 6,069 total) contracts are also available at the same weekly rate -- not seeded as separate rows.'),
    ('4865f1cc-c6c1-4ab4-8595-0c3460f8e9ba', '50c2c93b-30c4-4649-b937-5bb42604d590', 'UNIVERSITY_DORM', 'Pendreich Way (University of Stirling)', 'Stirling', 569.47, NULL, NULL, NULL, NULL, NULL, 'https://www.stir.ac.uk/student-life/accommodation/find-your-residence/pendreich-way/', '2026-08-31', 'Original figure: GBP 112.65/week (single standard room, 49-week contract, 2026/27 session), converted to a monthly figure using the standard 52/12 weeks-per-month factor (GBP 488.15/month), then to EUR at the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28).'),
    ('c39c97e4-1ed4-4343-a719-ced786a14fb1', 'c8345875-e831-4aee-af7f-b7eebd95dcc3', 'UNIVERSITY_DORM', 'The Precinct (University of Sunderland)', 'Sunderland', 540.91, NULL, NULL, ARRAY['bills_included', 'insurance_included'], NULL, NULL, 'https://www.sunderland.ac.uk/student-life/accommodation/the-precinct', '2026-08-31', 'Original figure: GBP 107/week (Standard room, 190 available, 40 or 50-week contracts), converted to a monthly figure using the standard 52/12 weeks-per-month factor (GBP 463.67/month), then to EUR at the ECB reference rate (1 EUR = 0.8572 GBP, 2026-08-28). Rent is stated as all-inclusive (bills and insurance).');

-- Visa requirements module completion (added 2026-09-01): the 4 destination
-- countries missing from the visa_requirements table (out of the 34 seeded
-- university countries) -- USA, Australia, Greece, Slovakia. The US row was
-- previously omitted entirely in an earlier batch after its SEVIS/MRV fee
-- pages 403'd automated fetches; this batch retried via the underlying CFR/
-- Federal Register regulatory text instead of the consumer-facing
-- travel.state.gov pages, and succeeded. AUD figures converted to EUR using
-- the ECB reference rate for 2026-08-31 (1 EUR = 1.6191 AUD, the latest
-- available at time of writing) -- Greece and Slovakia are both eurozone
-- members, so no conversion was needed for those two.
--
-- Sourcing notes:
--   * USA: travel.state.gov, studyinthestates.dhs.gov, and ice.gov/sevis all
--     403'd every fetch attempt (repeat of the earlier finding). Found the
--     same facts instead in the underlying regulatory text itself: 8 CFR
--     103.7(b)(1)(ii)(H)/214.13(a) for the SEVIS I-901 fee, and 22 CFR
--     22.1 Item 21(a) for the MRV visa fee -- both via Federal Register
--     "public inspection" PDF copies of the amending final rules (the
--     canonical federalregister.gov URLs themselves redirect to a bot
--     "unblock" interstitial and were not fetchable). No fixed financial
--     proof figure exists for the US -- it's tied to each school's own
--     Form I-20, not one national number, so financial_proof_eur is left
--     NULL rather than guessed. Passport validity, processing time, and a
--     complete document checklist beyond Form I-20 could not be confirmed
--     via any fetchable official source.
--   * Australia: immi.homeaffairs.gov.au and homeaffairs.gov.au 403'd every
--     URL tried (over 10 variants). Recovered the actual current financial-
--     capacity figures directly from the primary legislative instrument
--     itself (Migration (LIN 19/198) Instrument 2019, Compilation No. 2,
--     effective 10 May 2024) via legislation.gov.au's PDF download -- this
--     is stronger sourcing than the consumer-facing visa page would have
--     been, and is NOT the same as the third-party-aggregator figures this
--     project's rules exclude, since it's the government's own enacted
--     legal text. Visa application charge, passport validity, processing
--     time, and a full document checklist could not be confirmed since the
--     visa-listing page itself was unreachable.
--   * Greece: mfa.gr 403'd every attempt. Substituted migration.gov.gr
--     (Ministry of Migration and Asylum) instead, fetching the actual
--     Joint Ministerial Decision (KYA 41712/2014) implementing Law
--     4251/2014 Article 33, plus the Ministry's own official document
--     checklist for that permit category. Financial proof is confirmed as
--     EUR 400/MONTH (not an annual/total figure like most other rows in
--     this table) -- disclosed explicitly in this row's notes to avoid a
--     misleading direct comparison with other countries' lump-sum figures.
--   * Slovakia: mzv.sk 403'd every attempt. Substituted minv.sk (Ministry
--     of Interior) and the official Slov-Lex legal portal instead, fetching
--     Act No. 404/2011 Coll. (residence of foreigners) and Act No. 145/1995
--     Coll. (administrative fees) directly, plus an official Ministry FAQ
--     PDF. No fixed minimum financial-proof euro figure exists in any
--     fetchable official document -- only the accepted proof METHODS
--     (bank statement, scholarship, sponsor guarantee) are specified, so
--     financial_proof_eur is left NULL rather than using an unconfirmed
--     56/26-EUR-per-day secondary-source figure found only via search
--     snippet. Processing time (30 days) IS confirmed directly.

INSERT INTO visa_requirements (visa_requirement_id, destination_country_code, applicant_country_code, visa_type, financial_proof_eur, estimated_processing_days, minimum_passport_validity_months, required_documents, application_url, source_url, source_checked_on, notes) VALUES
    ('e8fb7147-1c5b-4b22-b1d0-f4735faa80ac', 'US', NULL, 'STUDY_VISA', NULL, NULL, NULL, ARRAY['Form_I-20'], 'https://www.fmjfee.com/i901fee/index.htm', 'https://public-inspection.federalregister.gov/2018-15140.pdf', '2026-09-01', 'F-1/M-1 student visa. financial_proof_eur left NULL: there is no fixed national dollar figure -- the financial requirement is tied entirely to the specific school''s own Form I-20 ("Certificate of Eligibility for Nonimmigrant Student Status"), which each SEVP-certified school issues individually; confirmed by 8 CFR 103.7(b)(1)(ii)(H) footnote 2 (fetched via the Federal Register public-inspection PDF above, since the canonical federalregister.gov page itself redirects to a bot-check interstitial rather than serving content directly). Two confirmed fees, neither stored in a dedicated column since this schema has none for visa/application fees specifically: SEVIS I-901 fee USD 350 for F and M students (8 CFR 103.7(b)(1)(ii)(H) / 214.13(a)(1)) -- payable at the application_url above, which was directly confirmed reachable (DHS''s own I-901 payment portal); and the MRV (DS-160) visa application fee USD 185, which the Department of State''s own fee schedule explicitly places student visas under ("non-petition-based nonimmigrant visa (except E category)"), per 22 CFR 22.1 Item 21(a), fetched via a separate Federal Register public-inspection PDF (Doc. 2023-06290) -- I could not find a later Federal Register document changing this figure, but travel.state.gov''s own consumer-facing fee page (which would state this most currently) returned HTTP 403 to every fetch attempt, so treat as best-available rather than guaranteed-current. minimum_passport_validity_months and estimated_processing_days left NULL: no official source I could fetch stated a specific clean figure for either. The DS-160 application portal itself (ceac.state.gov/genniv/) also returned HTTP 403 and could not be independently verified this session.'),
    ('b4218f62-5d93-4bbf-895d-257d86d0099c', 'AU', NULL, 'STUDY_VISA', 18349.70, NULL, NULL, NULL, NULL, 'https://www.legislation.gov.au/F2019L01366/2024-05-10/2024-05-10/text/original/pdf', '2026-09-01', 'Subclass 500 Student visa. financial_proof_eur is the primary applicant''s annual living-cost requirement: original figure AUD 29,710/year, converted to EUR using the ECB reference rate (1 EUR = 1.6191 AUD, 2026-08-31) -- https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/eurofxref-graph-aud.en.html. Sourced directly from the actual current legislative instrument text (Migration (LIN 19/198: Evidence of financial capacity) Instrument 2019, Compilation No. 2, effective 10 May 2024, s.6(2)(b)(ii)(A)) via legislation.gov.au''s own PDF download, after immi.homeaffairs.gov.au and every other Department of Home Affairs URL tried (10+ variants) returned HTTP 403. Same instrument also specifies, but not seeded here as separate rows: AUD 10,394/year for an accompanying spouse/de facto partner, AUD 4,449/year for each dependent child, AUD 13,502/year in school fees for a school-age dependant (s.6(2)(c)(ii)/(iv)), and an alternative income-based test (a parent/spouse with AUD 87,856/year personal income if no secondary applicant, or AUD 102,500/year if there is one, per s.6(3)(b)) -- any of these forms of evidence may substitute for a bank-deposit showing under s.10. required_documents, application_url, minimum_passport_validity_months, and estimated_processing_days all left NULL/empty: the visa-listing and application pages themselves were unreachable (HTTP 403) via every direct-fetch attempt, so none of these could be confirmed from an official source this session -- the visa application charge itself is also NOT confirmed here for the same reason (only third-party figures were found, explicitly not used per this project''s sourcing rules).'),
    ('57f405f1-b7b0-4bc3-9caf-d38b7ac408fc', 'GR', NULL, 'RESIDENCE_PERMIT', 400.00, NULL, NULL, ARRAY['application_form', 'passport_photos', 'passport_copy_with_entry_visa', 'residence_permit_fee_receipt', 'health_insurance_proof', 'enrollment_or_acceptance_certificate', 'proof_of_financial_means'], 'https://migration.gov.gr/en/migration-policy/metanasteusi-stin-ellada/katigories-adeion-diamonis-politon-triton-choron-dikaiologitika/', 'https://migration.gov.gr/wp-content/uploads/2020/05/%CE%9A%CE%A5%CE%9141712_2014.pdf', '2026-09-01', 'Residence permit category "Delta 1.1" (Studies, Article 33 of Law 4251/2014), following a national "type D" entry visa. financial_proof_eur is a MONTHLY requirement, not an annual/total figure like most other rows in this table -- quoted verbatim from Joint Ministerial Decision (KYA) 41712/2014: a minimum of "400 EUR monthly" (Greece is a eurozone member, no currency conversion needed), provable via bank deposit/transfer, scholarship, or salary slip. mfa.gr (the Ministry of Foreign Affairs, which would host the national-visa consular page) returned HTTP 403 to every fetch attempt -- migration.gov.gr (Ministry of Migration and Asylum) was used instead for the residence-permit side, which is the operative long-stay status. Confirmed fee: EUR 16 residence-permit printing cost; a further electronic administrative stamp fee ("parabolo") under Article 132 of Law 4251/2014 also applies but its exact amount was not stated in the documents fetched -- left undisclosed rather than guessed. Passport validity and processing time: COULD NOT CONFIRM a specific figure for either from any document fetched.'),
    ('92bbe12c-4448-4edc-9da6-5a06de82c7b3', 'SK', NULL, 'RESIDENCE_PERMIT', NULL, 30, NULL, ARRAY['application_form', 'passport_photo', 'passport_copy', 'proof_of_purpose_of_study', 'clean_criminal_record_certificate', 'proof_of_financial_security', 'medical_certificate_within_30_days_of_permit'], NULL, 'https://www.minv.sk/swift_data/source/policia/hranicna_a_cudzinecka_policia/ocp/faq/jul_2024/14_otazka.pdf', '2026-09-01', '"Prechodny pobyt" (temporary residence) for study purposes, under Act No. 404/2011 Coll. section 24 -- a "national visa" is only the entry mechanism, valid a maximum of 90 days on its own (section 15(3)), confirmed directly from the Act''s own text (static.slov-lex.sk). mzv.sk (Ministry of Foreign and European Affairs, the national-visa consular authority) returned HTTP 403 to every fetch attempt -- minv.sk (Ministry of Interior) and the official Slov-Lex legal portal were used instead. financial_proof_eur left NULL: the official application-requirements FAQ specifies accepted proof METHODS (a 3-month bank statement, scholarship confirmation, a legal entity''s funding guarantee, or a sponsor''s affidavit plus the sponsor''s 3-month bank statement) but states no fixed minimum euro amount -- a secondary/aggregator figure of "56 EUR/day, or 26 EUR/day if accommodation is prepaid" was found only via search snippet, not corroborated in any official document fetched, and is deliberately NOT used here. estimated_processing_days (30) is directly confirmed: "the relevant Foreign Police department decides on an application for temporary residence for study purposes within 30 days of receiving the complete application." minimum_passport_validity_months left NULL: the Act only requires the passport be unexpired and legible, no minimum-months figure is legislated. Confirmed fees (Act No. 145/1995 Coll. on Administrative Fees, Items 24 and 240, via static.slov-lex.sk, not stored in a dedicated column since this schema has none for visa fees specifically): the temporary-residence-for-study application itself is EUR 0 (free); issuing the residence card once granted is EUR 6 standard or EUR 35 expedited (2 working days); optional postal delivery within Slovakia is EUR 4; the national visa fee is EUR 90 (if needed to obtain the permit) or EUR 14 (if only to collect an already-granted permit). Maximum permit validity: 6 years (section 24(2)). application_url left NULL: applications are filed in person at a consulate abroad or, if already in Slovakia, at a Foreign Police department -- no single official web application URL was confirmed.');

-- ============================================================
