INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('9398406b-1c8f-40bc-a44d-f7301dc8d189', '2fdf3f12-03d5-44be-8518-01be0b5e7645', NULL, NULL, NULL, NULL, ARRAY['high_school_diploma', 'transcript_certified_translation'], 'https://www.uaic.ro/en/international/international-students/full-degree-students/', '2026-09-01', 'Non-EU full-degree bachelor''s admission: high school diploma + transcript required; page does not state a minimum grade/CGPA or a specific language-test score, so both left NULL rather than guessed. Master''s-level admission additionally requires the bachelor''s diploma/diploma supplement (not applicable to this bachelor''s row).'),
    ('61ccdf0e-1f78-4de8-bdbc-095bf3b5f63d', 'e183ad85-af2b-4a98-bc71-1e6d5cb68427', 60.00, NULL, NULL, NULL, ARRAY['acceptance_letter', 'diploma_transcript_certified_translation', 'language_certificate', 'medical_fitness_certificate'], 'https://international.ase.ro/21/admission-for-noneu-citizen/', '2026-09-01', 'Non-EU admission requires a minimum baccalaureate average of 6 (10-point Romanian scale) for English-medium programmes, converted here to 60.00 on the schema''s 0-100 scale (6/10 * 100) -- a unit conversion, not a guess. (French-medium programmes require 8/10 = 80.00, not applicable to this English-medium row.) No specific language-test/score named on this page.'),
    ('9c824551-e3a7-4452-8450-396f9f197449', 'dc646392-3189-4186-80b1-b92a4eca18e1', NULL, NULL, 'IELTS', '6.50', ARRAY['high_school_diploma_certified_translation', 'english_proficiency_certificate', 'birth_certificate', 'passport_or_id', 'medical_certificate'], 'https://www.unitbv.ro/en/prospective-students/admission/admission-information-for-non-eu-citizens.html', '2026-09-01', 'Non-EU admission: EUR 75 non-refundable registration fee (see program_fees APPLICATION_FEE row); requires TOEFL/IELTS (min 6.50)/SAT/GRE/Cambridge certificate OR 4 years of prior English-medium instruction. 2026 application window: 20 May - 14 July 2026. No CGPA/grade-average minimum stated.'),
    ('c54d828b-aa6d-42c6-b722-ab0fafe02e0c', '07bc43a0-9d39-41e5-90e0-20ab69d8e0b5', NULL, NULL, NULL, 'B2', ARRAY['application_form', 'diploma_transcript_certified_translation', 'birth_certificate', 'passport', 'medical_certificate', 'english_proficiency_certificate'], 'https://snspa.ro/en/non-eu-students/', '2026-09-01', 'Non-EU admission requires B2-level English (TOEFL/IELTS/Cambridge; specific test not fixed by the university, so language_test_name left NULL and minimum_language_score set to the stated CEFR level "B2") unless the applicant''s prior education was English-medium. Process includes an online interview and a Letter of Acceptance before visa application; enrollment deadline October 1. No CGPA/grade-average minimum stated.'),
    ('360c8755-90ff-4cef-9438-852eb6acfa61', 'f362d356-970f-4204-bc20-71b9cdd30d91', NULL, NULL, NULL, NULL, ARRAY['baccalaureate_diploma_certified_translation'], 'https://kv.sapientia.ro/en/admission/study-programs/law', '2026-09-01', 'Requires the baccalaureate diploma plus a RON 150 application fee and RON 70 registration fee (see program_fees APPLICATION_FEE row for the EUR-converted application fee; the RON 70 registration fee is not separately stored since this schema has no fee_type for it). Civic/criminal/procedural law courses are taught in Romanian; remaining courses in Hungarian -- this is a bilingual, not English-taught, programme. No CGPA/grade-average minimum or language-test score stated.');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('5fd2982d-f31d-45f2-8003-d95cde0d57f8', '2fdf3f12-03d5-44be-8518-01be0b5e7645', 'TUITION_PER_YEAR', 'INTERNATIONAL', 2070.00, 'https://www.uaic.ro/en/international/international-students/full-degree-students/', '2026-09-01', 'Low end of the published non-EU bachelor''s tuition range (EUR 2,070-3,500/year across FEAA bachelor''s programmes); the page does not break the fee down per individual programme, so EUR 2,070 is the confirmed floor for this programme category, not a programme-specific figure.'),
    ('90622f94-ba9f-4c6f-b3b5-17525cf74d77', 'e183ad85-af2b-4a98-bc71-1e6d5cb68427', 'TUITION_PER_YEAR', 'INTERNATIONAL', 3500.00, 'https://international.ase.ro/21/admission-for-noneu-citizen/', '2026-09-01', 'Non-EU tuition for the 2026-2027 academic year, as explicitly published (bachelor level).'),
    ('3bb3bf3d-b941-4066-8faf-44c82550a053', 'e183ad85-af2b-4a98-bc71-1e6d5cb68427', 'APPLICATION_FEE', 'INTERNATIONAL', 350.00, 'https://international.ase.ro/21/admission-for-noneu-citizen/', '2026-09-01', 'Non-EU registration fee, 2026-2027 academic year, in addition to the EUR 3,500 annual tuition.'),
    ('de33b677-d54c-4bf3-bbd7-aa9331316c7a', 'dc646392-3189-4186-80b1-b92a4eca18e1', 'TUITION_PER_YEAR', 'INTERNATIONAL', 2500.00, 'https://www.unitbv.ro/en/international-students/tuition-fee.html', '2026-09-01', 'Non-EU tuition for the Mathematics/Computer Science field. Page displayed an academic-year label of 2025-2026 at fetch time rather than a clearly updated 2026-2027 figure -- flagging this ambiguity rather than assuming the rate is unchanged.'),
    ('3ba05386-f0a8-4ed2-b5bd-d93ed9524082', 'dc646392-3189-4186-80b1-b92a4eca18e1', 'APPLICATION_FEE', 'INTERNATIONAL', 75.00, 'https://www.unitbv.ro/en/prospective-students/admission/admission-information-for-non-eu-citizens.html', '2026-09-01', 'Non-refundable non-EU registration fee.'),
    ('189ac7ff-cbe5-4378-bada-77335a539d6d', '07bc43a0-9d39-41e5-90e0-20ab69d8e0b5', 'TUITION_PER_YEAR', 'INTERNATIONAL', 1980.00, 'https://snspa.ro/en/non-eu-students/', '2026-09-01', 'Non-EU tuition, master''s level.'),
    ('1edb1f61-de9f-4348-985b-a8318c64eda1', 'f362d356-970f-4204-bc20-71b9cdd30d91', 'TUITION_PER_YEAR', 'INTERNATIONAL', 550.00, 'https://kv.sapientia.ro/en/admission/study-programs/law', '2026-09-01', 'Non-EU/foreign-track annual tuition for Law at the Cluj-Napoca (Miercurea Ciuc administrative) campus. Note: the university''s general domestic fee table separately lists Law at RON 2,250/year (≈ EUR 428.02 at 1 EUR = 5.2567 RON, 2026-09-01 ECB rate) -- the site does not reconcile these two figures, likely reflecting separate EU/domestic vs. non-EU/foreign tracks; both are disclosed here but only the EUR 550 non-EU figure is stored, matching this row''s INTERNATIONAL student_category.'),
    ('56ef3bb5-9ed4-42ca-b7d8-cdadd12a3b8f', 'f362d356-970f-4204-bc20-71b9cdd30d91', 'APPLICATION_FEE', 'INTERNATIONAL', 28.54, 'https://kv.sapientia.ro/en/admission/study-programs/law', '2026-09-01', 'RON 150 application fee, converted at 1 EUR = 5.2567 RON (ECB reference rate, 2026-09-01): 150 / 5.2567 = EUR 28.54. A separate RON 70 registration fee also applies and is not stored (no matching fee_type).');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('57cebcf2-8ec6-4922-a797-cdeea81569b3', '5b9dbe78-1bef-4c3f-a456-b8af94ed962d', 'UNIVERSITY_DORM', 'Alexandru Ioan Cuza University of Iași', 'Iași', 110.33, NULL, NULL, NULL, 'https://www.uaic.ro/en/international/erasmus-programme/erasmus-incoming-students/cost-living/', NULL, 'https://www.uaic.ro/en/international/erasmus-programme/erasmus-incoming-students/cost-living/', '2026-09-01', '2025-2026 rate for the "C5" dormitory (RON 580/month), converted at 1 EUR = 5.2567 RON (ECB reference rate, 2026-09-01): 580 / 5.2567 = EUR 110.33. Higher-tier "Gaudeamus" dormitory is RON 885/month (≈ EUR 168.34) -- not stored separately here. No deposit or distance-to-campus figure published. University states roughly EUR 600/month is enough for decent overall living costs in Iași (not accommodation-specific).'),
    ('defa27dc-bd34-45cb-8c2c-5e94addbc9d2', 'e9680bb7-2e63-4fa4-88cf-54dea9977859', 'UNIVERSITY_DORM', 'Sapientia Hungarian University of Transylvania', 'Cluj-Napoca', 112.24, NULL, NULL, NULL, 'https://kv.sapientia.ro/en/admission/dormitory', NULL, 'https://kv.sapientia.ro/en/admission/dormitory', '2026-09-01', '2026-2027 rate for a 1-bed room at the dormitory (1 Ponorului Street), RON 590/month including rent + utilities, converted at 1 EUR = 5.2567 RON (ECB reference rate, 2026-09-01): 590 / 5.2567 = EUR 112.24. Other room configurations range RON 450-590/month -- not stored separately here. No deposit or distance-to-campus figure published.');

-- ============================================================
-- Hungary depth batch (2026-09-01): 5 more universities distinct from the
