INSERT INTO admission_requirements (requirement_id, program_id, minimum_cgpa_percentage, official_funds_requirement_eur, language_test_name, minimum_language_score, required_documents, source_url, source_checked_on, notes) VALUES
    ('0453b2a9-5fb3-45dd-b71b-ec86d47f3ea5', '2f03cc7e-6eaf-4b76-a51f-8b32663448e1', NULL, NULL, 'IELTS', '6.0', ARRAY['bachelor_transcript_min_60_ects', 'english_proficiency_certificate'], 'https://eco.u-szeged.hu/english/training-programmes/programmes-for-international-students/international-economy-and-business-administration-ma/admission/requirements/admission-requirements/admission-requirements', '2026-09-01', 'Requires a minimum of 60 ECTS credits during the Bachelor''s degree in specified fields (Methodology, Economics, Business, Social Sciences). Non-EU applicants need a B2 English certificate (IELTS 6.0 or TOEFL 95 -- IELTS stored here, TOEFL 95 as the alternative accepted score). EU applicants instead sit an oral entrance exam. No CGPA/grade-average minimum stated.'),
    ('769ea98f-ef99-47f6-89ee-3d357dd02f56', '1dcfd232-0d90-418d-bfe4-52e41f1d00c2', NULL, NULL, NULL, NULL, NULL, 'https://semmelweis.hu/admission/2025/04/16/fees-and-costs-of-the-application-and-enrollment-procedure-5/', '2026-09-01', 'Specific admission criteria (documents, language test, prior degree requirements) for the Centre for Translational Medicine MSc were not stated on the fees/costs page fetched, and no separate admissions-requirements page for this specific programme was found -- left unconfirmed rather than guessed. Confirmed instead: EUR 75 admission/application fee (see program_fees), and a 50% tuition discount for Semmelweis alumni/current students.'),
    ('ee20f0e9-845e-47bf-ad75-0ba304b59c21', '2b8110f5-4da3-4265-afe3-8dba0480e578', NULL, NULL, NULL, 'B2', ARRAY['secondary_school_certificate', 'english_proficiency_certificate'], 'https://www.gtk.uni-pannon.hu/en/for-international-applicants/', '2026-09-01', 'Requires completed secondary school and a B2-level English certificate (TOEFL/IELTS/ESOL/BEC/ECL/PTE/FCE/CAE/TELC/TOEIC/Euroexam all accepted -- no single test fixed, so language_test_name left NULL and the CEFR level "B2" stored instead). EUR 150 non-refundable registration fee covers the first 2 semesters'' tuition before the Letter of Admission is issued (see program_fees APPLICATION_FEE row). No CGPA/grade-average minimum stated.'),
    ('faf7b5f4-c867-4349-83ff-ae0449d32767', 'ad2ebb1a-88b5-4528-b792-028ed4659cce', NULL, NULL, 'IELTS', '5.5', ARRAY['notarized_secondary_school_certificate', 'english_proficiency_certificate'], 'https://admissions.sze.hu/application-information', '2026-09-01', 'Requires a notarized secondary school certificate (with Mathematics evidence, given the business field) and B2-level English (TOEFL 513 / IELTS 5.5 / TOEFL iBT 66 -- IELTS stored here, others as accepted alternatives). EUR 100 application fee (see program_fees); a further EUR 130 one-month accommodation fee is due, alongside tuition for the first 2 semesters, before the Letter of Admission is issued -- not stored as a separate fee_type since this schema has none for a one-off accommodation deposit. No CGPA/grade-average minimum stated.'),
    ('55fa2143-c8a3-4fe7-88d1-252bacf94ecc', '8d2a3268-d4f2-49d3-bfac-6619816bbf72', NULL, NULL, 'IELTS', '5.5', ARRAY['passport_copy', 'motivation_letter', 'cv', 'english_proficiency_certificate', 'notarized_secondary_school_report'], 'https://uni-obuda.hu/required-documents/', '2026-09-01', 'Requires a passport copy, motivation letter, CV, notarized secondary school report referencing Mathematics/Physics/English study, a GCE or equivalent diploma, and English proficiency (TOEFL iBT 72 / IELTS 5.5 -- IELTS stored here; Duolingo explicitly NOT accepted per this page). EUR 150 mandatory application fee applies to every application regardless of outcome (see program_fees). No CGPA/grade-average minimum stated.');

INSERT INTO program_fees (fee_id, program_id, fee_type, student_category, amount_eur, source_url, source_checked_on, notes) VALUES
    ('5f54f044-0f70-440c-b3b6-78d54abd02a8', '2f03cc7e-6eaf-4b76-a51f-8b32663448e1', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 3000.00, 'https://eco.u-szeged.hu/english/training-programmes/programmes-for-international-students/international-economy-and-business-administration-ma/admission/fees/fees', '2026-09-01', 'Non-EU tuition, 2026/2027 academic year. Published directly in EUR, no conversion needed.'),
    ('ce43a805-b543-4bfa-8ba9-4022ff442a6c', '2f03cc7e-6eaf-4b76-a51f-8b32663448e1', 'APPLICATION_FEE', 'INTERNATIONAL', 200.00, 'https://eco.u-szeged.hu/english/training-programmes/programmes-for-international-students/international-economy-and-business-administration-ma/admission/fees/fees', '2026-09-01', 'Non-EU entrance-exam fee. EU applicants pay HUF 9,000 instead (≈ EUR 24.53 at 1 EUR = 366.71 HUF, ECB rate 2026-09-01) -- not stored separately since this row is INTERNATIONAL category.'),
    ('92a8aee0-d60e-4ee6-9bf0-0fc287d58523', '1dcfd232-0d90-418d-bfe4-52e41f1d00c2', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 12000.00, 'https://semmelweis.hu/admission/2025/04/16/fees-and-costs-of-the-application-and-enrollment-procedure-5/', '2026-09-01', 'Published directly in EUR, no conversion needed. Page alternatively quotes EUR 22,000/academic year (a slight discount vs. 2x the per-semester rate) -- both figures disclosed, per-semester amount stored here. A 50% discount applies for Semmelweis alumni/current students.'),
    ('21249752-fe42-44a5-bb3f-a1a9674dd437', '1dcfd232-0d90-418d-bfe4-52e41f1d00c2', 'APPLICATION_FEE', 'INTERNATIONAL', 75.00, 'https://semmelweis.hu/admission/2025/04/16/fees-and-costs-of-the-application-and-enrollment-procedure-5/', '2026-09-01', 'Admission/application fee, published directly in EUR.'),
    ('6919ce4d-5461-43e2-ba34-54a0ded390e1', '2b8110f5-4da3-4265-afe3-8dba0480e578', 'TUITION_PER_YEAR', 'EU', 3750.00, 'https://www.gtk.uni-pannon.hu/en/ba-in-business-administration-and-management/', '2026-09-01', 'EU-citizen tuition, published directly in EUR (2 semesters/academic year), no conversion needed.'),
    ('d31748a1-e566-4c2e-ac17-a8f8e2488fd3', '2b8110f5-4da3-4265-afe3-8dba0480e578', 'TUITION_PER_YEAR', 'INTERNATIONAL', 4000.00, 'https://www.gtk.uni-pannon.hu/en/ba-in-business-administration-and-management/', '2026-09-01', 'Non-EU tuition, published directly in EUR, no conversion needed.'),
    ('330d03a5-535a-43e9-a6d7-e6620ca4d883', '2b8110f5-4da3-4265-afe3-8dba0480e578', 'APPLICATION_FEE', 'INTERNATIONAL', 150.00, 'https://www.gtk.uni-pannon.hu/en/for-international-applicants/', '2026-09-01', 'Non-refundable registration fee; covers the first 2 semesters'' tuition before the Letter of Admission is issued.'),
    ('12413cff-133d-46cf-b794-667d91d6d1d7', 'ad2ebb1a-88b5-4528-b792-028ed4659cce', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 1700.00, 'https://admissions.sze.hu/bachelor-of-business-administration-and-management-bsc-', '2026-09-01', '7-semester (210-credit), English-taught programme. Published directly in EUR, no conversion needed.'),
    ('8986b88a-6468-40f7-af2b-67e14f06a09b', 'ad2ebb1a-88b5-4528-b792-028ed4659cce', 'APPLICATION_FEE', 'INTERNATIONAL', 100.00, 'https://admissions.sze.hu/application-information', '2026-09-01', 'Per-application fee, published directly in EUR.'),
    ('16dca883-abf5-4d80-a15b-f94a366eaf7a', '8d2a3268-d4f2-49d3-bfac-6619816bbf72', 'TUITION_PER_SEMESTER', 'EU', 2000.00, 'https://uni-obuda.hu/tuition-fees/', '2026-09-01', 'EU/EEA-citizen tuition, published directly in EUR, no conversion needed.'),
    ('64946713-7393-4f51-b4c6-6944b27eb5f3', '8d2a3268-d4f2-49d3-bfac-6619816bbf72', 'TUITION_PER_SEMESTER', 'INTERNATIONAL', 2900.00, 'https://uni-obuda.hu/tuition-fees/', '2026-09-01', 'Non-EEA-citizen tuition, published directly in EUR, no conversion needed.'),
    ('80709f26-ed54-4c10-ab84-0d0435d52ff5', '8d2a3268-d4f2-49d3-bfac-6619816bbf72', 'APPLICATION_FEE', 'INTERNATIONAL', 150.00, 'https://uni-obuda.hu/tuition-fees/', '2026-09-01', 'Mandatory, non-refundable application fee applying to every application regardless of outcome, published directly in EUR.');

INSERT INTO scholarships (scholarship_id, name, provider, country_code, university_id, program_id, coverage_type, amount_eur, eligibility_notes, application_deadline, application_url, source_url, source_checked_on) VALUES
    ('a7064ad6-ab29-4e30-a32e-038e41e482fa', 'Semmelweis Pannonia In Excellence Scholarship', 'Semmelweis University', 'HU', '4756b39b-f3f1-413e-bb64-589f46055916', NULL, 'PARTIAL_TUITION', 5453.90, 'Merit-based scholarship for students in English/German-taught programmes. Faculty of Medicine and Dentistry: HUF 2,000,000/year (stored here, converted at 1 EUR = 366.71 HUF, ECB rate 2026-09-01: 2,000,000 / 366.71 = EUR 5,453.90). Other faculty tiers not stored as separate rows: Pharmaceutical Sciences HUF 1,300,000/year (≈ EUR 3,545), Health Sciences HUF 900,000/year (≈ EUR 2,454), András Pető Faculty HUF 2,900,000/year (≈ EUR 7,909) -- see notes for full detail. University-wide, not tied to the CTM MSc programme seeded above.', NULL, 'https://semmelweis.hu/registrar/information/scholarships/semmelweis-pannonia-in-excellence-scholarship/', 'https://semmelweis.hu/registrar/information/scholarships/semmelweis-pannonia-in-excellence-scholarship/', '2026-09-01'),
    ('2a21f4b0-4eb6-4cae-91cc-c806f57742c2', 'Széchenyi ODA Grant (SODA)', 'Széchenyi István University', 'HU', '50e47956-b6b8-404c-9f77-0daeb604b908', NULL, 'PARTIAL_TUITION', NULL, 'For citizens of OECD-listed ODA recipient countries. Covers a 90% refund of the first two semesters'' tuition, a 90% refund during the official study period (30% after), free dormitory accommodation, and free basic healthcare. 10 grants available for 2026/2027 (5 BSc + 5 MSc places). amount_eur left NULL: this is a percentage-based refund/discount scheme, not a fixed award amount, so no single EUR figure can be stated without guessing which tuition tier it applies to.', NULL, 'https://admissions.sze.hu/soda-scholarship', 'https://admissions.sze.hu/soda-scholarship', '2026-09-01');

INSERT INTO student_accommodations (accommodation_id, university_id, accommodation_type, provider_name, city, monthly_rent_eur, deposit_eur, distance_to_university_km, amenities, application_url, contact_email, source_url, source_checked_on, notes) VALUES
    ('e676833f-0109-49f0-baaf-f306ab9a977d', '34d46693-bdc3-46ab-a277-53b442fe76c0', 'UNIVERSITY_DORM', 'University of Pannonia', 'Veszprém', 177.25, NULL, NULL, NULL, 'https://kollegiumok.uni-pannon.hu/en/dormitory-fee/dormitory-payment-veszprem', NULL, 'https://kollegiumok.uni-pannon.hu/en/dormitory-fee/dormitory-payment-veszprem', '2026-09-01', '2026/2027 rate for a 2-bed room at Magister Dormitory, HUF 65,000/month/person, converted at 1 EUR = 366.71 HUF (ECB reference rate, 2026-09-01): 65,000 / 366.71 = EUR 177.25 (the site''s own rounded conversion states ≈ EUR 186, using a slightly different rate -- both disclosed). Other options: 2x2-bed room HUF 61,500/month (≈ EUR 167.68 ECB), Central Dormitory HUF 58,000/month (≈ EUR 158.16 ECB). Stipendium Hungaricum scholarship holders pay reduced rates (e.g. Magister 2-bed HUF 25,000/month ≈ EUR 68.17 ECB; Central Dormitory fully covered) -- not stored separately. No deposit or distance-to-campus figure published.');
